(window.GIM_TS=window.GIM_TS||{})["Gittin.3"]={"from":72,"a":[["\u0003ולא הם,\u0004 הגויים, \u0003קונים\u0004 אחד \u0003מכם\u0004 שאין להם זכות קניינית בכם, \u0003ולא הם קונים זה מזה. יכול לא יקנו זה את זה?\u0004 ולפני שמשיבים לשאלה, תוהים: \u0003יכול לא יקנו זה את זה?!\u0004 מה טיבה של שאלה זו? \u0003האמרת\u0004 \u0005[הרי\u0006 כבר \u0005אמרת]:\u0006 \u0003לא הם קונים זה מזה!\u0004 אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ולא הם קונים זה מזה לגופו,\u0004 שאין לגוי זכות בגופו של העבד.","ומעתה נשאלת השאלה: \u0003יכול לא יקנו זה את זה\u0004 כעבדים גם \u0003ל\u0004ענין הזכות ב\u0003מעשה ידיו?\u0004 ועל כך משיבים: \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003קל וחומר:\u0004 אם \u0003גוי\u0004 את \u0003ישראל קונה\u0004 למעשה ידיו כפי שמפורש בתורה (ראה ויקרא כה, מז) — \u0003גוי\u0004 את ה\u0003גוי לא כל שכן\u0004 שקונה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בכספא\u0004 \u0005[ב\u0006קנין \u0005כסף]\u0006 שבכוחו יכול גוי לקנות גוי למעשה ידיו, \u0003אבל בחזקה,\u0004 בכוח, על ידי נטילה בשבי, \u0003לא! אמר רב פפא: עמון ומואב טהרו בסיחון\u0004 שעל ידי כיבושו של סיחון פסק שטח זה להיחשב כשייך לעמון ולמואב והותר לישראל, ובאותו אופן קונה השבאי את העבד.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ש\u0003גוי\u0004 יכול לקנות \u0003גוי\u0004 על ידי כיבוש שהוא החזקה. \u0003גוי\u0004 את \u0003ישראל מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא גם כן קונה כעבד בחזקה של כיבוש? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004וישמע הכנעני... וילחם בישראל \u0003וישב ממנו שבי\"\u0004 (במדבר כא, א). משמע שאף ישראל נקנה על ידי גוי כשבוי על ידי חזקה (מלחמה).","\u0003אמר רב שמן בר אבא אמר ר' יוחנן: עבד שברח מבית האסורים\u0004 — \u0003יצא\u0004 בכך \u0003לחירות\u0004 ואינו משועבד עוד לאדוניו, שמן הסתם כבר נתייאש ממנו. \u0003ולא עוד אלא שכופין את רבו וכותב לו גט\u0004 (שטר) \u0003שיחרור,\u0004 שכיון שהעבד נעשה בן חורין מן הדין, מכריחים את אדוניו לכתוב לו שטר שיחרור כדי שיוכל לשאת בת ישראל.","ומביאים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר:\u0004 עבד שפדאוהו מן השבי \u0003בין כך ובין כך ישתעבד. ואמר רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתנו\u0004 — \u0003הלכה כמותו, חוץ מ\u0004שלשה דינים: בענין אחריותו של \u0003ערב, ו\u0004במעשה שאירע בעיר \u0003צידן, ו\u0004במחלוקתו בדין \u0003ראיה,\u0004 בהלכה ה\u0003אחרונה.\u0004 ולפי זה הלכה כמותו גם במשנתנו שאינה בכלל אותן שלוש הלכות. הרי לפנינו סתירה בין שני פסקיו של ר' יוחנן.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי, מוקי לה להאי\u0004 \u0005[מעמיד את זו]\u0006 את משנתנו, שפסק בה רבן שמעון בן גמליאל שישתעבד — במקרה שהיה זה \u0003לפני יאוש\u0004 ולכן אין העבד משוחרר בפדיונו, ובזה הלכה כרבן שמעון בן גמליאל. \u0003והאי\u0004 \u0005[וזה]\u0006 שאמר ר' יוחנן לגבי עבד שברח מבית האסורים שיצא לחירות — \u0003לאחר יאוש,\u0004 ואין סתירה בין שתי הלכות אלו של ר' יוחנן.","\u0003אלא ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר\u0004 שגם משנתנו מדברת \u0003לאחר יאוש,\u0004 אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יוחנן\u0004 על דברי \u0003ר' יוחנן,\u0004 שהרי לפי זה פוסק כנגד רבן שמעון בן גמליאל, שלפי דבריו של ר' יוחנן עצמו, הלכה כמותו!","ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא: טעמא\u0004 \u0005[טעם\u0006 הדבר\u0005]\u0006 שאין העבד שנפדה משתחרר \u0003מאי\u0004 \u0005[מהו]\u0006 — \u0003משום\u0004 החשש שאמר \u0003חזקיה,\u0004 שאם יהא הדין כן יבואו עבדים למסור (להפיל) את עצמם לשבי בידי גייסות נכריים, אבל המקרה שלנו שהעבד \u0003בורח\u0004 מבית האסורים \u0003שאני\u0004 \u0005[שונה]\u0006 ואין בו מקום לחשש זה של חזקיה, שכן \u0003השתא לקטלא מסר נפשיה\u0004 \u0005[עכשיו\u0006 אנו רואים ש\u0005למוות\u0006 הוא מוכן \u0005למסור\u0006 את \u0005עצמו],\u0006 שהרי אם יתפסוהו ימיתו אותו על שברח מבית הסוהר, וכי אתה צריך עוד לחשוש שמא \u0003אפולי אפיל נפשיה\u0004 \u0005[יפיל את עצמו]\u0006 מתחילה לשבי \u0003לגייסות?!\u0004","מסופר: \u0003אמתיה\u0004 \u0005[שפחתו]\u0006 של \u0003מר שמואל אשתבאי\u0004 \u0005[נשבתה].\u0006 \u0003פרקוה לשום אמהתא\u0004 \u0003ושדרוה ליה\u0004 \u0005[פדו אותה לשם שפחות ושלחו אותה לו]\u0006 ועוד \u0003שלחו ליה\u0004 \u0005[לו]\u0006 הודעה זו: \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל סבירא לן\u0004 \u0005[סבורים אנו],\u0006 ולדעתנו שבכל מקרה צריכה היא לחזור לשיעבודה אצלך. \u0003את אי נמי כרבנן סבירא לך\u0004 \u0005[אתה אם גם כן כ\u0006דעת \u0005חכמים\u0006 במשנה \u0005סבור אתה]\u0006 תדע לך ש\u0003אנן לשום אמהתא פרקינן לה ניהלה\u0004 \u0005[אנו לשם שפחות פדינו אותה]\u0006 ובמקרה כזה, אף לדעת חכמים הריהי משועבדת לך.","ומוסיפים: \u0003ואינהו סבור\u0004 \u0005[והם חשבו]\u0006 ש\u0003לפני יאוש הוה\u0004 \u0005[היה]\u0006 הדבר, \u0003ולא היא,\u0004 אלא \u0003לאחר יאוש הוה\u0004 \u0005[היה],\u0006 \u0003ושמואל\u0004 כשקיבל את השפחה \u0003לא מיבעיא דאשתעבודי\u0004 \u0005[נצרכה\u0006 לומר \u0005שלהשתעבד]\u0006 הוא \u0003לא משתעבד\u0004 \u0003בה, אלא גיטא דחירותא נמי\u0004 \u0005[שטר שיחרור גם כן]\u0006 \u0003לא אצרכה\u0004 \u0005[הצריך אותה],\u0006 שלדעתו היתה בת חורין גמורה.","ומעירים: בענין זה \u0003שמואל לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: המפקיר עבדו יצא\u0004 העבד מיד \u0003לחירות, ו\u0004אף \u0003אינו צריך גט\u0004 (שטר) \u0003שיחרור, שנאמר: \"וכל עבד איש מקנת כסף\"\u0004 (שמות יב, מד), והשאלה היא: מה טעם תוספת ההדגשה במילים \"עבד איש\"? מדוע לא נאמר רק \"עבד\", וכי הכוונה לומר \u0003\"עבד איש\" ולא \"עבד אשה\"? אלא\u0004 מטרת ההדגשה היא אחרת, ללמדנו: \u0003עבד שיש לו רשות לרבו עליו,\u0004 ש\"עבד איש\" משמעו — עבדו של אדם מסויים — הוא \u0003קרוי עבד, שאין לו רשות לרבו עליו\u0004 — ממילא \u0003אין קרוי עבד\u0004 והוא משוחרר גמור. ואותה שפחה, משעה שנתייאש שמואל ממנה — כבר יצאה מרשותו, ואינה צריכה אף לשטר שיחרור.","מסופר: \u0003אמתיה\u0004 \u0005[שפחתו]\u0006 של \u0003ר' אבא בר זוטרא אישתבאי\u0004 \u0005[נשבתה],\u0006 \u0003פרקה ההוא תרמודאה לשום איתתא\u0004 \u0005[פדה אותה\u0006 גוי \u0005תרמודי אחד לשם אשה]\u0006 כדי לשאת אותה. \u0003שלחו\u0004 חכמים \u0003ליה לדידיה\u0004 \u0005[לו]\u0006 לר' אבא בר זוטרא: \u0003אי יאות עבדת שדר לה גיטא דחירותא\u0004 \u0005[אם כראוי אתה\u0006 רוצה \u0005לעשות, שלח לה שטר שיחרור].\u0006","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר כאן]?\u0006 \u0003אי דמצו פרקי לה\u0004 \u0005[אם שיכולים לפדות אותה],\u0006 \u0003למה לי גיטא דחירותא\u0004 \u0005[שטר שיחרור]?\u0006 שיפדוה לשם שפחות! \u0003אי דלא מצו פרקי לה\u0004 \u0005[אם שאינם יכולים לפדות אותה],\u0006 \u0003כי שדר לה גיטא דחירותא מאי הוי\u0004 \u0005[כאשר ישלח לה שטר שיחרור מה יהיה]?\u0006 מה יועיל הדבר? והרי היא מצויה עתה ביד אותו גוי!","ומשיבים: \u0003לעולם\u0004 מדובר \u0003דמצו פרקי לה\u0004 \u0005[שיכולים לפדות אותה],\u0006 \u0003וכיון דמשדר\u0004 \u0005[שישלח]\u0006 \u0003לה גיטא דחירותא\u0004 \u0005[שטר שיחרור],\u0006 \u0003חבורי מחברי אהדדי ופרקי לה\u0004 \u0005[יתחברו\u0006 תושבי העיר \u0005זה עם זה ויפדו אותה]\u0006 אבל לא היו רוצים לפדות אותה רק לשם שפחות. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 אחרת: \u0003לעולם\u0004 מדובר ש\u0003לא מצו פרקי לה\u0004 \u0005[יכלו לפדות אותה],\u0006 \u0003וכיון דמשדר\u0004 \u0005[ששולח]\u0006 \u0003לה גיטא דחירותא\u0004 \u0005[שטר שיחרור],\u0006 על ידי כך היא \u0003מיתזלא באפיה\u0004 \u0005[מזדלזלת בעיניו]\u0006 של הגוי שפדה אותה לשם נישואין, שהוא יודע שהיא שפחה, \u0003ומפריק לה\u0004 \u0005[ומאפשר לה להיפדות].\u0006 ומקשים: והאם במקרה זה יהא קל לפדות אותה?","\u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003חביבה להן\u0004 על הגויים \u0003בהמתן של ישראל יותר מנשותיהן\u0004 שלהם, ואם כן זה שהיתה שפחה של ישראל אינו בזוי בעיניהם! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בדברים שנעשים \u0003בצינעא, אבל בפרהסיא זילא בהו מילתא\u0004 \u0005[מזולזל בהם הדבר]\u0006 ולא היה נושא לו לאשה שפחה.","מסופר: \u0003ההיא אמתא דהות\u0004 \u0005[שפחה אחת שהיתה]\u0006 \u0003בפומבדיתא, דהוו קא מעבדי בה אינשי איסורא\u0004 \u0005[שהיו עושים בה אנשים איסור\u0006 זנות\u0005],\u0006 שלא יכול היה אדוניה לשומרה מפניהם. \u0003אמר אביי: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר רב יהודה אמר שמואל: כל המשחרר עבדו עובר בעשה, הוה כייפנא ליה למרה\u0004 \u0005[הייתי כופה את אדוניה],\u0006 \u0003וכתיב\u0004 \u0005[והיה כותב]\u0006 ונותן \u0003לה גיטא דחירותא\u0004 \u0005[שטר שיחרור].\u0006 \u0003רבינא אמר: כי הא\u0004 \u0005[\u0006במקרה \u0005כגון זה]\u0006 \u0003מודה רב יהודה\u0004 שמותר הדבר לשחרר, \u0003משום מילתא דאיסורא\u0004 \u0005[דבר איסור]\u0006 שנכשלים בה בני אדם.","ושואלים: \u0003ואביי,\u0004 האם סבור הוא שגם \u0003משום איסורא\u0004 \u0005[איסור]\u0006 \u0003לא\u0004 יספיק טעם זה כדי לשחרר אותה? \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב חנינא בר רב קטינא אמר ר' יצחק: מעשה באשה אחת ש\u0004היתה \u0003חציה שפחה וחציה בת חורין,\u0004 שהיתה שייכת לשני אדונים ושוחררה על ידי אחד מהם,"],["\u0003וכפו את רבה\u0004 (אדוניה) \u0003ועשאה בת חורין, ואמר רב נחמן בר יצחק\u0004 כהסבר מדוע כפו אותו לעשות כן: \u0003מנהג הפקר\u0004 (זנות) \u0003נהגו בה\u0004 אנשים. משמע שמשום שהיא גורמת לאיסור מותר לשחרר אותה!","ודוחים: \u0003הכי השתא\u0004 \u0005[וכי כך הוא\u0006 הדבר\u0005]\u0006 כיצד אתה משווה?! \u0003התם\u0004 \u0005[שם]\u0006 כשהיתה חציה שפחה \u0003לא לעבד חזיא\u0004 \u0005[\u0006היא \u0005ראויה]\u0006 להינשא \u0003ולא לבן חורין חזיא\u0004 \u0005[\u0006היא \u0005ראויה],\u0006 ומשום כך מובן מדוע היא מפקירה את עצמה, ואין אפשרות לפתור את הדבר בדרך אחרת אלא בכך שישחררוה. \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אפשר\u0004 לאדון \u0003דמיחד לה לעבדיה ומנטר לה\u0004 \u0005[שייחד אותה,\u0006 את השפחה הזו \u0005לעבדו וישמור אותה]\u0006 העבד מפני האנשים לבל יעשו עימה איסורים, ולא צריך הוא לשחררה בשל כך.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה שהזכרנו \u0003אמר רב יהודה אמר שמואל: כל המשחרר עבדו עובר ב\u0004מצות \u0003עשה, שנאמר: \"לעלם בהם תעבדו\"\u0004 (ויקרא כה, מו), וזו מצות עשה שצריך לעבוד בעבדים כל ימי חייהם, ולכן אסור לשחררם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003מעשה בר' אליעזר שנכנס בבית הכנסת\u0004 להתפלל \u0003ולא מצא עשרה\u0004 אנשים שיש בהם כדי מנין לתפילה בציבור, \u0003ושחרר\u0004 את \u0003עבדו והשלימו לעשרה,\u0004 משמע שמותר לשחרר עבד! ומשיבים: לצורך \u0003מצוה שאני\u0004 \u0005[שונה]\u0006 הדבר, שמשום מצוה של תפילה בעשרה מותר לעשות דבר זה.","על כך מקשים ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"לעולם בהם תעבדו\"\u0004 — הרי זו \u0003רשות,\u0004 אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: חובה\u0004 היא. \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003ר' אליעזר סבר לה\u0004 \u0005[סבור]\u0006 \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003רשות,\u0004 וממילא אין להוכיח מכאן — לשיטת הסבורים שאסור לשחרר עבד — שמותר לשחרר משום מצוה!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר שכך סובר ר' אליעזר, \u0003דתניא בהדיא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא \u0005במפורש]\u0006 בענין זה, ש\u0003ר' אליעזר אומר:\u0004 \"לעולם בהם תעבודו\" — \u0003חובה\u0004 הוא.","ובאותו ענין \u0003אמר רבה: בהני תלת מילי\u0004 \u0005[ב\u0006גלל \u0005שלושה דברים אלה]\u0006 \u0003נחתי\u0004 \u0005[יורדים,\u0006 מתרוששים\u0005]\u0006 \u0003בעלי בתים מנכסיהון\u0004 \u0005[מנכסיהם]:\u0006 \u0003דמפקי עבדייהו לחירותא\u0004 \u0005[שמוציאים\u0006 את \u0005עבדיהם לחירות],\u0006 \u0003ודסיירי נכסייהו בשבתא\u0004 \u0005[ושמסיירים\u0006 ובודקים \u0005נכסיהם בשבת],\u0006 \u0003ודקבעי סעודתייהו בשבתא בעידן בי מדרשא\u0004 \u0005[ושקובעים סעודתם בשבת בזמן בית המדרש]\u0006 ועל ידי כך נמנעים מלבוא לשמוע את הדרשה, וכפי ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: שתי משפחות היו בירושלים, אחת קבעה סעודתא בשבתא\u0004 \u0005[סעודה בשבת]\u0006 \u0003ואחת קבעה סעודתא\u0004 \u0005[סעודה]\u0006 \u0003בערב שבת, ושתיהן נעקרו,\u0004 אחת משום ביטול בית המדרש, והשניה משום שעל ידי סעודה זו נכנסו לשבת כשהם שבעים ולא יכלו לאכול את סעודת השבת לתיאבון.","\u0003אמר רבה אמר רב: המקדיש עבדו יצא לחירות\u0004 ומסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003גופיה\u0004 \u0005[גופו]\u0006 של העבד \u0003לא קדיש\u0004 \u0005[קדוש]\u0006 שהרי הוא אינו יכול להתקדש בקדושת הגוף כקרבן. ואף שיהיה העבד קדוש רק \u0003לדמי\u0004 \u0005[לדמים,\u0006 למחירו\u0005]\u0006 \u0003לא קאמר\u0004 \u0005[אמר]\u0006 בעליו, אם כן בהכרח יש לומר \u0003דליהוי\u0004 \u0005[שיהיה]\u0006 \u0003\"עם קדוש\"\u0004 (ישראל) \u0003קאמר\u0004 \u0005[אמר],\u0006 שזו היתה כוונת הדברים כשאמר שמקדיש אותו, ונמצא ששיחררו בכך.","\u0003ורב יוסף אמר\u0004 בשם \u0003רב:\u0004 \u0003המפקיר עבדו יצא לחירות.\u0004 ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בשם רב \u0003מקדיש\u0004 עבדו יצא לחירות — \u0003כל שכן\u0004 שהוא סובר שכן הדין ב\u0003מפקיר,\u0004 אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מפקיר\u0004 עבדו יצא לחירות, \u0003אבל מקדיש\u0004 לדעתו \u0003לא\u0004 יצא לחירות. ומדוע? — \u0003דלמא לדמי קאמר\u0004 \u0005[שמא\u0006 כשהקדיש אותו — \u0005לדמים אמר]\u0006 כשאר הקדש לצורך בדק הבית, שמוכרים אותו ומשתמשים בדמיו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 בשני מקרים אלה, של מקדיש ומפקיר עבדו, שאמרנו שיצא בהם לחירות, האם \u0003צריך\u0004 האדון גם לכתוב \u0003גט\u0004 (שטר) \u0003שיחרור, או לא צריך?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר רב חייא בר אבין אמר רב: אחד זה ואחד זה,\u0004 מקדיש ומפקיר — \u0003יצא\u0004 העבד \u0003לחירות, וצריך גט שחרור.\u0004","\u0003אמר רבה: ומותבינן אשמעתין\u0004 \u0005[ומקשים אנו על ההלכה שלנו],\u0006 כלומר, על אותה הלכה שרבה עצמו אמר בשם רב יש מקום להקשות. כיצד? שנינו: \u0003המקדיש נכסיו והיו בהן עבדים, אין הגזברין רשאין להוציאן לחירות, אבל מוכרין אותן,\u0004 את העבדים, \u0003לאחרים, ואחרים מוציאין אותן לחירות. רבי אומר, אומר אני: אף הוא,\u0004 העבד \u0003נותן דמי עצמו ויוצא\u0004 לחירות, \u0003מפני שהוא\u0004 הגזבר \u0003כמוכרו לו\u0004 (לעצמו). ומכל מקום אפשר ללמוד מכאן שעצם הקדשת העבד אינה מוציאה אותו לחירות! ודוחים: \u0003מתניתא קא רמית עליה דרב\u0004 \u0005[\u0006מ\u0005ברייתא אתה מקשה על רב]?\u0006 \u0003רב\u0004 עצמו \u0003תנא הוא ופליג\u0004 \u0005[וחולק]\u0006 על ברייתא זו.","ומביאים קושיה אחרת על רב, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו על הנאמר: \u0003\"אך כל חרם\u0004 אשר יחרים איש לה' מכל אשר לו... מאדם ובהמה\u0003\"\u0004 (ויקרא כז, כח). ודרשו חכמים: \u0003\"מאדם\"\u0004 — \u0003אלו עבדיו ושפחותיו הכנענים,\u0004 משמע שאפשר להקדישם, ולא יצאו לחירות בכך! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ש\u0003אמר\u0004 במפורש שמקדיש אותם \u0003לדמי\u0004 \u0005[לדמים].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אפשר לומר שבברייתא \u0003אידך\u0004 \u0005[האחרת]\u0006 שהקשינו ממנה, ותירצנו שרב חולק עליה, \u0003נמי\u0004 \u0005[גם כן]\u0006 מדובר ש\u0003אמר\u0004 האדון שהוא מקדיש את עבדיו \u0003לדמי\u0004 \u0005[לדמים]\u0006 ואין צורך לומר שרב חולק על אותה ברייתא!","ומשיבים: שם אי אפשר לתרץ כך, כי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, מה שאמרו בברייתא ש\u0003אין הגזברים רשאין להוציאן לחירות, גזברים מאי עבידתייהו\u0004 \u0005[מה מעשיהם]\u0006 וכיצד יוציאו אותם לחירות אם לא זכו אלא בדמיהם?","\u0003ותו\u0004 \u0005[ועוד],\u0006 מה שנאמר שם: \u0003אבל מוכרין אותן לאחרים ואחרים מוציאין אותן לחירות, אחרים מאי עבידתייהו\u0004 \u0005[מה מעשיהם],\u0006 מדוע יוציאו הם את העבדים לחירות? \u0003ותו\u0004 \u0005[ועוד],\u0006 מה שנאמר שם: \u0003רבי אומר, אומר אני: אף הוא נותן דמי עצמו ויוצא, מפני שהוא כמוכרו לו, ואי לדמי\u0004 \u0005[ואם לדמים]\u0006 הקדישו, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מפני שהוא כמוכרו לו\"?\u0004 וכל זה אינו מתיישב אלא לפי השיטה שההקדש הזה גורם הקדש לגופם של העבדים, אלא מכיון שאי אפשר לעשות דבר בגופם, צריך לפדות אותם באיזה אופן, ואין הברייתא כשיטת רב.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת נגד שיטתו של רב, ממה ששנינו: \u0003המקדיש עבדו\u0004 — העבד \u0003עושה\u0004 (עובד עבודה) \u0003ואוכל\u0004 בשכר עבודתו, מפני \u0003שלא הקדיש\u0004 האדון \u0003אלא\u0004 את \u0003דמיו\u0004 של העבד. משמע שהקדש חל עליו, ואינו משתחרר!"],["ומתרצים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אין אדם מוציא דבריו\u0004 להקדש \u0003לבטלה.\u0004 ואם הקדיש דבר, אף שלא הקדישו בלשון הראויה, אנו מפרשים את דבריו באופן שלא יהיו דבריו לריק, ולכן אף שלא אמר האדון שמקדיש את העבד לדמים — אנו מפרשים כך את דבריו. ואילו רב סבור כדעת חכמים החולקים עליו, ולדעתם אין העבד קדוש.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לפרש\u0005],\u0006 \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנה בסופה\u0006 של הברייתא\u0005]:\u0006 \u0003וכן הוא,\u0004 אדם בן חורין, \u0003שהקדיש עצמו\u0004 — \u0003עושה ואוכל\u0004 ממעשה ידיו, \u0003שלא הקדיש אלא דמיו\u0004 (שוויו) ולא את גופו. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שברייתא זו כשיטת \u0003ר' מאיר היא\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 מובנת הברייתא כולה, שגם כאשר הקדיש את עצמו מפרשים שהתכוון לסוג הקדש שיש בו משמעות.","\u0003אלא אי אמרת רבנן\u0004 \u0005[אם אתה אומר\u0006 ששיטת \u0005חכמים]\u0006 \u0003היא, בשלמא\u0004 \u0005[נניח]\u0006 את הרישא העוסקת במקדיש \u0003עבדו\u0004 נוכל לפרש — שכן \u0003לדמי קאי\u0004 \u0005[לדמים\u0006 הוא \u0005עומד]\u0006 ולכן מסתבר שכאשר הוא מקדיש אותו יש לפרש שהוא מקדיש את דמיו, \u0003אלא\u0004 הסיפא העוסקת במקדיש את עצמו — וכי \u0003איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 \u0003לדמי קאי\u0004 \u0005[לדמים\u0006 הוא \u0005עומד]?\u0006 הרי אין בן חורין עומד לכך! אלא בוודאי יש לפרש את הברייתא כשיטת ר' מאיר.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בבעיה זו של מקדיש עבדו? ששנינו: \u0003המקדיש עבדו\u0004 — \u0003אין מועלין בו,\u0004 בעבד, ששימוש בו אינו נחשב מעילה בהקדש. \u0003רבן שמעון בן גמליאל אומר: מועלין בשערו. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003קדוש,\u0004 כלומר, חלה עליו קדושה, ולכן יש בו דין מעילה כבכל הקדש, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003לא קדוש?\u0004","ותוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שאפשר לפרש כן? אם כן \u0003האי\u0004 \u0005[זו]\u0006 הלשון \u0003\"מועלין בו\" ו\"אין מועלין בו\"\u0004 השנויה במחלוקתם אינה לשון ראויה, \u0003האי\u0004 \u0005[זו]\u0006 הלשון \u0003\"קדוש\" ו\"אינו קדוש\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שכן בזה עיקר מחלוקתם!","\u0003אלא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 צריכים לומר שהעבד אכן \u0003קדוש,\u0004 שההקדש חל, ולא כדעת רב, \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 ש\u0003עבדא כמקרקעי דמי\u0004 \u0005[עבד כקרקעות\u0006 הוא \u0005נחשב],\u0006 שהרי הושוו עבדים לקרקעות לכמה דברים, וכשם שאין מעילה בקרקעות אף אין מעילה בעבדים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 \u0003כמטלטלי דמי\u0004 \u0005[כמטלטלים\u0006 הוא \u0005נחשב]\u0006 ומשום כך יש דין מעילה בעבדים כמו במטלטלים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את מחלוקתם, \u0003אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005נחלקים]\u0006 \u0003בשערו\u0004 של העבד אם מועלים בו או לא, \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בגופו\u0004 עצמו אם מועלים או אין מועלים בו!","\u0003אלא,\u0004 כך צריך לומר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עבדא כמקרקעי דמי\u0004 \u0005[העבד כקרקעות\u0006 הוא \u0005נחשב]\u0006 וממילא אין בו מעילה, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בשערו העומד ליגזז קמיפלגי\u0004 \u0005[נחלקו],\u0006 האם הוא נחשב עדיין כחלק מן העבד. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 ש\u0003כגזוז דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואינו נחשב עוד כחלק מן העבד, ואם כן, כתלוש הוא, וחל עליו דין מעילה כבכל המיטלטלים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כגזוז דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 אלא כמחובר בעבד כל עוד לא נגזז בפועל, ואף השיער נחשב כקרקעות, ומשום כך אין מועלים בו.","ומציעים: \u0003לימא הני תנאי כהני תנאי\u0004 \u0005[האם לומר\u0006 ש\u0005תנאים אלה\u0006 ש\u0005נחלקו כ\u0006מחלוקת \u0005תנאים אלה\u0006 האחרים\u0005]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: יש דברים שהם כקרקע\u0004 מבחינת צורתם \u0003ואינן כקרקע\u0004 מבחינת דינם, \u0003ואין חכמים מודים לו,\u0004 כיצד? — אם טוען אדם כלפי חבירו: \u0003\"עשר גפנים טעונות\u0004 (נושאות פירות) \u0003מסרתי לך\u0004 לשמירה \u0003\", והלה אומר: \"אינן אלא חמש\"\u0004 — \u0003ר' מאיר מחייב\u0004 את הנתבע בשבועה, כדין כל מודה במקצת, \u0003וחכמים אומרים: כל המחובר לקרקע הרי הוא כקרקע,\u0004 ואין נשבעים על כפירת קרקעות.","\u0003ו\u0004על כך \u0003אמר ר' יוסי בר' חנינא:\u0004 בענין \u0003ענבים העומדות ליבצר איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, ולא בכל עצים נושאי פרי, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 כיון שהן עומדות להיבצר — \u0003כבצורות דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 ומשום כך דינן כתלושות, ונשבעים על מיטלטלים. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כבצורות דמיין\u0004 \u0005[נחשבות]\u0006 ודינן כקרקע ולפיכך אין נשבעים עליהן. ואם כן, האם יש לומר שבמחלוקת רבן שמעון בן גמליאל וחכמים הם חלוקים?","ודוחים: אין בהכרח לומר שהמחלוקת בברייתא ביחס לשערו של עבד היא כמחלוקת במשנה ביחס לענבים, כי \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כ\u0003ר' מאיר\u0004 במשנה בענין ענבים העומדות להיבצר, שלדעתו נחשבות כבצורות — אין מכאן ראיה לשערו של עבד העומד להיגזז, כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 שפירות העומדים להיתלש נחשבים כתלושים \u0003אלא\u0004 דווקא \u0003בענבים,\u0004 שכל \u0003כמה דקיימין\u0004 \u0005[ש\u0006הם \u0005נמצאים,\u0006 נשארים\u0005]\u0006 יותר על העץ לאחר בישולם הם \u0003מיכחש כחישי\u0004 \u0005[מצטמקים יותר]\u0006 ונפסדים בכך, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בשיער, כל \u0003כמה דקאי\u0004 \u0005[ש\u0006הוא \u0005נמצא]\u0006 יותר על העבד \u0003אשבוחי משבח\u0004 \u0005[משתבח\u0006 הוא\u0005]\u0006 ולכן אין לומר שהוא כגזוז.","ובקשר לדברי רב שנאמרו מקודם שהמפקיר עבדו יצא לחירות, מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' חייא בר יוסף\u0004 מבבל לארץ ישראל, \u0003אמר להאי שמעתא\u0004 \u0005[את ההלכה הזו]\u0006 של \u0003רב\u0004 שהמפקיר עבדו יצא לחירות \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן. אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתמיהה: האמנם \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 ותוהים על כך: \u0003ו\u0004כי \u0003הוא,\u0004 ר' יוחנן עצמו, \u0003לא אמר הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא אמר ר' יוחנן: המפקיר עבדו יצא לחירות, וצריך גט\u0004 (שטר) \u0003שחרור,\u0004 אם כן, מדוע הוא תמה על רב?!","ומשיבים: לא היתה בדבריו תמיהה אלא \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 לר' חייא בר יוסף: האמנם \u0003אמר רב כוותי\u0004 \u0005[כמותי]?\u0006 ונהנה לשמוע שגם רב סבור כך. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 באופן אחר: \u0003לא סיימוה\u0004 את ההלכה \u0003קמיה\u0004 \u0005[לפניו],\u0006 לפני ר' יוחנן, שלדעת רב צריך העבד גט שיחרור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' חייא בר יוסף: \u0003ו\u0004כי \u0003לא אמר רב\u0004 כי \u0003צריך גט שחרור? ור' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר עולא אמר ר' יוחנן : המפקיר עבדו יצא לחירות, וצריך גט שחרור.\u0004","\u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה שהזכרנו, \u0003אמר עולא אמר ר' יוחנן: המפקיר עבדו\u0004 — \u0003יצא\u0004 בכך העבד \u0003לחירות, וצריך גט שיחרור\u0004 כדי לשחררו לגמרי ולהתירו לשאת אשה מישראל.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לעולא\u0004 ממה ששנינו בברייתא: \u0003גר שמת ובזבזו\u0004 (בזזו) \u0003ישראל נכסיו,\u0004 שהרי אין לו יורשים ונכסיו נעשו הפקר וכל אחד יכול לזכות בהם, \u0003והיו בהן,\u0004 בין הנכסים, \u0003עבדים, בין\u0004 שהיו עבדים \u0003גדולים ובין קטנים\u0004 — \u0003קנו עצמן\u0004 והריהם \u0003בני חורין,\u0004 משום שגם הם זוכים מן ההפקר וזכו בעצמם. \u0003אבא שאול אומר:\u0004 עבדים \u0003גדולים\u0004 — \u0003קנו עצמן בני חורין, קטנים\u0004 — \u0003כל המחזיק בהן, זכה בהן.\u0004","ולשיטת ר' יוחנן יש לשאול: \u0003וכי מי כתב גט שחרור לאלו\u0004 שנעשו בני חורין? והרי בעליהם הגר מת בלא ששיחררם. משמע שעל ידי זה שהעבד נעשה כהפקר הוא יוצא לחירות לגמרי, ואינו צריך כתב שיחרור!","\u0003אמר\u0004 עולא: \u0003דמי האי מדרבנן כדלא גמרי אינשי שמעתא\u0004 \u0005[דומה זה מן החכמים,\u0006 ר' אבא, \u0005כמו\u0006 אנשים \u0005שלא למדו הלכה],\u0006 ולא ענה לו כלל על שאלתו, מפני שחשב שאינו ראוי לתשובה על שאלה זו. ושואלים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מהו]?\u0006 מדוע במקרה כזה אכן אין העבדים צריכים גט שיחרור? \u0003אמר רב נחמן, קסבר\u0004 \u0005[סבור]\u0006 \u0003עולא: עבדו\u0004 של \u0003גר\u0004 הוא לענין זה \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אשתו\u0004 של גר, \u0003מה אשתו משתלחה\u0004 (מותרת) במותו \u0003בלא גט,\u0004 ואינה צריכה גט להפקיע את איסורה, \u0003אף עבדיו משתלחים\u0004 (משתחררים) \u0003בלא גט.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם אתה משווה לענין זה עבד לאשה, מדוע נאמר הדבר דווקא בעבדו של גר? \u0003אפילו ישראל נמי\u0004 \u0005[גם כן]\u0006 היה צריך להיות שבמות האדון ישתחררו עבדיו לגמרי בדומה לאשתו! ומשיבים: בעבדים \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והתנחלתם אתם לבניכם אחריכם לרשת אחזה\"\u0004 (ויקרא כה, מו) ומשום כך יש זכות לבנים בעבדים, ולכן אינם יוצאים לחירות במיתת האדון, אבל גר אין לו יורשים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003המפקיר עבדו ו\u0004אחר כך \u0003מת, נמי\u0004 \u0005[גם כן]\u0006 לא יצטרך גט שיחרור, שהרי שוב אין כאן נחלה לבנים, \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר אמימר: המפקיר עבדו ומת\u0004 — \u0003אותו העבד אין לו תקנה,\u0004 שאין מי שישחרר אותו? ואומרים: \u0003דאמימר קשיא\u0004 \u0005[\u0006זו \u0005ש\u0006אמר \u0005אמימר\u0006 אכן \u0005קשה]\u0006 על הסברו של רב נחמן לדברי עולא.","\u0003אמר ר' יעקב בר אידי אמר ר' יהושע בן לוי: הלכה כאבא שאול\u0004 בענין גר שמת והשאיר עבדים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' יעקב בר אידי:\u0004"],["\u0003בפירוש שמיע לך\u0004 \u0005[שמעת\u0006 זאת\u0005]\u0006 בשם ר' יהושע בן לוי, \u0003או מכללא שמיע לך\u0004 \u0005[מכלל\u0006 דבריו \u0005שמעת,\u0006 למדת, זאת\u0005]?\u0006 שאל אותו ר' יעקב בר אידי: \u0003מאי כללא\u0004 \u0005[מהו\u0006 אותו \u0005הכלל]\u0006 שיכול הייתי להבין דבר זה ממנו? השיב לו ר' זירא: ש\u0003אמר ר' יהושע בן לוי, אמרו לפני רבי:\u0004 אם \u0003אמר\u0004 אדם \u0003\"נתייאשתי מפלוני עבדי\", מהו\u0004 דינו של אותו עבד? \u0003אמר להם, אומר אני: אין לו תקנה\u0004 לעבד \u0003אלא בשטר\u0004 שיחרור.","\u0003ואמר ר' יוחנן:\u0004 \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003רבי? - גמר\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 בגזירה שווה \u0003\"לה\" \"לה\" מאשה,\u0004 שבאשה נאמר \"וכתב לה ספר כריתות\" (דברים כד, ג) ובשפחה נאמר \"חופשה לא ניתן לה\" (ויקרא יט, כ); \u0003מה אשה\u0004 אינה יוצאת מבעלה אלא \u0003בשטר\u0004 (גט), \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 משתחרר דווקא \u0003בשטר.\u0004","עד כאן שמעת, \u0003וקא דייקת מינה\u0004 \u0005[ודייקת מכאן],\u0006 מן ההשוואה הזאת, לענייננו, במיתת האדון, שהעבד דינו \u0003כאשה, מה אשה\u0004 כשמותרת במיתת בעלה — הרי זה כשיש עליה זיקת \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003ולא\u0004 זיקת \u0003ממונא\u0004 \u0005[ממון],\u0006 \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 אין מיתת האדון משחררת אותו אלא כשיש זיקת \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003ולא\u0004 זיקת \u0003ממונא\u0004 \u0005[ממון],\u0006 ודבר זה יכול להיות רק בעבד גדול שבאותה שעה זוכה מבחינה ממונית בעצמו, ולא בעבד קטן, וכשיטת אבא שאול בענין עבדים קטנים. ונמצא שסבור ר' יהושע בן לוי כאבא שאול.","אמר לו: \u0003ואי מכללא מאי\u0004 \u0005[ואם\u0006 אכן \u0005מכלל\u0006 הדברים למדתי, \u0005מה]\u0006 הפגם בכך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 שאם למדת כן מכלל דברי ר' יהושע בן לוי \u0003אדרבה\u0004 (להיפך), \u0003דוק מינה לאידך גיסא\u0004 \u0005[דקדק מכאן לצד האחר]\u0006 ואמור כך: \u0003מה אשה\u0004 מועילה בה מיתה לשחררה בלא גט \u0003בין\u0004 שהיא \u0003גדולה בין\u0004 שהיא \u0003קטנה, אף עבד נמי\u0004 \u0005[גם כן]\u0006 \u0003בין\u0004 שהוא \u0003גדול בין\u0004 שהוא \u0003קטן\u0004 הריהו נעשה בן חורין במיתת האדון, ולא כשיטת אבא שאול! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בפירוש שמיע לי\u0004 \u0005[שמעתי]\u0006 זאת מר' יהושע בן לוי שהלכה כאבא שאול.","\u0003ור' חייא בר אבא אמר\u0004 בשם \u0003ר' יוחנן: אין הלכה כאבא שאול. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' חייא בר אבא: בפירוש שמיע לך\u0004 \u0005[שמעת]\u0006 את הדבר, \u0003או מכללא שמיע לך\u0004 \u0005[מכלל\u0006 הדברים \u0005שמעת,\u0006 למדת אותו\u0005]?\u0006 שאל אותו: \u0003מאי כללא\u0004 \u0005[מהו\u0006 אותו \u0005הכלל]\u0006 שיכול הייתי להבין זאת ממנו? השיב לו: ממה ש\u0003אמר ר' יהושע בן לוי, אמרו לפני רבי:\u0004 אם אמר האדון \u0003\"נתייאשתי מפלוני עבדי\", מהו? אמר להם. אומר אני: אין לו תקנה אלא בשטר.\u0004","\u0003ואמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 מגזירה שווה \u0003\"לה\" \"לה\" מאשה; מה אשה\u0004 אינה יוצאת מבעלה אלא \u0003בשטר, אף עבד נמי\u0004 \u0005[גם כן]\u0006 אינו יוצא","\u0003לחירות אלא\u0004 \u0003בשטר. וקא דייקת מינה\u0004 \u0005[ולמדת מכאן]\u0006 שדינו אף לענין מיתה \u0003כאשה; מה אשה\u0004 משתלחת במיתת בעלה \u0003בין\u0004 שהיא \u0003גדולה בין\u0004 שהיא \u0003קטנה, אף עבד נמי\u0004 \u0005[גם כן]\u0006 \u0003בין\u0004 שהוא \u0003גדול בין\u0004 שהוא \u0003קטן\u0004 משתחרר באותה דרך, וכמו שיוצא בשטר בעודו קטן, כך יוצא במיתת האדון.","ושאל אותו ר' חייא בר אבא: \u0003ואי מכללא מאי\u0004 \u0005[ואם מכלל\u0006 הדברים למדתי, \u0005מה]\u0006 הפגם בכך? והשיב לו ר' זירא: \u0003אדרבה\u0004 (להיפך), \u0003דוק מינה להך גיסא\u0004 \u0005[דקדק מכאן לצד אחר],\u0006 וכך תדקדק: \u0003מה אשה\u0004 מדובר כאן בהפקעת \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003ולא ממונא\u0004 \u0005[ממון],\u0006 \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 מדובר במקום שיש הפקעת \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003ולא ממונא\u0004 \u0005[ממון]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בפירוש שמיע לי\u0004 \u0005[שמעתי]\u0006 את הדבר מר' יוחנן.","ומעתה דנים באותה הלכה לגופה, \u0003אמר מר\u0004 \u0005[החכם,\u0006 רבי\u0005]:\u0006 \u0003אמר להם, אומר אני: אין לו תקנה אלא בשטר.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רבי אומר, אומר אני: אף הוא נותן דמי עצמו ויוצא, מפני שהוא כמוכרו לו,\u0004 משמע שהעבד יוצא לא רק בשטר אלא גם באופן אחר!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003או\u0004 יוצא \u0003בכסף או בשטר, והאי\u0004 \u0005[וזה]\u0006 \u0003פקע ליה כספיה\u0004 \u0005[לו כספו]\u0006 שהוא יכול לתת ועל ידו להשתחרר, וממילא אין להוציאו אלא בשטר. \u0003ולאפוקי מהאי תנא\u0004 \u0005[ולהוציא מ\u0006דברי \u0005תנא זה]\u0006,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר משום\u0004 (בשם) \u0003ר' עקיבא: יכול יהא כסף גומר בה\u0004 באמה עבריה, ומשחרר אותה לחלוטין מאדוניה \u0003כדרך ששטר גומר בה?\u0004 — \u0003תלמוד לומר\u0004 בפרשת הבא על שפחה חרופה (מסורה) לאיש שאין שניהם חייבים מיתה כדין הבא על אשת איש בת חורין: \u0003\"והפדה לא נפדתה\u0004 או חופשה לא ניתן לה\u0003\"\u0004(ויקרא יט, כ),","ובסוף הפסוק נאמר \"לא יומתו כי לא חופשה\", לומר: \u0003אורעה\u0004 (זומנה, נתקשרה) \u0003כל הפרשה כולה ל\u0004דין של \u0003\"לא חפשה\"\u0004 (ויקרא יט,כ) בלבד, לומר שאין טעמו של דבר שאינה בת חורין תלוי בכסף (\"והפדה לא נפדתה\"), אלא בכך שלא נשתחררה בשטר (\"חופשה\"), \u0003לומר לך: שטר גומר בה\u0004 ומשחררה לחלוטין \u0003ואין הכסף גומר בה.\u0004","\u0003אמר רמי בר חמא אמר רב נחמן: הלכה כר' שמעון. ורב יוסף בר חמא אמר\u0004 בשם \u0003ר' יוחנן: אין הלכה כר' שמעון.\u0004","מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רב נחמן בר יצחק לרבא בר שאילתא דהוה קאי אפיתחא דבי תפלה\u0004 \u0005[שהיה עומד על פתח בית התפילה,\u0006 בית הכנסת\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בענין זה: \u0003הלכה\u0004 כר' שמעון \u0003או אין הלכה\u0004 כמותו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני אומר אין הלכה\u0004 בענין זה כר' שמעון, \u0003ורבנן דאתו\u0004 \u0005[וחכמים שבאו]\u0006 \u0003ממחוזא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אמר ר' זירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: הלכה\u0004 כר' שמעון,","\u0003וכי אתאי\u0004 \u0005[וכאשר באתי]\u0006 \u0003לסורא, אשכחתיה\u0004 \u0005[מצאתי אותו]\u0006 את \u0003ר' חייא בר אבין, אמרי ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003אימא לי איזי גופא דעובדא היכי הוה\u0004 \u0005[אמור לי ידידי גוף המעשה איך היה],\u0006 מה בדיוק אמר רב נחמן? \u0003אמר לי: דההיא אמתא דהוה מרה שכיב מרע\u0004 \u0005[שפחה אחת שהיה אדוניה נוטה למות],\u0006 \u0003אתיא בכיא קמיה\u0004 \u0005[באה ובכתה לפניו],\u0006 וכך \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עד אימת תשתעביד ותיזיל ההיא איתתא\u0004 \u0005[עד מתי תשתעבד ותלך\u0006 ותמשיך \u0005אותה אישה],\u0006 כלומר, עד כמה אהיה עוד שפחה? \u0003שקל כומתיה שדא בה\u0004 \u0005[לקח\u0006 את \u0005כובעו זרק לה],\u0006 ו\u0003אמר לה: זיל\u0004 \u0005[לכי]\u0006 \u0003קני הא\u0004 \u0005[\u0006את \u0005זה,\u0006 את הכומתה\u0005]\u0006 \u0003ו\u0004על ידי כך \u0003קני נפשך\u0004 \u0005[את עצמך]\u0006 כמשוחררת. \u0003אתו לקמיה\u0004 \u0005[באו\u0006 לדון \u0005לפני]\u0006 \u0003רב נחמן\u0004 בענין זה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא עשה ולא כלום.\u0004","\u0003מאן דחזא\u0004 \u0005[מי שראה]\u0006 את הדבר \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003משום\u0004 ש\u0003הלכה כר' שמעון\u0004 שאין שפחה משתחררת אלא בשטר. \u0003ולא היא, אלא משום דהוה ליה\u0004 \u0005[שהיה זה]\u0006 קנין חליפין שנעשה ב\u0003כליו של מקנה,\u0004 ואין קנין אלא כשקונה המקנה כלי של הקונה, ומשום כך לא חל השיחרור.","\u0003אמר רב שמואל בר אחיתאי אמר רב המנונא סבא אמר ר' יצחק בר אשיאן אמר רב הונא אמר רב המנונא: הלכה כר' שמעון.\u0004 ומסכמים: \u0003ולא היא,\u0004 אלא \u0003אין הלכה כר' שמעון.\u0004","\u0003אמר ר' זירא אמר ר' חנינא אמר רב אשי אמר רבי: עבד שנשא את בת חורין בפני רבו\u0004 —"],["\u0003יצא לחירות. אמר לו ר' יוחנן\u0004 לר' זירא: הלכה קיצונית \u0003כל כך יש בידך, ואני שונה\u0004 הלכה זו: \u0003הכותב שטר אירוסין לשפחתו,\u0004 שכותב לה האדון \"הרי את מקודשת לי\", \u0003ר' מאיר אומר: מקודשת, וחכמים אומרים: אינה מקודשת,\u0004 שאפילו זו אינה הוכחה ששיחרר אותה, ולכן אינה מקודשת!","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רבה בר רב שילא\u0004 בענין שיבואר להלן: מדובר \u0003כשרבו\u0004 של העבד \u0003הניח לו תפילין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר לא שנשא העבד אשה בפניו אלא ש\u0003רבו\u0004 עצמו \u0003השיאו אשה\u0004 וזו בוודאי ראיה ששיחררו.","ושואלים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 כזה שאתה אומר \u0003דלעבדיה לא מעבד ליה איסורא\u0004 \u0005[שלעבדו אינו עושה לו איסור]\u0006 ואם השיאו בת חורין לעבדו — בוודאי שיחררו, \u0003ואיהו עבד איסורא\u0004 \u0005[והוא\u0006 עצמו \u0005עושה איסור],\u0006 שהוא עצמו חשוד שנושא שפחה שלא שיחרר אותה? וכיצד לפי זה ניתן להבין את דעת חכמים?","\u0003אמר רב נחמן בר יצחק: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ש\u0003אמר לה,\u0004 לשפחה כשנתן לה את שטר הקידושין: \u0003\"צאי בו והתקדשי בו\",\u0004 והתכוון לשחרר אותה בכך, ובזה נחלקו: \u0003ר' מאיר סבר\u0004 ש\u0003יש בלשון הזה לשון שחרור\u0004 ולכן היא מקודשת, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין בלשון הזה לשון שחרור,\u0004 אם כן, המחלוקת שלהם אינה בכוונתו לשחרר את השפחה, ואף לדעת חכמים אינו חשוד לשאתה לאשה בלא לשחררה, אלא בשאלה מה התוקף של דבריו.","ובאותו ענין \u0003אמר ר' יהושע בן לוי: עבד שהניח תפילין בפני רבו\u0004 — \u0003יצא לחירות,\u0004 שאין דרכו של עבד להניח תפילין לפי שאינו חייב במצוה זו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: עבד ש\u0003לוה הימנו רבו, או שעשאו רבו אפוטרופוס\u0004 לנכסיו, \u0003או שהניח תפילין בפני רבו, או שקרא שלשה פסוקים בבית הכנסת בפני רבו,\u0004 אף על פי שכל אלה הם דברים שנוהגים בבן חורין — \u0003הרי זה לא יצא לחירות\u0004 על ידי כך, וקשה איפוא לר' יהושע בן לוי!","\u0003אמר רבה בר רב שילא:\u0004 ר' יהושע בן לוי אמר דבריו \u0003כשרבו\u0004 בעצמו \u0003הניח לו תפילין,\u0004 ובמקרה זה ברור שעושה זאת מדעתו, ולא היה מניח לו תפילין אלא אם כן שיחררו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 \u0003מי שאמר בשעת מיתתו: \"פלונית שפחתי אל ישתעבדו בה לאחר מותי\"\u0004 — \u0003כופין את היורשים וכותבין לה גט\u0004 (שטר) \u0003שחרור. אמרו לפניו ר' אמי ור' אסי: רבי,\u0004 וכי \u0003אי\u0004 (אין) \u0003אתה מודה שבניה עבדים?\u0004 שבאמת אין כאן לשון שיחרור ממש, אלא רצה לומר שלא ישתעבדו בה יותר מדי, ומכל מקום אין בכך שיחרור, ובניה ישארו עבדים, ואם כן מדוע כופים את הבנים לשחררה?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה אמר\u0004 בשם \u0003ר' יוחנן\u0004 בנוסח אחר: \u0003מי שאמר בשעת מיתתו: \"פלונית שפחתי קורת רוח עשתה לי, יעשה לה קורת רוח\"\u0004 — \u0003כופין את היורשין ועושין לה קורת רוח,\u0004 ואם אין לה קורת רוח אלא כשמשחררים אותה — ישחררוה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003מצוה לקיים דברי המת.\u0004","\u0003אמר אמימר: המפקיר עבדו\u0004 — \u0003אותו עבד אין לו תקנה\u0004 מבחינת ההלכה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003גופיה\u0004 \u0005[גופו]\u0006 של העבד שוב \u0003לא קני ליה\u0004 \u0005[קנוי לו\u0006 לאדון\u0005],\u0006 \u0003איסורא\u0004 \u0005[\u0006חלק \u0005האיסור]\u0006 בלבד \u0003הוא דאיכא גביה\u0004 \u0005[שיש אצלו,\u0006 אצל האדון\u0005]\u0006 שעדיין אסור העבד בבת ישראל, \u0003ואיסורא לא מצי מקני ליה\u0004 \u0005[ו\u0006את \u0005האיסור אינו יכול להקנות לו],\u0006 שאין זה דבר שניתן להקנות, ושטר שיחרור לא מועיל כאן, שהרי כבר אין העבד שלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא אמר\u0004 בשם \u0003ר' יוחנן, ורב חייא בר אבין אמר\u0004 זאת בשם \u0003רב: אחד זה ואחד זה\u0004 בין מקדיש עבדו ובין מפקיר עבדו \u0003יצא לחירות, וצריך גט שחרור,\u0004 משמע שמפקיר עבדו משתחרר מקנין הממון ויוצא אחר כך בגט שיחרור להיות בן חורין, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מה שאמרו \u0003\"צריך\"\u0004 כוונתו שאמנם צריך \u0003ו\u0004אולם \u0003אין לו תקנה,\u0004 שכדי שיהיה חופשי לגמרי ויהיה מותר בבת ישראל צריך גט שיחרור, אבל אי אפשר לעשות זאת. עד כאן לשון אחת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 זאת בלשון אחרת: \u0003אמר אמימר: המפקיר עבדו ומת\u0004 האדון — \u0003אותו העבד אין לו תקנה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003גופיה\u0004 \u0005[גופו]\u0006 של העבד \u0003לא קני ליה\u0004 \u0005[קנוי לו]\u0006 עוד לאדון, \u0003איסורא\u0004 \u0005[איסור]\u0006 בלבד \u0003הוא דאיכא גביה\u0004 \u0005[שיש אצלו],\u0006 \u0003ו\u0004את הכוח להתיר \u0003איסורא\u0004 \u0005[איסור]\u0006 של האב \u0003לבריה\u0004 \u0005[לבנו]\u0006 \u0003לא מורית\u0004 \u0005[מוריש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 שמי שאמר שאל ישתעבדו בשפחתו כופים את היורשים וכותבים לה גט שיחרור!","ענה לו אמימר: מה שאמר \u0003רב דימי\u0004 בשם ר' יוחנן \u0003טעותא\u0004 \u0005[טעות]\u0006 \u0003היא,\u0004 שלא כך אמר ר' יוחנן. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעותא\u0004 \u0005[מה הטעות]\u0006 — ש\u0003לא אמרה\u0004 את הדבר הזה \u0003בלשון שחרור, הא\u0004 \u0005[הרי]\u0006 אם \u0003אמרה\u0004 \u0003בלשון שחרור הכי נמי\u0004 \u0005[כך גם כן]\u0006 היה מועיל הדבר, ואם כן, מפני מה אין אתה מודה לדבריו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כדרב שמואל בר יהודה סבירא לי\u0004 \u0005[סבור אני]\u0006 שלא כך היו דבריו של ר' יוחנן, אלא שאמר דבריו במקרה שאמר האב שיעשו לה קורת רוח, ואם כן, אין כאן ענין של שיחרור אלא צוואת המת לעשות קורת רוח לשפחה זו.","מסופר: \u0003ההוא דסקרתא דעבדי דאזדבן\u0004 \u0005[עיר של עבדים שנמכרה]\u0006 \u0003לגוי, כלו\u0004 (מתו) \u0003מרוותא בתראי\u0004 \u0005[אדוניהם האחרונים]\u0006 הגויים, \u0003אתו לקמיה\u0004 \u0005[באו\u0006 אותם העבדים \u0005לפני]\u0006 \u0003רבינא\u0004 ואמרו שמכיון שבפועל אין להם אדונים היו רוצים להיחשב כישראלים גמורים, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו אהדרו אבני מרוותא קמאי\u0004 \u0005[לכו\u0006 ו\u0005חזרו על בני האדונים הראשונים\u0006 שלכם\u0005],\u0006 \u0003ויכתבו לכו\u0004 \u0005[לכם]\u0006 \u0003גיטא דחירותא\u0004 \u0005[שטר שיחרור]\u0006 ואז תהיו בני חורין לגמרי. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבינא, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אמימר: המפקיר עבדו ומת\u0004 — \u0003אותו העבד אין לו תקנה,\u0004 וכן במוכר אותו לגוי, שבמכירה לגוי פקע שיעבודו הממוני מן העבד ואין הוא שוב יכול לכתוב לו שטר שיחרור!","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כרב דימי סבירא לי\u0004 \u0005[סבור אני]\u0006 שאמר בשם ר' יוחנן שהיורשים יכולים לתת גט שיחרור. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 מה שאמר \u0003רב דימי טעותא\u0004 \u0005[טעות]\u0006 \u0003היא! אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי טעותא\u0004 \u0005[מה\u0006 היתה \u0005הטעות]\u0006 — ש\u0003לא אמרה בלשון שחרור, הא\u0004 \u0005[הרי]\u0006 אם \u0003אמרה בלשון שחרור הכי נמי\u0004 \u0005[כך גם כן]\u0006 היה. ואם כן, יכתבו שטר שיחרור גמור, ולא תהיה בעיה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרבינא\u0004 בענין זה שבני האדונים הראשונים יכולים לכתוב שטר שיחרור לעבדים.","מסופר: \u0003ההוא עבדא דבי תרי\u0004 \u0005[עבד אחד של שני\u0006 בעלים\u0005]\u0006 שהיו שותפים, \u0003קם חד מינייהו ושחרריה לפלגיה\u0004 \u0005[עמד אחד מהם ושיחרר את חציו]\u0006 של העבד השייך לו, \u0003אמר אידך\u0004 \u0005[\u0006האדון \u0005האחר]:\u0006 \u0003השתא שמעי\u0004 \u0005[עכשיו ישמעו]\u0006 \u0003בי רבנן\u0004 \u0005[חכמים]\u0006 שהעבד חציו בן חורין \u0003ומפסדו ליה מינאי\u0004 \u0005[ויפסידו אותו ממני]\u0006 שיכריחו אותי לשחררו, כפי שנאמר במשנה שכופים את האדון לשחרר עבד שחציו בן חורין, \u0003אזל אקנייה\u0004 \u0005[הלך\u0006 ו\u0005הקנה אותו,\u0006 את העבד\u0005]\u0006 \u0003לבנו\u0004 ה\u0003קטן,\u0004 ואת הבן הקטן אי אפשר לכפות בבית דין, ואם כן, ישאר העבד ברשותו.","\u0003שלחה רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 לשאלה זו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא, שלח ליה\u0004 \u0005[לו]\u0006 תשובה כסגנון הכתוב: \u0003\"כאשר עשה כן יעשה לו, גמולו ישיב לו בראשו\"\u0004 (ראה ויקרא כד, יט. עובדיה א, טו), כלומר, כשם שהוא הערים על דברי חכמים, כך אנו צריכים להערים עליו. הלא \u0003אנן קים לן בינוקא דמקרבא דעתיה לגבי זוזי\u0004 \u0005[אנו מוחזק לנו בתינוק שקרובה דעתו אצל כסף],\u0006 שהוא נהנה מכסף מזומן, על כן \u0003מוקמינן ליה\u0004 \u0005[נעמיד לו\u0006 לתינוק\u0005]\u0006 \u0003אפוטרופוס\u0004 שיוכל להעריך עבור התינוק את מחיר העבד,"],["\u0003ומקרקיש ליה זוזי\u0004 \u0005[ו\u0006העבד \u0005יקשקש לו,\u0006 לפניו ב\u0005כסף],\u0006 שכיון שקטן הוא — יהא להוט אחריו ויגמור בדעתו לשחררו, \u0003וכתב ליה גיטא דחירותא על שמיה\u0004 \u0005[ויכתוב לו שטר שיחרור על שמו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003האומר: \"עשיתי פלוני עבדי בן חורין\",\u0004 או אמר: \u0003\"\u0004עבדי \u0003עשוי בן חורין\",\u0004 או שאומר: \u0003\"הרי הוא בן חורין\"\u0004 בכל המקרים הללו — \u0003הרי הוא\u0004 נעשה \u0003בן חורין\u0004 על ידי כל אלה.","אם אומר: \u0003\"אעשנו בן חורין\"\u0004 — \u0003רבי אומר: קנה\u0004 העבד את עצמו, \u0003וחכמים אומרים: לא קנה. אמר ר' יוחנן: וכולן\u0004 שאמרנו שקנה, מדובר דווקא כשכתב דברים אלה \u0003בשטר\u0004 ומסרו לעבד, אבל באמירה בעל פה אינו מועיל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדומה קצת לזה, \u0003האומר: \"נתתי\u0004 במתנה \u0003שדה פלונית לפלוני\",\u0004 או: \u0003\"\u0004הרי שדה זו \u0003נתונה לפלוני\",\u0004 או: \u0003\"הרי היא שלו\",\u0004 בכל המקרים הללו — \u0003הרי היא שלו,\u0004 של המקבל. ואם אמר: \u0003\"אתננה לפלוני\"\u0004 — \u0003ר' מאיר אומר: קנה\u0004 פלוני את השדה, \u0003וחכמים אומרים: לא קנה.\u0004 ואף בזאת \u0003אמר ר' יוחנן: וכולן\u0004 מדובר שלא אמר זאת בעל פה אלא כשכתב את הדברים האלה \u0003בשטר\u0004 ומסרו לאותו פלוני, שרק אז יש תוקף לדבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003האומר: \"עשיתי פלוני עבדי בן חורין\", והוא,\u0004 העבד, \u0003אומר: \"לא עשאני\u0004 בן חורין \u0003\"\u0004— \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא זיכה לו\u0004 האדון את שיחרורו \u0003על ידי אחר\u0004 אלא שהעבד אינו יודע על כך, והעבד משוחרר. ואולם אם אמר האדון: \u0003\"כתבתי ונתתי לו\", והוא,\u0004 העבד, \u0003אומר:\u0004 \u0003\"לא כתב לי ולא נתן לי\",\u0004 במקרה כזה — \u0003הודאת בעל דין כמאה עדים דמי\u0004 \u0005[נחשב],\u0006 ומכיון שהעבד מודה שעדיין עבד הוא — נשאר בגדר עבד.","ועוד, במקרה דומה של אדם \u0003האומר: \"נתתי שדה פלונית לפלוני\", והוא,\u0004 אותו פלוני, \u0003אומר: \"לא נתן לי\"\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא זיכה לו\u0004 את השדה \u0003על ידי אחר.\u0004 ואם אומר \u0003\"כתבתי ונתתי לו\", והוא,\u0004 אותו פלוני, \u0003אומר: \"לא כתב ולא נתן לי\"\u0004 — \u0003הודאת בעל דין כמאה עדים דמי\u0004 \u0005[נחשב].\u0006","ושואלים: במקרה זה שהנותן אומר שנתן לחבירו שדה, והמקבל אומר שלא קיבל, \u0003מי אוכל פירות\u0004 של אותה שדה? שהרי כל אחד מהם אומר שאין השדה שלו. \u0003רב חסדא אמר:\u0004 ה\u0003נותן אוכל פירות,\u0004 שהשדה נשאר בחזקתו, \u0003ורבה אמר: משלשין\u0004 (מפקידים) \u0003את הפירות\u0004 ביד שליש.","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 אלא הם מדברים במקרים שונים: \u0003הא באבא\u0004 \u0005[זה באב],\u0006 במקבל המתנה עצמו, שכל זמן שהוא חי ואומר שלא קיבל, בינתיים הנותן אוכל פירות, \u0003הא בברא\u0004 \u0005[זה בבן]\u0006 של מקבל המתנה, הטוען שאביו לא קיבל, שכיון שייתכן שהבן אינו יודע מה בדיוק אירע — משאירים את הדבר בידי השליש.","\u0003עבד שעשאו רבו\u0004 (אדוניו) \u0003אפותיקי\u0004 (כמשכון מוגדר לפרעון חובו) \u0003לאחרים\u0004 שלווה מהם, \u0003ו\u0004אחר כך \u0003שיחררו\u0004 — לפי \u0003שורת הדין אין העבד חייב כלום, אלא מפני תיקון העולם כופין את רבו ועושה אותו בן חורין, וכותב\u0004 העבד \u0003שטר על דמיו\u0004 כדי לשלם את החוב למלווה. \u0003רבן שמעון בן גמליאל אומר: אינו כותב אלא משחרר.\u0004","שנינו במשנה: \u0003\"עבד שעשאו רבו אפותיקי ושיחררו\".\u0004 ומבררים: \u0003מי שחררו? אמר רב: רבו\u0004 ה\u0003ראשון\u0004 שיחררו. וכך יש להסביר את המשנה: \u0003שורת הדין אין העבד חייב כלום לרבו\u0004 ה\u0003שני,\u0004 ומדוע?","\u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: הקדש\u0004 שמקדיש אדם דבר, או איסור \u0003חמץ\u0004 שחל עליו, או \u0003שחרור\u0004 של עבד — \u0003מפקיעין מידי שיעבוד\u0004 לחוב שהיה אותו דבר או אותו עבד משועבד לפרעונו. ואם כן, מצד הדין לאחר ששיחררו רבו הראשון, העבד משוחרר לגמרי ואין המלווה יכול לתפוס אותו, \u0003אלא מפני תיקון העולם,\u0004 ומהו תיקון העולם? \u0003שמא ימצאנו\u0004 המלווה את העבד \u0003בשוק\u0004"],["\u0003ויאמר לו: \"עבדי אתה\"\u0004 לפי שהיה מיועד להיות לו כמשכון, ונמצא על ידי כך מוציא לעז על הבנים שיוולדו לו לאחר שיחרורו שהם בני עבד, לכן \u0003כופין\u0004 בית דין \u0003את רבו\u0004 ה\u0003שני,\u0004 כלומר, זה שנעשה לו אפותיקי, \u0003ועושה אותו בן חורין, וכותב\u0004 לו ה\u0003עבד שטר על דמיו,\u0004 כלומר, בשוויו. \u0003רבן שמעון בן גמליאל אומר: אין העבד כותב אלא משחרר\u0004 רבו הראשון ששיחרר אותו הוא ש\u0003כותב\u0004 ומשלם את דמי העבד לבעל החוב, שהרי היה מיועד לגביית החוב.","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]? -\u0006 \u0003במזיק שיעבודו של חבירו,\u0004 דבר המשועבד לו, \u0003קא מיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים].\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 שמזיק שיעבודו של חבירו \u0003חייב\u0004 לשלם אף שהחפץ המשועבד עצמו עדיין אינו שייך לחבירו, ויש לו רק שיעבוד עליו. ולכן בענייננו המשחרר הוא זה שכותב שטר על דמיו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 שהוא \u0003פטור\u0004 ולכן העבד הוא הכותב שטר על דמיו.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שנחלקו בכך רבן שמעון בן גמליאל וחכמים: \u0003המזיק שיעבודו של חבירו, באנו למחלוקת רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים],\u0006 ומשמע שאכן זה הוא בסיס המחלוקת במשנה.","\u0003עולא אמר\u0004 פירוש אחר למשנתנו: מה שאמרו \"שיחררו\" \u0003מי שיחררו\u0004 — \u0003רבו\u0004 ה\u0003שני\u0004 שהיה ממושכן לו עבור חובו. וכך יש לפרש את המשנה: \u0003שורת הדין אין העבד חייב כלום במצות\u0004 על ידי שיחרור זה, מפני שהשני עדיין אינו אדוניו, ואינו יכול לשחרר אותו, \u0003אלא מפני תיקון העולם, שהרי יצא עליו\u0004 על ידי מעשה זה של רבו השני \u0003שם בן חורין, כופין את רבו ראשון ועושה אותו בן חורין, וכותב\u0004 העבד לאדוניו \u0003שטר על דמיו. רבן שמעון בן גמליאל אומר:\u0004 העבד \u0003אינו כותב, אלא\u0004 ה\u0003משחרר,\u0004 בעל החוב, הוא ש\u0003כותב\u0004 שטר לאדון.","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 — \u0003בהיזק שאינו ניכר קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבן שמעון בן גמליאל \u0005סבור]\u0006 שאף היזק שאינו ניכר, שלא נגרם כל נזק מוחשי בגוף החפץ, אם גורם על ידי כך להפסד — \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003היזק,\u0004 וחייב המזיק לשלם את מה שהזיק. ואף כאן כיון שעל ידי שיחרורו של השני נאלץ האדון לשחרר את עבדו, נחשב הדבר כנזק. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא \u0005סבור]:\u0006 \u0003היזק שאינו ניכר לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק\u0004 עד שניתן לכפות אדם לשלם אותו.","ושואלים: \u0003עולא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרב\u0004 בפירוש משנתנו? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה עולא \u0005לומר]\u0006 \u0003לך:\u0004 וכי ל\u0003שני, \"רבו\" קרית ליה\u0004 \u0005[קורא אתה אותו]?!\u0006 הרי אינו אדוניו, ובסך הכל יש לו רק שיעבוד עליו!","ומצד אחר שואלים: \u0003ורב מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כעולא?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה רב \u0005לומר]\u0006 \u0003לך: שני, \"משחרר\" קרית ליה\u0004 \u0005[קורא אתה לו]?\u0006 והרי אין המעשה שעשה נחשב מעשה שיחרור, שהרי אינו יכול לשחררו כשאינו שלו!","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בבעיה דומה: אדם \u0003העושה שדהו אפותיקי לאחרים\u0004 לפרעון חובו להם \u0003ושטפה נהר,\u0004 החכם המכונה \u0003אמי שפיר\u0004 (יפה) \u0003נאה אמר\u0004 בשם \u0003ר' יוחנן:\u0004 המלווה \u0003אינו גובה משאר נכסים,\u0004 שכיון שהיה שדה זה אפותיקי — הפסיד המלווה, \u0003ואבוה\u0004 \u0005[ואביו]\u0006 של \u0003שמואל\u0004 \u0003אמר: גובה משאר נכסים.\u0004","\u0003אמר רב נחמן בר יצחק: משום שאמי שפיר\u0004 (יפה) \u0003נאה הוא, אומר שמעתא דלא שפירן\u0004 \u0005[הלכות שאינן יפות,\u0006 שאינן נכונות\u0005]?\u0006 \u0003תתרגם\u0004 \u0005[תתפרש]\u0006 \u0003שמעתיה\u0004 \u0005[הלכתו],\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה בעל השדה למלווהו במפורש: לא שתהא שדה זו סתם משכון ואחריות לחוב, אלא שאמר לו: \u0003\"לא יהא לך פרעון אלא מזו\"\u0004 ובמקרה כזה מובנים הדברים שכאשר אבד השדה — איבד המלווה את הכל.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003העושה שדהו אפותיקי לאחר ושטפה נהר\u0004 — \u0003גובה משאר נכסים, ואם אמר לו \"לא יהא לך פרעון אלא מזו\"\u0004 — \u0003אינו גובה משאר נכסים.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003העושה שדהו אפותיקי לבעל חוב\u0004 או \u0003לכתובת אשה\u0004 ואחר כך מכר את השדה — \u0003גובין משאר נכסים. רבן שמעון בן גמליאל אומר: בעל חוב גובה משאר נכסים, אשה אינה גובה משאר נכסים,\u0004 ומדוע? — לפי \u0003שאין דרכה של אשה לחזר על בתי דינין,\u0004 ומתחילה היתה כוונתו לייחד לה שדה זה בלבד כדי לחסוך לה טירחה.","\u0003מי שחציו עבד וחציו בן חורין\u0004 כגון שאחד משני שותפים שהיו בעליו שיחרר את חלקו בעבד — \u0003עובד את רבו\u0004 (אדוניו) \u0003יום אחד, ואת עצמו\u0004 (עבור עצמו) \u0003יום אחד,\u0004 אלו \u0003דברי בית הלל. בית שמאי אומרים:\u0004 על ידי סידור זה \u0003תקנתם את רבו,\u0004 שאין רבו מפסיד דבר, \u0003ו\u0004אולם \u0003את עצמו לא תקנתם,\u0004 והעבד עצמו נמצא במצב בלתי אפשרי: מן הצד האחד, \u0003לישא שפחה אי אפשר\u0004 — לפי \u0003שכבר חציו בן חורין,\u0004 ובן חורין אסור בשפחה."],["ומן הצד האחר, לשאת \u0003בת חורין אי אפשר\u0004 — \u0003שכבר חציו עבד,\u0004 ואסור הדבר. אם תאמר \u0003יבטל\u0004 מנישואין בכלל, \u0003והלא לא נברא העולם אלא לפריה ורביה, שנאמר: \"לא תהו בראה לשבת יצרה\"\u0004 (ישעיה מה, יח)! \u0003אלא מפני תיקון העולם\u0004 כדי שיוכל העבד לקיים יישובו של עולם בהעמדת ילדים — \u0003כופין\u0004 (מכריחים) \u0003את רבו ועושה אותו בן חורין, וכותב\u0004 העבד \u0003שטר חוב על חצי דמיו\u0004 (שוויו) ופורע אותו לאדון במשך הזמן. \u0003וחזרו בית הלל להורות כדברי בית שמאי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אדון \u0003המשחרר\u0004 רק את \u0003חצי עבדו\u0004 — \u0003רבי אומר: קנה,\u0004 כלומר, נגמר הדבר וחציו של העבד אכן משוחרר. \u0003וחכמים אומרים: לא קנה.\u0004","\u0003אמר רבה: מחלוקת\u0004 זו היא דווקא כששיחררו האדון \u0003בשטר\u0004 שיחרור, ש\u0003רבי סבר:\u0004 נאמר בשפחה חרופה \u0003\"והפדה לא נפדתה או חפשה לא נתן לה\"\u0004 (ויקרא יט, כ), ומוזכרות בפסוק שתי אפשרויות של שיחרור זו ליד זו: פידיון (\"והפדה\") — בכסף, ושיחרור (\"חופשה\") — בשטר.","ובזה \u0003מקיש\u0004 (משווה) הכתוב \u0003שטר לכסף; מה\u0004 ב\u0003כסף\u0004 יכול העבד לקנות \u0003בין\u0004 את \u0003כולו\u0004 ו\u0003בין\u0004 את \u0003חציו, אף שטר נמי\u0004 \u0005[גם כן]\u0006 יכול לחול \u0003בין\u0004 על \u0003כולו בין\u0004 על \u0003חציו.\u0004","\u0003ורבנן גמרי\u0004 \u0005[וחכמים למדים]\u0006 בגזירה שווה: \u0003\"\u0004חופשה לא ניתן \u0003לה\"\u0004 (ויקרא יט,כ) \"וכתב \u0003לה\u0004 ספר כריתות\" (דברים כד, א) \u0003מ\u0004גירושי \u0003אשה; מה אשה\u0004 שמתגרשת בשטר \u0003חציה לא,\u0004 שאינו יכול לגרש חציה בשטר גירושין, \u0003אף עבד נמי\u0004 \u0005[גם כן]\u0006 \u0003חציו לא. אבל בכסף\u0004 — \u0003דברי הכל קנה\u0004 העבד את מחציתו, ושפחה הנמצאת במצב זה הריהי \u0003פדויה ואינה פדויה.\u0004","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבי, \u0005סבור]:\u0006 לימוד מ\u0003הקישא עדיפא\u0004 \u0005[היקש עדיף]\u0006 ולכן הוא סומך יותר על ההיקש שבמילים \"והפדה לא נפדתה, או חופשה לא נתן לה\", \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003גזירה שוה עדיפא\u0004 \u0005[עדיפה]\u0006 ולכן סומכים על גזירה שווה של \"לה\" \"לה\"?","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[של\u0006 דעת \u0005הכל],\u0006 בדרך כלל, \u0003גזירה שוה עדיפא\u0004 \u0005[עדיפה],\u0006 \u0003ו\u0004אולם לדעת רבי \u0003שאני הכא דאיכא למיפרך\u0004 \u0005[שונה כאן, שיש\u0006 מקום \u0005לפרוך]\u0006 את הגזירה השווה, ולומר: \u0003מה לאשה שכן אינה יוצאה\u0004 (מתגרשת) \u0003בכסף\u0004 כלל, \u0003תאמר בעבד שיוצא\u0004 (משתחרר) \u0003בכסף?\u0004 ויש לומר שגם כן יוצא לחצאין. עד כאן לפי שיטת רבה.","\u0003ורב יוסף אמר: מחלוקת\u0004 רבי וחכמים היא דווקא \u0003בכסף,\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 מן הכתוב אנו יכולים ללמוד כן, שהרי נאמר \u0003\"והפדה לא נפדתה\"\u0004 — שהכתוב מדבר במי שנשתחררה חציה בכסף והריהי \u0003פדויה ואינה פדויה, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003דברה תורה כלשון בני אדם\u0004 ומשמעות הביטוי — שלא נפדתה כלל. \u0003אבל\u0004 במשחרר חציו \u0003בשטר\u0004 — \u0003דברי הכל לא קנה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב יוסף ממה ששנינו בברייתא: \u0003המשחרר חצי עבדו בשטר, רבי אומר: קנה, וחכמים אומרים: לא קנה,\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב יוסף!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","ומציעים: בברייתא זו \u0003(נימא\u0004 \u0005[נאמר]\u0006\u0003) בשטר הוא דפליגי\u0004 \u0005[שחלוקים],\u0006 \u0003אבל בכסף לא פליגי\u0004 \u0005[אינם חלוקים]\u0006 שהיא נפדית, ואם כן, \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רב יוסף בתרתי\u0004 \u0005[בשתים],\u0006 אחת, שלדעתו בשטר רבי מודה ואילו בברייתא שנינו שהוא חולק, והשניה, שלדבריו המחלוקת היא בכסף ואילו מדיוק דברי הברייתא ניתן להבין שבכסף מודים חכמים שקנה!","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יוסף: פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 \u0003בשטר, והוא הדין בכסף, והא דקא מיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 במפורש \u0003בשטר\u0004 — \u0003להודיעך כחו\u0004 של \u0003רבי\u0004 עד כמה הוא מתיר.","ושואלים: \u0003וליפלגי\u0004 \u0005[ושיחלקו]\u0006 \u0003בכסף, ולהודיעך כחן דרבנן\u0004 \u0005[של חכמים]\u0006 עד כמה הם אוסרים! ומשיבים: \u0003כח דהיתירא\u0004 \u0005[של היתר]\u0006 \u0003עדיף ליה\u0004 \u0005[לו]\u0006 להשמיע לנו, ולכן מנוסחת המחלוקת בצורה זו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שדרשו תנאים בברייתא על הפסוק העוסק בשפחה חרופה: מה שנאמר \u0003\"והפדה\",\u0004 \u0003יכול לכל,\u0004 שהיא פדויה גמורה? — \u0003תלמוד לומר: \"לא נפדתה\". אי\u0004 \u0005[אם]\u0006 \u0003\"לא נפדתה\", יכול לכל\u0004 שהיא שפחה גמורה? — \u0003תלמוד לומר: \"והפדה\"; הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יתקיימו שני הכתובים? — \u0003פדויה ואינה פדויה.\u0004 דברים אלה אמורים במי שנפדתה \u0003בכסף ובשוה כסף.\u0004","\u0003ואין לי אלא בכסף, בשטר מנין?\u0004 — \u0003תלמוד לומר: \"והפדה לא נפדתה או חפשה לא נתן לה\"\u0004 (ויקרא יט, כ) \u0003ולהלן הוא אומר: \"וכתב לה ספר כריתת\"\u0004 (דברים כד, א), \u0003מה להלן\u0004 באשה \u0003בשטר\u0004 הוא, \u0003אף כאן\u0004 לגבי יציאת השפחה לחופשי מדובר \u0003בשטר.\u0004","\u0003אין לי אלא\u0004 ש\u0003חציו\u0004 של עבד יכול להיפדות \u0003בכסף\u0004 (\"והפדה לא נפדתה\") \u0003או כולו בשטר\u0004 (\"חופשה\"), \u0003חציו בשטר מנין?\u0004 — \u0003תלמוד לומר: \"והפדה לא נפדתה או חפשה לא נתן לה\", מקיש\u0004 הכתוב \u0003שטר לכסף, מה כסף בין כולו בין חציו\u0004 יכול להיפדות בו, \u0003אף שטר נמי\u0004 \u0005[גם כן]\u0006 \u0003בין כולו בין חציו.\u0004 עד כאן לשון הברייתא.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב יוסף בתר דאיתותב\u0004 \u0005[אחרי שהושב,\u0006 שנדחו דבריו\u0005]\u0006 והוא מסביר שבין בשטר ובין בכסף נחלקו רבי וחכמים, \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי]\u0006 — כשיטת \u0003רבי היא,\u0004 שבשניהם משתחרר חציו. \u0003אלא ל\u0004שיטת \u0003רבה\u0004 שנחלקו רבי וחכמים רק בשטר, אבל בכסף לדברי הכל קנה חציו, \u0003רישא\u0004 \u0005[ראשה]\u0006 שמשתחרר חציו בכסף כ\u0003דברי הכל, וסיפא\u0004 \u0005[וסופה]\u0006 שמשתחרר חציו בשטר דווקא כשיטת \u0003רבי?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבה: אין\u0004 \u0005[כן],\u0006 \u0003רישא\u0004 \u0005[ראשה]\u0006 \u0003דברי הכל, וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003רבי. רב אשי אמר:\u0004 ברייתא זו כולה דברי \u0003רבי היא.\u0004","ושואלים: \u0003אלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה]\u0006 בה: \u0003מי שחציו עבד וחציו בן חורין, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רבה, מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 במקרה ששיחרר האדון את חציו של העבד \u0003בכסף ודברי הכל\u0004 היא, \u0003אלא לרב יוסף, לימא\u0004 \u0005[האם תאמר]\u0006 שלדעתו משנתנו כשיטת \u0003רבי היא ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 שהרי לדעתו חכמים סבורים שאינו יכול לשחרר חצי עבדו כלל, בין בכסף ובין בשטר! \u0003אמר רבינא:\u0004"],["במשנתנו מדובר \u0003בעבד של שני שותפין,\u0004 ובמקרה כזה ל\u0003דברי הכל,\u0004 גם לדעת חכמים, כל אחד מהם יכול לשחרר את כל חלקו בעבד, ונמצא העבד משוחרר חציו.","ועוד בדבר המחלוקת במשחרר חצי עבדו, \u0003אמר רבה: מחלוקת\u0004 רבי וחכמים אם קנה העבד חציו — דווקא \u0003בששיחרר\u0004 האדון את \u0003חציו והניח\u0004 את \u0003חציו\u0004 השני, \u0003אבל\u0004 אם \u0003שיחרר\u0004 את \u0003חציו ומכר\u0004 את \u0003חציו\u0004 השני, \u0003או נתן במתנה\u0004 את \u0003חציו\u0004 השני, \u0003כיון דקנפיק מיניה כוליה\u0004 \u0005[ש\u0006העבד \u0005יוצא ממנו כולו]\u0006 — \u0003דברי הכל קנה\u0004 העבד את חציו עצמו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וב\u0004מקרה שיוצא ממנו \u0003כולו לא פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003והתני חדא\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003הכותב נכסיו לשני עבדיו\u0004 — \u0003קנו\u0004 את הנכסים \u0003ומשחררין זה את זה,\u0004 שלכל אחד יש בעלות בחציו של חבירו. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003האומר: \"כל נכסי נתונין לפלוני ופלוני עבדיי\"\u0004 — \u0003אף עצמם לא קנו,\u0004 וכל שכן את הנכסים.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 זה ההסבר לסתירה בין הברייתות הללו: \u0003הא\u0004 \u0005[זו],\u0006 הברייתא הראשונה — כשיטת \u0003רבי,\u0004 שיש שיחרור לחצי עבד, \u0003והא\u0004 \u0005[וזו],\u0006 הברייתא השניה — כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שאף שכל אחד מהם יצא לגמרי מרשותו של האדון, הואיל ולא נשתחררו לגמרי לא קנו?","ודוחים: \u0003לא, אידי ואידי רבנן\u0004 \u0005[זו וזו\u0006 כשיטת \u0005חכמים],\u0006 אלא \u0003הא\u0004 \u0005[זו],\u0006 בברייתא הראשונה מדובר ש\u0003אמר כולו,\u0004 שלכל אחד מהם הוא נותן את כל נכסיו. וכיון שנתן לשניהם — שניהם קונים, ומשחררים זה את זה, ומחלקים ביניהם את הנכסים. \u0003הא\u0004 \u0005[זו],\u0006 בברייתא השניה מדובר ש\u0003אמר חצי חצי,\u0004 שלכל אחד מהם נתן רק מחצית נכסיו, ולא הקנה לאף אחד מהם קנין גמור.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה\u0006 ב\u0005סופה]\u0006 של הברייתא השניה: \u0003ואם אמר חצי חצי\u0004 — \u0003לא קנו, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבראשה]\u0006 מדובר ש\u0003אמר כולו!\u0004 ומשיבים: אין להבין שיש כאן דין נוסף בברייתא אלא \u0003פרושי קא מפרש\u0004 \u0005[מפרש]\u0006 את דברי הברייתא הקודמים: \u0003אף עצמן לא קנו, כיצד? כגון\u0004 ש\u0003אמר חצי חצי.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003דאי סלקא דעתך רישא\u0004 \u0005[שאם עולה על דעתך\u0006 שב\u0005ראשה]\u0006 של הברייתא מדובר ש\u0003אמר כולו,\u0004 אם כן, סופה מיותר, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003אמר כולו לא קנו, אמר חצי חצי מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 \u0003לא איריא\u0004 \u0005[שייך]\u0006 ואין מכאן הוכחה, שכן אפשר לומר ש\u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005סופה\u0006 כדי \u0005לגלות\u0006 את משמעות \u0005ראשה],\u0006 \u0003שלא תאמר: רישא\u0004 \u0005[ראשה]\u0006 עוסק במקרה ש\u0003אמר חצי חצי, אבל\u0004 אם \u0003אמר כולו קנו,\u0004 על כן \u0003תנא סיפא\u0004 \u0005[שנה בסופה]\u0006 ש\u0003אמר חצי חצי,\u0004 ו\u0003מכלל\u0004 הדברים נלמד \u0003דרישא\u0004 \u0005[ש\u0006ב\u0005ראשה]\u0006 מדובר ש\u0003אמר כולו ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא קנו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 ואפשר ליישב את הסתירה בין הברייתות בדרך אחרת: \u0003כאן,\u0004 בברייתא השניה שלא קנו, מדובר \u0003בשטר אחד,\u0004 שכן אין אפשרות לשחרר שני עבדים בשטר אחד, \u0003כאן\u0004 בברייתא הראשונה שקנו, מדובר \u0003בשני שטרות.\u0004","ושואלים: אם בברייתא השניה מדובר שהקנה לשניהם את נכסיו \u0003בשטר אחד, מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע היה צריך לומר שכשאמר \u0003חצי חצי\u0004 לא קנו? \u0003אפילו אמר כולו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנו,\u0004 וכפי ששנינו במפורש בתחילת הברייתא, ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, זוהי כוונת הדברים: \u0003אף עצמן לא קנו, במה דברים אמורים\u0004 שלא קנו? כשנתן להם \u0003בשטר אחד, אבל בשני שטרות\u0004 — \u0003קנו, ואם אמר חצי חצי\u0004 — \u0003אף בשני שטרות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קנו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן זה ליישב את הסתירה בין הברייתות: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן,\u0004 בברייתא הראשונה, שקנו, מדובר שנתן להם \u0003בבת אחת, כאן\u0004 בברייתא השניה, שלא קנו, מדובר שנתן להם \u0003בזה אחר זה.\u0004","ושואלים: אם נתן בזה אחר זה, \u0003בשלמא בתרא לא קני\u0004 \u0005[נניח\u0006 ש\u0005האחרון אינו קונה],\u0006 \u0003דהא קני ליה קמא\u0004 \u0005[שהרי\u0006 כבר \u0005קנה אותו הראשון],\u0006 \u0003אלא קמא ליקני נפשיה ולקנייה לחבריה\u0004 \u0005[הראשון שיקנה\u0006 את \u0005עצמו ושיקנה\u0006 גם \u0005את חבירו]!\u0006 \u0003אלא, מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שתירצנו מתחילה],\u0006 ובכל אופן מדובר שנתן להם בבת אחת.","\u0003רב אשי אמר:\u0004 כך יש ליישב את הסתירה בין שתי הברייתות, \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בברייתא השניה, \u0003דקא קרי להו\u0004 \u0005[ש\u0006הוא \u0005קורא להם]\u0006 \u0003\"עבדיי\",\u0004 משמע שאין כאן שיחרור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רפרם לרב אשי: ודלמא\u0004 \u0005[ושמא]\u0006 מה שאומר \u0003\"עבדיי\"\u0004 כוונתו אלה \u0003שהיו כבר\u0004 עבדיי בעבר!","וראיה לדבר: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדומה לכך: \u0003הכותב כל נכסיו לעבדו\u0004 — \u0003יצא לחירות,\u0004 ואם \u0003שייר קרקע כל שהוא\u0004 — \u0003לא יצא לחירות. ר' שמעון אומר: לעולם\u0004 העבד \u0003הוא בן חורין, עד שיאמר\u0004 בנוסח כזה: \u0003\"כל נכסי נתונין לפלוני עבדי חוץ מאחד מרבוא\u0004 (רבבה) \u0003שבהן\".\u0004","ונדייק מן הדברים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר: \"חוץ מאחד מרבוא שבהן\",\u0004 שאפשר שרומז בכך לעבד עצמו שהוא הדבר שלא נתן לו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אמר הכי\u0004 \u0005[כך]\u0006 — \u0003קני\u0004 \u0005[קונה]\u0006 העבד. ואילו להסברך \u0003אמאי\u0004 \u0005[מדוע]\u0006 קונה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עבד\" קא קרי ליה\u0004 \u0005[הוא קורא לו]!\u0006 \u0003אלא\u0004 בהכרח יש לפרש שמה שקורא לו \u0003\"עבדי\"\u0004 כוונתו \u0003שהיה כבר\u0004 בעבר עבדו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כשאמר \u0003\"עבדיי\"\u0004 כוונתו: אלה \u0003שהיו כבר\u0004 עבדיי, ואי אפשר ליישב כרב אשי את הסתירה בין שתי הברייתות.","מי שהיה חציו עבד וחציו בן חורין ו\u0003נגחו שור\u0004 והזיקו, אם נגחו ב\u0003יום\u0004 שבו עבודתו היא \u0003של רבו\u0004 — הרי תשלום הנזק שייך \u0003לרבו,\u0004 ואם היה זה \u0003יום של עצמו\u0004 — \u0003לעצמו.\u0004 ומקשים: \u0003אלא מעתה,\u0004 לפי עיקרון זה של חלוקה, ב\u0003יום של רבו ישא שפחה,\u0004 ואילו ב\u0003יום של עצמו ישא בת חורין!\u0004 ומשיבים: \u0003איסורא לא קאמרינן\u0004 \u0005[\u0006לגבי \u0005איסור אין אנו אומרים]\u0006 שהעבד מתחלק כך.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003המית\u0004 השור \u0003מי שחציו עבד וחציו בן חורין\u0004 — \u0003נותן\u0004 בעל השור \u0003חצי קנס\u0004 (תשלום לבעלי עבד שנהרג) \u0003לרבו\u0004 (אדוניו)"],["\u0003וחצי כופר\u0004 (דמי ההרוג כשהוא בן חורין) יתן \u0003ליורשיו\u0004 של המשוחרר למחצה. ולשיטה זו יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 כך הוא דרך התשלום? \u0003הכי נמי לימא\u0004 \u0005[כך גם כן נאמר]:\u0006 אם הרגו השור ב\u0003יום של רבו\u0004 — יתן \u0003לרבו,\u0004 \u0003יום של עצמו\u0004 — יתן \u0003לעצמו,\u0004 או ליורשיו! ומשיבים: \u0003שאני הכא דקא כליא קרנא\u0004 \u0005[שונה כאן שכלתה הקרן],\u0006 שהרי מת העבד, ומשום כך מגיע חצי לרבו, גם אם נגחו השור ביום של העבד, שהרי סוף סוף חציו שייך לו.","ושואלים: \u0003ואלא היכי דמי דלא קא כליא קרנא\u0004 \u0005[איך הוא בדיוק\u0006 מקרה זה \u0005ש\u0006בו \u0005אין הקרן כלה]\u0006 שבו נקבע הזכאי בתשלומים לפי היום שבו הזיק השור את העבד? ומסבירים: \u0003כגון שהכהו\u0004 השור \u0003על ידו וצמתה\u0004 (נעשתה משותקת) \u0003ידו ו\u0004אולם \u0003סופה לחזור\u0004 ולהתרפא.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי,\u0004 ש\u0003אמר:\u0004 אדם שחובל בחבירו באופן כזה שגורם לו שיתוק זמני — \u0003נותן לו שבת גדולה,\u0004 כלומר, את ה\"נזק\" — מה שפוחת מחירו כעת בגלל השיתוק, \u0003ו\u0004גם \u0003שבת קטנה\u0004 על שבטל מכל מלאכה ומפסיד אף שכר עבודה שהיה יכול לעשות בהיותו משותק — \u0003שפיר\u0004 \u0005[יפה],\u0006 שגם מי שהזיק שורו — משלם נזק, שבת גדולה.","\u0003אלא ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר: אינו נותן לו אלא שבתו שבכל יום ויום,\u0004 ולא את השבת של פחת מחירו (\"נזק\"), משום שסופו להתרפא ולשוב לכפי שהיה, הלוא \u0003האי\u0004 \u0005[זה]\u0006 שהזיק — \u0003שור הוא, ושור,\u0004 כלומר, בעליו, \u0003אינו משלם אלא נזק,\u0004 ואינו משלם שבת כלל, ואיך מסביר רבא את הדברים?","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר כאן \u0003כשהכהו אדם\u0004 ולא שור. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 דבר זה \u0003מימרא\u0004 \u0005[מאמר\u0006 של אמוראים\u0005]\u0006 \u0003היא, ומימרא\u0004 \u0005[ומאמר\u0006 זה\u0005]\u0006 \u0003לרבא לא סבירא ליה\u0004 \u0005[מסתבר לו,\u0006 אינו מקבלה\u0005].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה זו ללומדים: עבד שמבחינה ממונית יצא מרשות אדוניו, אבל עדיין הוא \u0003מעוכב גט שחרור,\u0004 שלא ניתן לו עדיין שטר השיחרור שלו, האם \u0003יש לו,\u0004 לאדוניו, \u0003קנס\u0004 כדין כל עבד שהומת על ידי שור, \u0003או אין לו קנס?\u0004","והצדדים שבשאלה הזו: \u0003\"כסף שלשים שקלים יתן לאדניו\"\u0004 (שמות כא, לב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והאי לאו\u0004 \u0005[וזה לא]\u0006 \u0003\"אדון\" הוא,\u0004 שהרי העבד בפועל משוחרר. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003מחוסר גט\u0004 (שטר) \u0003שחרור\u0004 — עדיין \u0003\"אדון\" קרינא ביה\u0004 \u0005[קוראים אנו בו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003המית מי שחציו עבד וחציו בן חורין\u0004 — \u0003נותן חצי קנס לרבו וחצי כופר ליורשיו. מאי לאו\u0004 \u0005[האם לא]\u0006 שברייתא זו היא \u0003כ\u0004שיטת \u0003משנה אחרונה,\u0004 לאחר שהודו בית הלל לבית שמאי שלכל הדעות אין העבד הזה עובד עוד בשביל אדוניו, אף שלא קיבל עדיין את שטר השיחרור, ובכל זאת נאמר שאדוניו מקבל חצי קנס?","ודוחים: \u0003לא,\u0004 שיטת הברייתא היא \u0003כ\u0004שיטת \u0003משנה ראשונה\u0004 של בית הלל, שעובד את עצמו יום אחד ואת אדוניו יום אחד, ולפי שיטה זו הוא אינו עומד לשיחרור כלל, ואין מכאן איפוא פתרון לשאלה שנשאלה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו: \u0003הפיל את שינו\u0004 של עבדו, \u0003ו\u0004אחר כך \u0003סימא את עינו\u0004 — \u0003יוצא\u0004 העבד לחירות \u0003ב\u0004גלל \u0003שינו\u0004 כמפורש בכתוב \"לחופשי ישלחנו תחת שינו\" (שמות כא, כז), \u0003ונותן\u0004 לו האדון \u0003דמי עינו\u0004 כאילו היה בן חורין. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שעבד שעדיין לא קיבל שטר שיחרור \u0003יש לו קנס וקנס לרבו,\u0004 יש לתהות: \u0003השתא חבלי ביה אחריני יהבי ליה לרביה\u0004 \u0005[עכשיו,\u0006 הרי, אם \u0005חובלים בו אחרים\u0006 הם \u0005נותנים לו\u0006 את הקנס \u0005לרבו],\u0006 \u0003חבל ביה רביה גופיה, יהיב ליה לדידיה\u0004 \u0005[\u0006אם \u0005חובל בו אדוניו עצמו, יתן לו לעצמו]\u0006 דמי עינו?","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 ברייתא זו סבורה \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 שבמקרה של שיחרור עבד בגלל הפלת שן \u0003אינו צריך\u0004 שטר שיחרור, אלא משתחרר מיד עם הפגיעה בו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בכולן,\u0004 בכל עשרים וארבעה ראשי איברים שהגדירו חכמים שעבד יוצא בהם לחופשי אם חבל בו רבו באחד מהם, \u0003עבד יוצא בהם לחירות, וצריך גט\u0004 (שטר) \u0003שחרור מרבו,\u0004 אלו \u0003דברי ר' ישמעאל. ר' מאיר אומר:\u0004 \u0003אינו צריך\u0004 שטר שיחרור. \u0003ר' אלעזר אומר: צריך. ר' טרפון אומר: אינו צריך. ר' עקיבא אומר: צריך.\u0004","\u0003המכריעין לפני חכמים,\u0004 כלומר, אותם חכמים שהיו בודקים ומנסים להכריע בשיטות ולתווך ביניהן \u0003אומרים\u0004 כך: \u0003נראים דברי ר' טרפון\u0004 שאינו צריך שטר שיחרור — \u0003בשן ועין, הואיל ותורה זכתה לו\u0004 במפורש את שיחרורו (שמות כא, כו-כז), \u0003ו\u0004נראים \u0003דברי ר' עקיבא\u0004 שצריך לכתוב לו שטר שיחרור — \u0003בשאר אברים, הואיל וקנס חכמים הוא.\u0004","על הלשון תוהים: \u0003קנס\u0004 חכמים?! \u0003הא קראי קא דרשינן\u0004 \u0005[הרי מקראות אנו דורשים]\u0006 ללמוד שהעבד משתחרר לא רק בחבלת שן ועין אלא גם בחבלה באיברים אלה! \u0003אלא אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 \u0003הואיל ומדרש חכמים הוא,\u0004 ולא נכתב כן במפורש בתורה.","ועוד בענין מעוכב גט שיחרור \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003מעוכב גט\u0004 (שטר) \u0003שחרור\u0004 שהיה עבדו של כהן, האם \u0003אוכל בתרומה או אינו אוכל?\u0004 והצדדים בשאלה: \u0003\"קנין כספו\u0004 הוא יאכל בו\u0003\"\u0004 (ויקרא כב, יא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003קנין כספו הוא, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003מחוסר\u0004 עדיין \u0003גט שחרור, \"קנין כספו\" קרינא ביה\u0004 \u0005[קוראים אנו בו]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לשאלה ממה ש\u0003אמר רב משרשיא: כהנת שנתערב ולדה בולד שפחתה\u0004 שילדו שתיהן ילדים, ונתערבו הילדים ולא ברור מיהו כל אחד מהם — \u0003הרי אלו,\u0004 שני הילדים, \u0003אוכלין בתרומה, וחולקין\u0004 (מקבלים יחד) \u0003חלק אחד\u0004 של תרומה \u0003על הגורן,\u0004 שהרי אחד מהם הוא כהן ומגיע לו בשביל עצמו, והשני הוא עבד והוא אוכל מכוח האדון. וכאשר \u0003הגדילו התערובות\u0004 — \u0003משחררין זה את זה\u0004 ונמצא העבד שביניהם נעשה בן חורין. משמע שאף שילד זה שהיה בן שפחה עומד לשיחרור, בכל זאת, כיון שהוא מעוכב עדיין שטר שיחרור — הריהו אוכל בתרומה!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003אם יבא אליהו ויאמר בחד מינייהו\u0004 \u0005[על אחד מהם]\u0006 ש\u0003עבד הוא,\u0004 אם כן, \u0003\"קנין כספו\" קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 לכל ענין, ומה שצריכים לשחרר זה את זה הוא רק מחמת חוסר ידיעתנו, שאין בידינו דרכים לגלות מיהו בן השפחה. אבל \u0003הכא לאו\u0004 \u0005[כאן לא]\u0006 \u0003קנין כספו הוא כלל,\u0004 כיון ששיחררו, אף שעדיין לא נתן לו שטר — שמא אינו נחשב כבר כקנין כספו, ולא נפתרה איפוא השאלה.","ועוד בענין הזכות בקנס של עבד: \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003עבד שמכרו רבו\u0004 לאדם אחר רק \u0003ל\u0004ענין \u0003קנס,\u0004 כלומר, שאם יהרג על ידי שור — שהקנס יהיה שייך לקונהו אבל לשאר הדברים לא מכרו, האם הוא \u0003מכור או אינו מכור?\u0004 כלומר, האם חלה מכירה זו.","ומסבירים: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003ל\u0004דעת \u0003ר' מאיר, תיבעי לרבנן\u0004 \u0005[תישאל ל\u0006דעת \u0005חכמים].\u0006 \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003ל\u0004דעת \u0003ר' מאיר; עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' מאיר\u0004 ש\u0003אדם מקנה דבר שלא בא לעולם, אלא כגון\u0004 המוכר \u0003פירות דקל דעבידי דאתו\u0004 \u0005[שעשויים שיבואו],\u0006 שדרך הטבע הוא שהם צומחים, ולכן יכול למכור דבר עתידי, אף על פי שאינו מצוי כעת, \u0003אבל הכא מי יימר דמינגח\u0004 \u0005[כאן מי יאמר ש\u0006העבד כלל \u0005יינגח]?\u0006 \u0003ואם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר דמינגח\u0004 \u0005[שיינגח],\u0006 \u0003ממאי דמשלם\u0004 \u0005[מניין\u0006 יודע אתה \u0005שישלם]\u0006 בעל השור שנגחו את הקנס?"],["\u0003דלמא מודה ומיפטר\u0004 \u0005[שמא יודה וייפטר]\u0006 מחיובו בקנס, שכן המודה בעבירה שחייבים עליה קנס פטור מן הקנס!","\u0003ו\u0004כמו כן \u0003תבעי\u0004 \u0005[תישאל]\u0006 השאלה גם \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים];\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן\u0004 \u0005[אומרים חכמים]\u0006 ש\u0003אין אדם מקנה דבר שלא בא לעולם\u0004 — \u0003אלא כגון פירות דקל, דהשתא מיהא ליתנהו\u0004 \u0005[שעכשיו על כל פנים אינם\u0006 בעולם\u0005],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003הא קאי\u0004 \u0005[הרי עומד,\u0006 נמצא\u0005]\u0006 ה\u0003שור והא קאי\u0004 \u0005[והרי עומד,\u0006 נמצא\u0005]\u0006 ה\u0003עבד,\u0004 ואין צורך במציאות חדשה שתבוא לעולם. אם כן, \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","\u0003אמר ר' אבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממדרש הלכה על הכתוב המדבר באלה האוכלים כתרומה, שנאמר: \"וכהן כי יקנה נפש קנין כספו הוא יאכל בו ויליד ביתו הם יאכלו בלחמו\" (ויקרא כב, יא), וכך דרשו: \u0003\"ויליד בית\" מה תלמוד לומר?\u0004 לכאורה מה צורך בכתוב מיוחד לדבר? שהרי \u0003אם\u0004 מי שהוא עבד שהוא \u0003קנין כסף\u0004 בלבד \u0003אוכל, יליד בית\u0004 שנולד לשפחתו של הכהן \u0003לא כל שכן?\u0004","ומשיבים: \u0003אילו כן\u0004 — רק לפי קל וחומר זה — \u0003הייתי אומר: מה קנין כסף\u0004 רק זה \u0003שיש בו שוה כסף\u0004 — הוא \u0003אוכל, אף יליד בית\u0004 רק זה \u0003שיש בו שוה כסף\u0004 — \u0003אוכל, ומנין שאף על פי שאינו שוה כלום?\u0004 — \u0003תלמוד לומר: \"יליד בית\", מכל מקום.\u0004","\u0003ועדיין אני אומר\u0004 מצד שני: \u0003יליד בית\u0004 — \u0003בין שיש בו שוה כסף בין שאין בו שוה כסף\u0004 — \u0003אוכל, קנין כסף\u0004 — אם \u0003יש בו שוה כסף\u0004 — \u0003אוכל, אין בו שוה כסף\u0004 — \u0003אינו אוכל. תלמוד לומר: \"קנין כספו... ויליד ביתו\u0004 הם יאכלו בלחמו\u0003\"\u0004 (ויקרא כב, יא), שהכתוב משווה אותם, לומר: \u0003מה יליד בית אף על פי שאינו שוה כלום\u0004 — \u0003אוכל\u0004 בתרומה, \u0003אף קנין כספו, אף על פי שאינו שוה כלום\u0004 — \u0003אוכל.\u0004 עד כאן לשון הברייתא, וממנה עולה כי יש מציאות של עבד שאינו שווה כלום.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003עבד שמכרו רבו לקנס\u0004 — \u0003מכור, מי איכא עבדא דלא מזדבין לקנסא\u0004 \u0005[האם יש עבד שאינו ניתן להימכר ל\u0006צורך \u0005קנס]?\u0006 שאפילו אם אינו שווה כלום מצד עצמו, יש עדיין שווי כלשהו למכירתו לאחר שיקבל את קנסו! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 מקרה כזה של \u0003עבד טרפה\u0004 (עתיד למות), שכיון שהוא טריפה, גם אם הרג אותו שור — אין משלמים עליו קנס, ולכן אותו עבד אינו שווה כלום, ואף לא למכירה לקנס.","ומקשים: \u0003והא חזי למיקם קמיה\u0004 \u0005[הרי ראוי\u0006 הוא \u0005לעמוד לפניו]\u0006 לשם כבוד, גם אם אינו ראוי לעבוד עבודה אחרת, ואיך ניתן לדבר עליו כעל עבד שאינו שווה כלום! ומשיבים: מדובר פה \u0003ב\u0004עבד שלא רק שהוא טריפה, שאין לו קנס, אלא גם \u0003מנוול\u0004 (מלוכלך) או \u0003מוכה שחין\u0004 שאין זה כבוד לו שיעמוד לפניו, ולכן אינו שווה כלום. ולא נפתרה איפוא השאלה אם חלה מכירת עבד רק לענין הקנס.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003מי שחציו עבד וחציו בן חורין שקידש\u0004 אשה \u0003בת חורין, מהו\u0004 הדין? והצדדים בשאלה זו: \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ש\u0003בן ישראל שאמר לבת ישראל: \"התקדשי לחציי\"\u0004 — \u0003מקודשת,\u0004 הרי זה משום \u0003דחזיא לכוליה\u0004 \u0005[ש\u0006היא \u0005ראויה לכולו],\u0006 אבל כאן \u0003הא לא חזיא לכוליה\u0004 \u0005[הרי אינה ראויה לכולו]\u0006 לפי שחציו עבד, ולכן אין אלו קידושין כלל.","\u0003ו\u0004לאידך גיסא, \u0003אם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ש\u0003בן ישראל המקדש חצי אשה\u0004 — \u0003אינה מקודשת,\u0004 ומדוע? משום ש\u0003שייר בקנינו\u0004 שהרי בקנין קידושין הוא קונה אשה שלימה ולא חצי אשה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עבד\u0004 זה \u0003לא שייר\u0004 \u0003בקנינו,\u0004 אלא קנה כל כמה שיכול לקנות, אם כן יש פה מצד זה שלימות בקנין, \u0003מאי\u0004 \u0005[מה]\u0006 הדין בקידושין אלה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003המית\u0004 שור \u0003מי שחציו עבד וחציו בן חורין\u0004 — \u0003נותן חצי קנס לרבו וחצי כופר ליורשיו. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003קידושיו לאו\u0004 \u0005[אינם]\u0006 \u0003קידושין,\u0004 ואינו יכול לשאת אשה, \u0003יורשין מנא ליה\u0004 \u0005[מניין לו]?\u0006 אלא ודאי יכול לקדש ולשאת אשה, ועל ידי כך, להעמיד לו יורשים!","\u0003אמר רב אדא בר אהבה:\u0004 כאן מדובר באופן שהשור לא הרגו ממש אלא \u0003כשעשאו טרפה,\u0004 והרי הוא נחשב כמת לענין זה, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"יורשיו\"\u0004 שאמרנו פה — \u0003נפשיה\u0004 \u0005[\u0006הוא \u0005עצמו].\u0006","\u0003אמר רבא, שתי תשובות בדבר\u0004 לדחות הסבר זה: \u0003חדא\u0004 \u0005[אחת]\u0006 ש\u0003\"יורשיו\" קתני\u0004 \u0005[שנה]\u0006 והוא עצמו אינו נקרא \"יורשיו\". \u0003ועוד, כופר הוא\u0004 המדובר כאן, \u0003ואמר ריש לקיש: כופר אין משתלם אלא לאחר מיתה,\u0004 ולא בחיי הנפגע, אפילו ניזוק קשה כדי שייחשב טריפה! \u0003אלא אמר רבא:\u0004 זה ששנינו שחצי כופר ליורשיו — כוונתו \u0003ראוי ליטול ואין לו,\u0004 שהכוונה לומר שאם היו לו יורשים היו הם ראויים ליטול, אבל כיון שאין לו יורשים — בפועל אין אף אחד מקבל.","\u0003אמר רבא: כשם שהמקדש חצי אשה\u0004 — \u0003אינה מקודשת, כך\u0004 מי שהיתה \u0003חציה שפחה וחציה בת חורין שנתקדשה\u0004 — \u0003אין קדושיה קדושין.\u0004","מסופר: \u0003דרש רבה בר רב הונא\u0004 הלכה זו ברבים: \u0003כשם שהמקדש חצי אשה\u0004 — \u0003אינה מקודשת, כך חציה שפחה וחציה בת חורין שנתקדשה\u0004 — \u0003אינה מקודשת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא\u0004 בשאלה: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 המקדש חצי אשה \u0003שייר בקנינו,\u0004 שלא קנה את כל האשה, ולכן אין הקידושין תופסים, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 חציה שפחה וחציה בת חורין שהתקדשה \u0003לא שייר בקנינו\u0004 אלא שזה כל מה שיכול לקנות בה, וממילא הקידושין תופסים!","\u0003הדר אוקים\u0004 \u0005[חזר\u0006 ו\u0005העמיד]\u0006 \u0003רבה בר רב הונא אמורא עליה\u0004 \u0005[מתורגמן עליו,\u0006 לפניו\u0005]\u0006 שישמיע את דבריו לרבים, \u0003ודרש\u0004 כך את הכתוב \u0003\"והמכשלה הזאת תחת ידך\"\u0004 (ישעיהו ג, ו): \u0003אין אדם עומד על דברי תורה אלא אם כן נכשל בהן,\u0004 ואני עצמי נכשלתי בהוראתי הקודמת, והנני חוזר בי מדברי ואומר ש\u0003אף על פי שאמרו\u0004 חכמים ש\u0003המקדש חצי אשה\u0004 — \u0003אינה מקודשת, אבל חציה שפחה וחציה בת חורין שנתקדשה\u0004 — \u0003קדושיה קדושין. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003התם\u0004 \u0005[שם]\u0006 במקדש חצי אשה \u0003שייר בקנינו, הכא\u0004 \u0005[כאן]\u0006 במקדש חציה שפחה וחציה בת חורין \u0003לא שייר בקנינו.\u0004","\u0003אמר רב ששת\u0004 בניגוד לכך: \u0003כשם שהמקדש חצי אשה אינה מקודשת, כך חציה שפחה וחציה בת חורין שנתקדשה\u0004 — \u0003אין קידושיה קידושין. ואם לחשך אדם לומר\u0004 (אם יבוא אדם לומר לך ולהקשות על כך), ממה ששנינו במשנה: \u0003איזו היא שפחה חרופה\u0004 הכתובה בתורה? \u0003זו שחציה שפחה וחציה בת חורין המאורסה לעבד עברי, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003בת איתרוסי\u0004 \u0005[אירוסין]\u0006 \u0003היא! אמור לו\u0004 שאין מכאן ראיה כלל: \u0003כלך\u0004 (לך) \u0003אצל\u0004 שיטת \u0003ר' ישמעאל, שהוא אומר\u0004 שאין מדובר פה בחציה שפחה אלא \u0003בשפחה כנענית המאורסה לעבד עברי\u0004 מדובר.","ועל כך יש לשאול: \u0003ו\u0004כי \u0003שפחה כנענית בת איתרוסי\u0004 \u0005[אירוסין]\u0006 \u0003היא? אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מאורסת\"\u0004 בענין זה — כוונתו ש\u0003מיוחדת\u0004 לו, ונעשתה כאשתו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בלשון המשנה, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מאורסת\"\u0004 — \u0003מיוחדת\u0004 ולא אירוסין ממש.","\u0003אמר רב חסדא:\u0004 מי שהיתה \u0003חציה שפחה וחציה בת חורין שנתקדשה לראובן ו\u0004אחר כך \u0003נשתחררה\u0004 כולה, \u0003וחזרה ונתקדשה לשמעון\u0004 אחיו, \u0003ומתו שניהם\u0004 בלא בנים — \u0003מתייבמת ללוי\u0004 האח השלישי, משום שהיא נחשבת לאשתו הגמורה של אחד מאחיו בלבד,"],["\u0003ואין אני קורא בה\u0004 (מחשיב אותה) \u0003אשת שני מתים,\u0004 כי יבמה שהיתה עליה זיקת יבום משום שני אנשים, אינה מתייבמת כלל. והטעם במקרה שלנו, שאין הדבר כך, הוא: \u0003מה נפשך\u0004 (מה רצונך לומר), בכל אופן שתרצה להבין, יהא זה הדין, כי \u0003אי קדושי\u0004 \u0005[אם קידושין]\u0006 של \u0003ראובן קדושין\u0004 — \u0003קדושי\u0004 \u0005[קידושין]\u0006 של \u0003שמעון לאו\u0004 \u0005[אינם]\u0006 \u0003קדושין,\u0004 ונמצא שהיא אלמנתו של ראובן, \u0003ואי קדושי\u0004 \u0005[ואם קידושין]\u0006 של \u0003שמעון קדושין\u0004 — \u0003קדושי\u0004 \u0005[קידושין]\u0006 של \u0003ראובן לאו\u0004 \u0005[אינם]\u0006 \u0003קדושין\u0004 וממילא היא אלמנתו של אדם אחד בלבד ולא של שניים.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: מי שהיתה \u0003חציה שפחה וחציה בת חורין שנתקדשה לראובן ונשתחררה, וחזרה ונתקדשה לשמעון\u0004 (לאדם אחר, כלשהו), \u0003רב יוסף בר חמא אמר\u0004 בשם \u0003רב נחמן:\u0004 על ידי השיחרור \u0003פקעו קדושי\u0004 \u0005[קידושין]\u0006 של \u0003ראשון\u0004 לגמרי, וחלים קידושי השני. \u0003ר' זירא אמר\u0004 בשם \u0003רב נחמן: גמרו קדושי\u0004 \u0005[שלמו קידושין]\u0006 של \u0003ראשון,\u0004 שהקידושין שקידש אותה הראשון חלו עליה בשלימות כאשר נשתחררה, וקידושי השני אינם חלים.","\u0003אמר ר' זירא: כוותיה דידי מסתברא\u0004 \u0005[כשיטתי שלי מסתבר],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בבועל שפחה חרופה: \u0003\"לא יומתו כי לא חפשה\"\u0004 (ויקרא יט, כ), ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חופשה\u0004 (נשתחררה) — \u0003יומתו\u0004 משום שהיא אשת איש. משמע שאירוסיה שאורסה בעודה שפחה למחצה תקפים בעת שיחרורה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ול\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 ש\u0003אמר: בשפחה כנענית המאורסת לעבד עברי\u0004 מדובר, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003חופשה יומתו?!\u0004 הרי כשנשתחררה, מה שהיתה מיוחדת לעבד אין בו ממש מן הדין! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר],\u0006 ללמוד מדיוק הכתוב \"לא יומתו כי לא חופשה\"; מתי יומתו — במקרה \u0003שחופשה וחזרה ונתקדשה\u0004 לאדם כלשהו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשיטה שמדובר במי שהיא חציה שפחה וחציה בת חורין, יכול אתה לדייק: מתי יומתו — במקרה \u0003שחופשה וחזרה ונתקדשה\u0004 לאחר. ואם כן, אין להוכיח מכאן.","\u0003אמר רב הונא בר קטינא אמר ר' יצחק: מעשה\u0004 היה \u0003באשה אחת ש\u0004היתה \u0003חציה שפחה וחציה בת חורין, וכפו את רבה\u0004 (אדוניה) \u0003ועשאה בת חורין.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי היא]?\u0006 האם \u0003כ\u0004שיטת \u0003ר' יוחנן בן ברוקה,\u0004 ש\u0003אמר: על שניהם,\u0004 על האיש וגם על האשה \u0003הוא אומר: \"ויברך אתם אלהים ויאמר\u0004 להם אלהים \u0003פרו ורבו ומלאו\u0004 את הארץ","\u0003\"\u0004(בראשית א, כח), כלומר, שמצוות פריה ורביה חלה גם על נשים? \u0003אמר רב נחמן בר יצחק: לא,\u0004 מכאן אין להוכיח, והטעם ששיחררו אותה הוא לא משום מצוות פריה ורביה, אלא משום שבמצב כזה אינה יכולה להינשא ו\u0003מנהג הפקר נהגו בה,\u0004 ונעשתה מכשול לרבים, ולכן שיחררו אותה כדי שתוכל להינשא ולא תהיה הפקר.","\u0003המוכר עבדו לגוים או\u0004 אפילו \u0003ל\u0004ישראל שב\u0003חוצה לארץ\u0004 — \u0003יצא\u0004 העבד \u0003בן חורין\u0004 על ידי כך. שלפי שהוא מפקיעו על ידי כך מן המצוות, קנסוהו חכמים שיהא כמשוחרר, ואם יצא מאדוניו הגוי בכל דרך — הריהו כישראל לכל דבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר עבדו לגוים\u0004 — \u0003יצא לחירות, וצריך גט\u0004 (שטר) \u0003שחרור מרבו\u0004 (אדוניו) \u0003ראשון. אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 שצריך שטר שיחרור — \u0003שלא כתב עליו אונו\u0004 (שטר), \u0003אבל\u0004 אם \u0003כתב עליו אונו\u0004 — \u0003זהו שחרורו\u0004 ואינו צריך שטר נוסף.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003אונו?\u0004 \u0003אמר רב ששת: דכתב ליה הכי\u0004 \u0005[שכותב לו כך]:\u0006 \u0003לכשתברח ממנו,\u0004 מן הגוי, \u0003אין לי עסק בך,\u0004 ואף על פי שאין זה שטר שיחרור מפורש, מכל מקום די בכך לענין החשבתו כבן חורין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לוה עליו,\u0004 על סמך העבד, \u0003מן הגוי\u0004 על מנת להיפרע ממנו במקרה של אי־פרעון החוב, \u0003כיון שעשה לו\u0004 ה\u0003גוי נמוסו\u0004 (חוקו, מנהגו) בקנין — \u0003יצא\u0004 העבד \u0003לחירות\u0004 כדין הנמכר לגוי. ושואלים \u0003מאי\u0004 \u0005[מהו]\u0006 ענין \u0003נמוסו?\u0004 ומשיבים: \u0003אמר רב הונא בר יהודה:\u0004 ששם עליו \u0003נשקי\u0004 \u0005[חותם],\u0006 שכיון ששם עליו הגוי חותם הרי הוא נעשה כמכור לגוי, ומאז יצא לחופשי מישראל.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו: \u0003האריסין, והחכירות, ואריסי בתי אבות\u0004 (משפחה שלימה של אריסים שעבדו בשדה זה דור אחר דור), \u0003וגוי שמשכן שדהו לישראל, אף על פי שעשה לו נמוסו\u0004 — \u0003פטורה\u0004 השדה \u0003מן המעשר,\u0004 משום שהשדה עדיין שייך לגוי.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\"נמוסו\" כוונתו \u0003נשקי\u0004 \u0005[חותם],\u0006 וכי \u0003שדה בת נשקי היא? אלא אמר רב ששת:\u0004 הביטוי \"שעשה לו נימוסו\" כוונתו \u0003זמן,\u0004 כלומר, שנקבע זמן מסויים שאם לא ייפרע החוב עד אותה שעה יעבור העבד לבעלות הגוי.","ומקשים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003זמן\u0004 על ענין \u0003זמן,\u0004 שהרי לגבי העבד נראה שעם קביעת הזמן יוצא מרשות הלווה ומשתחרר, ואילו לגבי השדה אין הדבר כך, שהרי אינה מתחייבת מאותה שעה במעשר, כשדה של ישראל! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 ויש לחלק ולומר: \u0003הא\u0004 \u0005[זה],\u0006 בעבד שמשתחרר, מדובר במקרה \u0003דמטא זמניה\u0004 \u0005[שהגיע זמנו],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 בשדה מדובר במקרה שעדיין \u0003לא מטא זמניה\u0004 \u0005[הגיע זמנו].\u0006","ושואלים: \u0003אלא גבי עבד\u0004 \u0003דמטא זמניה צריכא למימר\u0004 \u0005[שהגיע זמנו צריך לומר]\u0006 שהוא משתחרר? הלא מובן שבכך עבר לחלוטין לרשות הגוי! \u0003אלא,\u0004 צריכים לומר כך: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר ש\u0003לא מטא זמניה\u0004 \u0005[הגיע זמנו ]\u0006 עדיין, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא לגופא\u0004 \u0005[זה,\u0006 מסר לו לגוי \u0005את גוף\u0006 העבד\u0005],\u0006 \u0003והא לפירא\u0004 \u0005[וזה, לפירות]\u0006 שהמלווה הישראל אוכל את פירות השדה בלבד, אבל אינו מחזיק בה."],["\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 אף אם הגיע זמנו של העבד יש חידוש בדבר — \u0003ב\u0004מקרה \u0003שלוה\u0004 מן הגוי \u0003על מנת למשכנו ולא משכנו\u0004 עדיין, שכיון שהגיע זמן הפרעון — הרי זה נחשב כאילו כבר מוסר את העבד לגויים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גבאו\u0004 הגוי את העבד \u0003בחובו או שלקחו סיקריקון\u0004 (שודד, אנס) — \u0003לא יצא לחירות.\u0004 ושואלים: \u0003ו\u0004אם לקחו \u0003בחובו,\u0004 האם \u0003לא\u0004 קונסים את האדון והעבד יוצא לחירות?","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003הרי שאנסו בית המלך גורנו\u0004 (נטלו ממנו את הגורן שלו באונס), \u0003אם בחובו\u0004 נטלו זאת, משום שהוא חייב להם כסף — \u0003חייב לעשר\u0004 גם על מה שלקחו, שאם לא כן נמצא שהוא משלם את חובו מן המעשר. \u0003אם באנפרות\u0004 (לחינם, בלי סיבה) — \u0003פטור מלעשר!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דקא משתרשי ליה\u0004 \u0005[שהוא מרוויח]\u0006 על ידי כך שהוא פורע מקצת חובו מן המעשר, ולכן הוא חייב במעשר. אולם לגבי עבד, הרי דין שיחרורו של עבד שמכרו רבו לגויים הוא רק משום קנס, וכשאין האדון עושה זאת מדעתו, ואף אינו מרוויח בדבר — אין קונסים אותו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר רב: המוכר עבדו לפרהנג\u0004 (מושל) \u0003גוי\u0004 — \u0003יצא לחירות.\u0004 והרי אף מכירה זו אינה מרצון גמור, אלא מפני לחץ המושל! ומשיבים: \u0003התם הוה ליה\u0004 \u0005[שם היה לו]\u0006 \u0003לפייס\u0004 את המושל בדבר אחר \u0003ו\u0004הוא \u0003לא פייס,\u0004 ולכן יש מקום לקונסו.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה ש\u0003אמר רב\u0004 ש\u0003המוכר עבדו לפרהנג גוי\u0004 — \u0003יצא לחירות,\u0004 שואלים: \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 הרי המושל הגוי מכריח אותו לכך! ומשיבים: \u0003הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לפייס\u0004 את הפרהנג הזה בכסף או באופן אחר שלא יקח את העבד, \u0003ו\u0004הוא \u0003לא פייס,\u0004 ולכן קנסו אותו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: מכרו\u0004 את העבד לגוי \u0003לשלשים יום, מהו\u0004 הדין? האם נקרא הדבר הזה כמכירה ומשתחרר משום כך, או שאינו כמכירה גמורה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ש\u0003אמר רב: המוכר עבדו לפרהנג גוי\u0004 — \u0003יצא לחירות,\u0004 ומן הסתם מכרו לו כדי שיעסוק במלאכת המושל לזמן מוגבל עד שתסתיים אותה מלאכה, והרי שאף במכירה לזמן הריהו יוצא לחירות! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בפרהנג גוי, ש\u0004מכירה זו \u0003אינה חוזרת,\u0004 ולכן הרי הוא משתחרר, אבל במכירה שחוזרת לא מדובר.","ושואלים עוד: אם \u0003מכרו\u0004 את העבד לגוי \u0003חוץ ממלאכתו, מהו\u0004 הדין? וכן אם מכרו לגוי \u0003חוץ מן המצות,\u0004 שהתנה שיהא העבד ממשיך לקיים מצוות, \u0003מהו\u0004 הדין? וכן אם מכר אותו \u0003חוץ משבתות וימים טובים, מהו?\u0004 או מכרו \u0003לגר תושב,\u0004 גוי שקיבל עליו שלא לעבוד עבודה זרה, או \u0003לישראל משומד\u0004 שהמיר את דתו, \u0003מהו?\u0004 מכרו \u0003לכותי, מהו?\u0004 ומציעים: \u0003פשוט מיהא חדא\u0004 \u0005[פתור לפחות\u0006 שאלה \u0005אחת]\u0006 מאלה, ששנינו: \u0003גר תושב הרי הוא כגוי.\u0004 ואילו \u0003כותי וישראל משומד\u0004 — \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שדינו \u0003כגוי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שדינו \u0003כישראל.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מר' אמי: עבד שהפיל עצמו לגייסות,\u0004 שברח מבית אדוניו והמציא עצמו שיקחו אותו כחייל בצבא, \u0003ואין רבו יכול להוציאו\u0004 משם \u0003לא בדיני ישראל ולא בדיני אומות העולם, מהו שיטול\u0004 האדון לפחות \u0003את דמיו\u0004 מן הצבא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זריקא: פוק\u0004 \u0005[צא]\u0006 \u0003עיין במכילתיך\u0004 \u0005[במשניות שלך]\u0006 ותמצא פתרון לכך. \u0003נפק דק ואשכח\u0004 \u0005[יצא דיקדק ומצא]\u0006 פתרון, מזו \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר ביתו\u0004 שבארץ ישראל \u0003לגוי\u0004 — \u0003דמיו\u0004 של הבית \u0003אסורין,\u0004 \u0003וגוי שאנס\u0004 (שנטל בכוח) \u0003ביתו של ישראל ואין בעליו יכול להוציאו\u0004 ממנו \u0003לא בדיני ישראל ולא בדיני אומות העולם\u0004 — \u0003מותר ליטול\u0004 מן הגוי \u0003את דמיו, ו\u0004אף \u0003כותב\u0004 שטר \u0003ומעלה\u0004 (רושם) ומאשר את השטר \u0003בערכאות שלהן,\u0004 של הגויים, \u0003מפני שהוא כמציל מידם.\u0004 משמע שכל דבר שאם נמכר לגוי דמיו אסורים, כאשר נלקח באונס ואינו יכול להוציא מידם — מותר ליטול את דמיו, ואם כן הוא הדין לכאורה אף בעבד שהפיל עצמו לגייסות!","ודוחים: \u0003ודילמא הני מילי\u0004 \u0005[ושמא דברים אלה]\u0006 אמורים דווקא ב\u0003בית,\u0004 ש\u0003כיון\u0004 ש\u0003לא סגי ליה\u0004 \u0005[די לו\u0006 לאדם\u0005]\u0006 \u0003בלא בית, לא אתי לזבוניה\u0004 \u0005[יבוא למוכרו]\u0006 מרצונו, ולכן אין מקום לקונסו במקום אונס, \u0003אבל עבדא\u0004 \u0005[עבד]\u0006 \u0003דסגי ליה\u0004 \u0005[שדי לו\u0006 לאדם\u0005]\u0006 \u0003בלא עבדא\u0004 \u0005[עבד]\u0006 יש לחשוש כי \u0003אתי לזבוניה\u0004 \u0005[יבוא למכור אותו]\u0006 אף מרצונו, ואם כן, האם יש לקונסו אף במקרה כזה, \u0003או לא,\u0004 שאין לחלק בין הדברים.","\u0003שלח להו\u0004 \u0005[להם]\u0006 \u0003ר' אמי, \"מיני\u0004 \u0005[ממני]\u0006 \u0003אמי בר נתן, תורה יוצאה לכל ישראל,\u0004 פסק הלכה זה: \u0003עבד שהפיל עצמו לגייסות, ואין רבו יכול להוציאו\u0004 משם \u0003לא בדיני ישראל ולא בדיני אומות העולם\u0004 — \u0003מותר ליטול את דמיו, וכותב ומעלה בערכאות של גוים, מפני שהוא כמציל מידם.\u0004","\u0003אמר ר' יהושע בן לוי: המוכר עבדו לגוי\u0004 אף שאינו יכול עוד להשתעבד בו עוד — \u0003קונסים אותו עד\u0004 פי \u0003מאה בדמיו\u0004 שיפדה אותו מן הגוי.","ושואלים: \u0003דוקא\u0004 \u0005[בדיוק]\u0006 נאמר הדבר שעד פי מאה, \u0003או לאו דוקא\u0004 \u0005[לא בדיוק],\u0006 ורוצה לומר רק שקונסים אותו הרבה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר ריש לקיש: המוכר בהמה גסה לגוי\u0004 — \u0003קונסים אותו עד\u0004 פי \u0003עשרה בדמיה,\u0004 שלמרות שעבר על דברי חכמים ומכרה — אין קונסים אותו יותר מפי עשרה. ונראה מכאן שמה שאמרו במוכר עבדו \"עד מאה\" אינו אלא גוזמה.","ודוחים: \u0003ודלמא שאני\u0004 \u0005[ושמא שונה]\u0006 \u0003עבד, דכל יומא ויומא מפקע ליה\u0004 \u0005[\u0006ש\u0005כל יום ויום\u0006 הוא \u0005מפקיע אותו]\u0006 \u0003ממצות\u0004 ולכן קנסו בו יותר, ואם כן, אין מכאן ראיה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שנאמרו הדברים בלשון אחרת, \u0003אמר ר' יהושע בן לוי: המוכר עבדו לגוי\u0004 — \u0003קונסין אותו עד\u0004 פי \u0003עשרה בדמיו.\u0004 ושואלים: האם \u0003דוקא\u0004 \u0005[בדיוק]\u0006 נאמר הדבר \u0003או לאו דוקא\u0004 \u0005[לא בדיוק]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לשאלה זו ממה ש\u0003אמר ריש לקיש: המוכר בהמה גסה לגוי\u0004 — \u0003קונסין אותו עד\u0004 פי \u0003מאה בדמיה.\u0004 משמע שאין הדבר מדוייק, אלא שאמרו מספרים גדולים בלבד.","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר ב\u0003עבד, דלא הדר ליה\u0004 \u0005[שאינו חוזר אליו],\u0006 שהרי אמרו שאם הוא מוכר אותו לגוי משתחרר העבד, ויש מקום לומר שלא צריך לקנוס אותו כל כך.","ומקשים: \u0003אלא בהמה טעמא מאי\u0004 \u0005[מה טעם]\u0006 קונסים בה יותר מאשר בעבד — \u0003משום דהדרא ליה\u0004 \u0005[שחוזרת לו]?\u0006 אם כן \u0003לקנסיה טפי חד\u0004 \u0005[\u0006יש \u0005לקנוס אותו\u0006 רק פעם \u0005אחת יותר]\u0006 מאשר בעבד, שאם ההבדל היחידי הוא שהבהמה חוזרת לבעליה והעבד לא — יש מקום לקנוס את בעליה יותר מאשר בעבד רק כשיעור שהרוויח בדבר — שווי הבהמה, ולא יותר! \u0003אלא\u0004 יש לומר כך: \u0003עבד מילתא דלא שכיחא\u0004 \u0005[דבר שאינו מצוי\u0006 הוא שימכור\u0005],\u0006 \u0003ומלתא דלא שכיחא\u0004 \u0005[ודבר שאינו מצוי]\u0006 \u0003לא גזרי בה רבנן\u0004 \u0005[גזרו בו חכמים]\u0006 עד כדי כך, ומשום כן אין להוכיח לגביו מדין המוכר בהמה לגוי, שהוא דבר מצוי ביותר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' אסי:\u0004 מי ש\u0003מכר עבדו\u0004 לגוי \u0003ומת, מהו שיקנסו את בנו אחריו?\u0004 האם קונסים גם את הבן שיפדנו, או שהקנס הוא רק על המוכר בלבד? \u0003אם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 לפי השיטה שמי ש\u0003צרם\u0004 (חתך) \u0003אוזן\u0004 של \u0003בכור\u0004 בהמה, שהטיל בו מום כדי להכשיר אותו לאכילה, \u0003ומת\u0004 — \u0003קנסו בנו אחריו,\u0004 שגם הבן לא יוכל לשוחטו, אפשר לומר \u0003משום דאיסורא דאורייתא היא\u0004 \u0005[שאיסור שמן התורה הוא],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 במכירת העבד רק \u0003איסורא דרבנן\u0004 \u0005[איסור שמדברי סופרים]\u0006 ושמא לא קנסו את הבן."],["\u0003ואם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר,\u0004 ותשאל באופן אחר: מי ש\u0003כוון מלאכתו\u0004 לעשותה \u0003במועד,\u0004 שהביא עצמו בכוונה לידי כך שתהא לו מלאכה של דבר האבד בחול המועד, וקנסו אותו חכמים שמה שעשה יאבד, \u0003ומת\u0004 — ש\u0003לא קנסו בנו אחריו,\u0004 אפשר לומר שלא קנסו את הבן \u0003משום\u0004 ש\u0003לא עבד איסורא\u0004 \u0005[עשה\u0006 הבן \u0005איסור],\u0006 \u0003הכא מאי\u0004 \u0005[כאן מה]\u0006 יהיה הדין? האם \u0003לדידיה\u0004 \u0005[אותו\u0006 עצמו\u0005]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים]\u0006 \u0003והא ליתיה\u0004 \u0005[והרי\u0006 הוא \u0005איננו],\u0006 \u0003או דילמא לממוניה\u0004 \u0005[שמא את ממונו]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים]\u0006 שיאבד \u0003והא איתיה\u0004 \u0005[והרי ישנו]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 שכן שנינו: \u0003שדה שנתקווצה\u0004 (שהוציאו ממנה את הקוצים) \u0003ב\u0004שנה ה\u0003ש\u0004\u0003ביעית,\u0004 שאף שאסור לעשות כן בשנת השמיטה, כיון שאין זו עבודת אדמה ממש — \u0003תזרע למוצאי שביעית,\u0004 אבל אם \u0003נטייבה\u0004 (טייב אותה בזבל) \u0003או נדיירה\u0004 (עשה בה דיר של בהמות שהשאירו שמה זיבלן) שעשה מעשה לעבד את האדמה ולהכשירה לשנה הבאה — \u0003לא תזרע למוצאי שביעית.\u0004","\u0003ואמר ר' יוסי בר' חנינא, נקטינן\u0004 \u0005[מוחזקים אנו]:\u0006 אם \u0003הטיבה ומת\u0004 — \u0003בנו זורעה\u0004 למוצאי שביעית. \u0003אלמא\u0004 \u0005[מכאן נלמד]:\u0006 \u0003לדידיה\u0004 \u0005[אותו]\u0006 \u0003קנסו רבנן\u0004 \u0005[חכמים],\u0006 ואולם \u0003לבריה\u0004 \u0005[את בנו]\u0006 \u0003לא קנסו רבנן\u0004 \u0005[חכמים].\u0006","ובאותו ענין \u0003אמר אביי, נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 בהלכה זו: מי ש\u0003טימא טהרות של חבירו ומת\u0004 — \u0003לא קנסו רבנן\u0004 \u0005[חכמים]\u0006 את \u0003בנו אחריו\u0004 שישלם את דמי הטהרות. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003היזק שאינו ניכר,\u0004 כלומר, נזק שגרם אדם לחבירו על ידי פעולה שתוצאותיה אינן נראות באופן מוחשי, \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003היזק\u0004 להתחייב מן התורה בתשלומין על מעשהו ככל מזיק. וכיון שהמטמא טהרות אינו עושה היזק ניכר לעין, למרות שבמעשהו הוא פוסל את כל הטהרות, אין הוא חייב מן הדין, אלא \u0003קנסא דרבנן היא\u0004 \u0005[קנס שמדברי חכמים הוא],\u0006 \u0003לדידיה\u0004 \u0005[אותו\u0006 עצמו\u0005]\u0006 \u0003קנסוהו רבנן\u0004 \u0005[חכמים],\u0006 ואולם \u0003לבריה לא קא קנסו רבנן\u0004 \u0005[את בנו לא קנסו חכמים].\u0006","שנינו במשנה שהמוכר עבדו לגוי \u0003או לחוצה לארץ\u0004 אף ליהודי — העבד יוצא בכך לחירות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוכר עבדו לחוצה לארץ\u0004 — \u0003יצא לחירות, ו\u0004אולם \u0003צריך גט\u0004 (שטר) \u0003שחרור מרבו\u0004 (אדוניו) ה\u0003שני\u0004 שקנה אותו בחוצה לארץ. \u0003רבן שמעון בן גמליאל אומר: פעמים יצא\u0004 לחירות \u0003ופעמים לא יצא. כיצד?\u0004 — אם \u0003אמר\u0004 האדון: \u0003\"פלוני עבדי מכרתיהו לפלוני אנטוכי\u0004 (בן אנטיוכיה) \u0003\"\u0004— \u0003לא יצא\u0004 לחירות, משום שאפשר לפרש שקראו אנטוכי על שם מקום לידתו, אבל עכשיו הוא גר בארץ ישראל. אבל אם אמר שמכרו \u0003\"לאנטוכי שבאנטוכיא\"\u0004 — \u0003יצא\u0004 לחירות, שכן משמע מדבריו שמכר עבדו לחוצה לארץ.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אם אמר \u0003\"מכרתיהו לאנטוכי\"\u0004 — \u0003יצא\u0004 העבד לחירות, \u0003\"לאנטוכי השרוי בלוד\"\u0004 — \u0003לא יצא.\u0004 ומפורש שאם אומר שמכרו לאנטוכי סתם — יצא לחירות, ואין זה כדברי רבן שמעון בן גמליאל!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שלא יצא לחירות — הרי זה מדובר באופן \u0003דאית ליה ביתא\u0004 \u0005[שיש לו,\u0006 לאותו אנטוכי \u0005בית]\u0006 \u0003בארץ ישראל,\u0004 שאפשר לפרש שלצורך ביתו בארץ קנה את העבד. \u0003הא\u0004 \u0005[זה]\u0006 שיצא העבד לחירות — \u0003דאית ליה אושפיזא\u0004 \u0005[שיש לו\u0006 רק \u0005מלון,\u0006 מקום בו הוא מתארח\u0005]\u0006 \u0003בארץ ישראל\u0004 לפי שעיקר מקומו של הקונה הוא בחוץ לארץ.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: בן בבל שנשא אשה בארץ ישראל והכניסה לו\u0004 בנישואיה \u0003עבדים ושפחות, ודעתו לחזור\u0004 לבבל, \u0003מהו\u0004 הדין? האם לומר שעל ידי הנישואין כאילו מכרה את העבדים לבעלה, והוא עומד להוציאם לחוצה לארץ, ויהא דינם כמוכר עבדו לחוצה לארץ שיצא לחירות?","\u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003הדין עמה,\u0004 שבמקרה של גירושין העבדים שלה נשארים ברשותה, ואין הבעל יכול לשלם לה את מחירם ולהחזיק בהם. \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003הדין עמו\u0004 והעבדים נשארים במקרה כזה ברשותו.","ומסבירים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003הדין עמה, כיון\u0004 ש\u0003הדין עמה\u0004 לגבי גוף העבדים — \u0003כדידה דמו\u0004 \u0005[כשלה\u0006 הם \u0005נחשבים],\u0006 ולכן אין הנישואין נחשבים כמכירתם לחוץ לארץ, שהרי היא בת ארץ ישראל. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דמשעבדי ליה לפירא\u0004 \u0005[ש\u0006הם \u0005משועבדים לו לפירות],\u0006 שהרי שכר עבודתם שייך לבעל, כפירות שאר נכסים שמכניסה לו האשה — \u0003כדידיה דמו\u0004 \u0005[כשלו\u0006 הם \u0005נחשבים]\u0006 והרי זה כאילו קנה את עבדיה להוציאם לבבל?","\u0003ו\u0004כמו כן \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003הדין עמו,\u0004 האם לומר \u0003כיון\u0004 ש\u0003הדין עמו\u0004 — \u0003כדידיה דמו\u0004 \u0005[כמו שלו\u0006 הם \u0005נחשבים]\u0006 ויהיה דינם כעבד שנמכר לחוצה לארץ, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא קני ליה לגופיה\u0004 \u0005[שאינו קונה אותם לגופם]\u0006 אלא רק לשימוש בהם — \u0003כדידה דמו\u0004 \u0005[כשלה\u0006 הם \u0005נחשבים]?\u0006 שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ר' אבהו, שנה לי ר' יוחנן: עבד שיצא\u0004 מרצונו \u0003אחר רבו\u0004 (אדונו) \u0003לסוריא,\u0004 שדינה כחוצה לארץ לענין המוכר עבדו לחוצה לארץ, \u0003ומכרו שם רבו\u0004 — \u0003יצא\u0004 העבד \u0003לחירות.\u0004 ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא:\u0004 \u0003איבד\u0004 העבד \u0003את זכותו\u0004 לצאת לחירות במכירה לחוצה לארץ אם יצא תחילה מרצונו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאמרנו שיצא לחירות אם מכרו רבו, מדובר באופן \u0003שדעת רבו\u0004 מתחילה כאשר יצאו לסוריא, היתה \u0003לחזור\u0004 ועל דעת כן יצא עימו העבד, ומאחר שמכרו בסוריא הרי זה כמוכר מארץ ישראל לחוץ לארץ. \u0003כאן\u0004 שאמרנו שלא יצא לחירות הרי זה באופן \u0003שאין דעת רבו לחזור\u0004 ועל דעת כן יצא עימו העבד, ולכן, אף שמכרו שם, מאחר שעל דעת כן יצא, איבד את זכותו ואינו יוצא לחירות.","ומביאים, \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוצא העבד אחר רבו לסוריא.\u0004 ויש לתהות: \u0003יוצא\u0004 לכתחילה?! \u0003לא סגי דלא נפיק\u0004 \u0005[די שאינו יוצא],\u0006 וכי חייב הוא לצאת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 הכל מעלים לארץ ישראל, שיכולים אשה ועבד לומר שרצונם לעלות, ואין לכפותם להישאר בחוץ לארץ, \u0003ואין הכל מוציאין,\u0004 שאינו יכול לכפות את העבד לצאת אחריו!","\u0003אלא,\u0004 יש לתקן ולשנות בלשון עבר, שמשמעה בדיעבד: אם \u0003יצא העבד אחר רבו לסוריא ומכרו רבו שם, אם דעת רבו לחזור,\u0004 שמתחילה לא יצא אלא לזמן קצר, אלא שמכר את העבד בסוריא — \u0003כופין אותו\u0004 לשחררו, שהרי העבד לא יצא אלא על מנת לחזור, \u0003ואם אין דעת רבו לחזור\u0004 והעבד יצא עימו מרצונו — \u0003אין כופין אותו\u0004 אלא איבד את זכותו.","\u0003אמר רב ענן, שמעית מיניה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003מר שמואל תרתי\u0004 \u0005[שתי\u0006 הלכות\u0005]:\u0006 \u0003חדא, הך\u0004 \u0005[אחת, זו]\u0006 בענין עבד, שנמכר לחוצה לארץ ויוצא לחירות. \u0003ואידך\u0004 \u0005[והאחרת]\u0006 — \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה: \u0003המוכר שדהו בשנת היובל עצמה,\u0004 שבה השדות חוזרים לבעליהם, מה דינו? \u0003רב אמר: מכורה,\u0004 שהמכר חל עקרונית, \u0003ויוצאה\u0004 מיד ביובל, והקונה איבד את כספו. \u0003ושמואל אמר: אינה מכורה כל עיקר,\u0004 שהמכר בטל ולא חל מעיקרו.","ושמעתי בשתי ההלכות הללו שאמר שמואל אודות כספי המכירה: \u0003בחדא הדרי זביני\u0004 \u0005[באחת חוזר המקח]\u0006 ונחשב כאילו לא היתה זו מכירה כלל, ולא איבד הקונה את כספו, \u0003ובחדא לא הדרי זביני\u0004 \u0005[ובאחת אין המקח חוזר]\u0006 אלא הוא קיים והקונה איבד את כספו, \u0003ולא ידענא הי מינייהו\u0004 \u0005[ואיני יודע באיזו\u0006 \u0005מהן]\u0006 הכסף חוזר ובאיזו מהן אין הכסף חוזר.","\u0003אמר רב יוסף: ניחזי אנן\u0004 \u0005[נראה אנו]\u0006 ונבין מדעתנו, \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 בברייתא: \u0003המוכר עבדו לחוצה לארץ\u0004 — \u0003יצא לחירות, וצריך גט שחרור מרבו שני. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003קנייה\u0004 \u0005[קנה אותו]\u0006 \u0003רבו שני, ולא הדרי זביני\u0004 \u0005[ואין המקח חוזר]\u0006 ואינו בטל לגמרי, שהרי רבו השני הוא זה שצריך לשחררו, משמע שהעבד קנוי לו. \u0003ו\u0004אם כן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל התם\u0004 \u0005[שם]\u0006 שהשדה \u0003אינה מכורה,\u0004 כוונתו שהמכר לא חל מעיקרו כל עיקר \u0003ומעות חוזרין\u0004 לקונה."],["ואומרים: \u0003ורב ענן\u0004 שלא ידע להחליט באיזו מהן אמר שמואל שמעות חוזרות ובאיזו לא — את ה\u0003ברייתא\u0004 שהביא רב יוסף לראיה שמעות אינן חוזרות במכירת עבד לחוצה לארץ \u0003לא שמיע ליה\u0004 \u0005[שמע אותה],\u0006 ומכיון שלא ידע את הברייתא, לא יכול היה לפתור ממנה את הבעיה.","\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שיכול רב ענן לפתור את בעייתו זו \u0003מ\u0004דברי \u0003שמואל\u0004 עצמו, שהרי אמר שהשדה אינה מכורה כלל, וכדרך מכר שנתבטל המעות חוזרות לבעליהן. הרי אפשר לומר: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק ש\u0003אינה מכורה ו\u0004משום כך \u0003מעות חוזרין? דילמא\u0004 \u0005[שמא]\u0006 \u0003אינה מכורה ו\u0004אולם \u0003מעות מתנה נינהו\u0004 \u0005[הם],\u0006 כלומר, בכל זאת הכסף אינו חוזר והוא נחשב כמתנה. \u0003מידי דהוה\u0004 \u0005[כפי שהוא]\u0006 דעתו של שמואל בענין ה\u0003מקדש את אחותו, דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בענין \u0003המקדש את אחותו, רב אמר: מעות\u0004 שנתן לקידושין — \u0003חוזרין,\u0004 שהרי אין הקידושין חלים, \u0003ושמואל אמר:\u0004 \u0003מעות\u0004 אלה \u0003מתנה\u0004 הן, שרצה לתת לה מתנה ועשה זאת באופן כזה.","על הלכה זאת שהמוכר עבד להוציאו לחוץ לארץ מפסיד הקונה את דמיו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי חזית\u0004 \u0005[מה ראית]\u0006 לומר \u0003דקנסינן\u0004 \u0005[שקונסים אנו]\u0006 את ה\u0003לוקח\u0004 (הקונה), שצריך לשחרר את העבד ובכל זאת הכסף אינו חוזר אליו? \u0003נקנסיה\u0004 \u0005[נקנוס אותו],\u0006 את ה\u0003מוכר\u0004 שיחזיר את הכסף! \u0003אמר,\u0004 השיב, \u0003ליה\u0004 \u0005[לו]\u0006 במשל: \u0003לאו עכברא גנב\u0004 \u0005[לא העכבר גונב]\u0006 \u0003אלא חורא גנב\u0004 \u0005[החור גונב],\u0006 כלומר, הגניבה נמצאת אצל הקונה ולא אצל המוכר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 על דרך אותו משל: \u0003אי לאו עכברא, חורא מנא ליה\u0004 \u0005[אם לא העכבר, חור מניין לו]?\u0006 הרי החור אינו גונב בעצמו, משמע שעיקר הדבר תלוי במוכר ולא בלוקח!","השיב לו רב יוסף: \u0003מסתברא, היכא דאיכא איסורא התם קנסינן\u0004 \u0005[מסתבר\u0006 הדבר ש\u0005במקום שנמצא האיסור שם אנו קונסים],\u0006 וכיון שכעת העבד נמצא ברשות רבו השני, הרי הוא צריך לשחרר אותו.","מסופר: \u0003ההוא עבדא דערק\u0004 \u0005[עבד אחד שברח]\u0006 מאדוניו \u0003מחוצה לארץ לארץ, אזל מריה אבתריה\u0004 \u0005[הלך אדוניו אחריו]\u0006 לארץ ישראל, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי. אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003נכתוב\u0004 \u0005[יכתוב]\u0006 \u0003לך\u0004 עבדך \u0003שטרא אדמיה\u0004 \u0005[שטר על דמיו,\u0006 מחירו\u0005]\u0006 \u0003וכתוב ליה\u0004 \u0005[לו]\u0006 אתה \u0003גיטא דחירותא\u0004 \u0005[שטר שחרור],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשה כן, \u0003מפקנא ליה מינך\u0004 \u0005[אוציא אותו ממך\u0006 לחירות לגמרי\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003ר' אחי בר' יאשיה.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר על יושבי ארץ כנען: \u0003\"לא ישבו בארצך פן יחטיאו אתך לי\"\u0004 (שמות כג, לג), \u0003יכול\u0004 שגם \u0003בגוי שקיבל עליו שלא לעבוד עבודה זרה הכתוב מדבר\u0004 שאף לו אין ישיבה בארץ — \u0003תלמוד לומר: \"לא תסגיר עבד אל אדניו אשר ינצל אליך מעם אדניו\"\u0004 (דברים כג, טז) והפסוק עוסק באותו גוי הניצל מעבודה זרה שעבד אותה. \u0003מאי\u0004 \u0005[מה]\u0006 \u0003תקנתו?\u0004 — \u0003\"עמך ישב בקרבך\"\u0004 (דברים כג, יז). משמע שכל זמן שקיבל עליו שלא לעבוד עבודה זרה — אין מגרשים אותו מן הארץ.","\u0003וקשיא ליה\u0004 \u0005[והיה קשה לו]\u0006 \u0003לר' יאשיה\u0004 על פירוש זה של הפסוק: \u0003האי\u0004 \u0005[זו]\u0006 הלשון \u0003\"מעם אדניו\"\u0004 אינה מדוייקת לענין שלנו, שמדובר בגוי שפרש מעבודה זרה, שכן \u0003\"מעם אביו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שהוא עוזב את מורשת אבותיו, שהרי לשיטה זו לא מדובר בעבד שברח מאדוניו! \u0003אלא אמר ר' יאשיה: במוכר עבדו לחוצה לארץ הכתוב מדבר\u0004 וכדין משנתנו — \"עמך ישב\", שאינו יוצא לחוצה לארץ, אלא משתחרר ונשאר בארץ ישראל.","\u0003וקשיא ליה\u0004 \u0005[והיה קשה לו]\u0006 \u0003לר' אחי בר' יאשיה\u0004 על פירוש זה: אם מדובר בעבד שברח מארץ ישראל לחוץ לארץ, אם כן \u0003האי\u0004 \u0005[זו]\u0006 הלשון \u0003\"אשר ינצל אליך\"\u0004 אינה מדוייקת, ו\u0003\"אשר ינצל מעמך\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא אמר ר' אחי בר' יאשיה: בעבד שברח מחוצה לארץ לארץ הכתוב מדבר,\u0004 ש\"עמך ישב\" ואין מסגירים אותו. ובכך איים ר' אמי על אותו אדון.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 על הפסוק \u0003\"לא תסגיר עבד אל אדוניו\"\u0004 — \u0003רבי אומר: בלוקח\u0004 (קונה) \u0003עבד על מנת לשחררו הכתוב מדבר.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אמר רב נחמן בר יצחק: דכתב ליה הכי\u0004 \u0005[שכותב לו\u0006 בשטר \u0005כך]:\u0006 \u0003\"לכשאקחך\u0004 (לכשאקנה אותך), \u0003הרי עצמך קנוי לך מעכשיו\".\u0004","מסופר: \u0003רב חסדא ערק ליה עבדא\u0004 \u0005[ברח לו עבד]\u0006 \u0003לבי כותאי,\u0004 מקום שם שכנו כותים, \u0003שלח להו\u0004 \u0005[להם,\u0006 לבני המקום\u0005]:\u0006 \u0003הדרוה ניהלי\u0004 \u0005[החזירו אותו לי],\u0006 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 בתשובה: הרי נאמר \u0003\"לא תסגיר עבד אל אדניו\",\u0004 ולכן אין אנו מסגירים את העבד. \u0003שלח להו\u0004 \u0005[להם]:\u0006 הלא נאמר \"...והשבותו לו \u0003וכן תעשה לחמרו וכן תעשה לשמלתו וכן תעשה לכל אבדת אחיך\"\u0004 (דברים כב, ב-ג). \u0003שלחו ליה\u0004 \u0005[לו]\u0006 שוב: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תסגיר עבד אל אדניו\", שלח להו\u0004 \u0005[להם]\u0006 בחזרה: \u0003ההוא,\u0004 עבד זה ברח מחוצה לארץ למקום אחר בחוצה לארץ, ואילו אותו פסוק מדבר \u0003בעבד שברח מחוצה לארץ לארץ, וכ\u0004פירושו של \u0003ר' אחי בר' יאשיה.\u0004","ושואלים: \u0003ומאי שנא דשלח להו\u0004 \u0005[ומה שונה, ששלח להם]\u0006 דווקא \u0003כ\u0004דברי \u0003ר' אחי בר' יאשיה\u0004 בפירוש פסוק זה ולא כפירושו האחר של הפסוק? ומשיבים: \u0003משום דמשמע להו קראי\u0004 \u0005[שנשמע להם\u0006 הדבר יפה מן \u0005הכתובים\u0006 עצמם\u0005]\u0006 ולכן לקח פירוש שנובע כאילו מן הכתוב, שהרי הכותים אינם מודים בדברי חכמים.","מסופר: \u0003אביי אירכס ליה חמרא בי כותאי\u0004 \u0005[אבד לו חמור בין הכותים],\u0006 \u0003שלח להו\u0004 \u0005[להם]:\u0006 \u0003שדרוה\u0004 \u0005[שלחו אותו]\u0006 \u0003לי. שלחו ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003שלח סימנא\u0004 \u0005[סימן]\u0006 וניתן לך אותו. \u0003שלח להו\u0004 \u0005[להם]\u0006 סימן: \u0003דחיוורא כריסיה\u0004 \u0005[שכריסו לבנה].\u0006 \u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003נחמני את\u0004 \u0005[אתה]\u0006 שאנו יודעים שאדם צדיק וישר אתה, \u0003לא הוה משדרנא ליה ניהלך\u0004 \u0005[היינו שולחים אותו אליך],\u0006 \u0003אטו כולי חמרי לאו כריסייהו חיוורין נינהו\u0004 \u0005[וכי כל החמורים אין כריסם לבנה]?\u0006 אלא לך אנו מאמינים שאכן החמור הוא שלך.","\u0003אין פודין את השבויין יתר על כדי דמיהן\u0004 הרגילים, \u0003מפני תיקון העולם. ואין מבריחין את השבויין\u0004 מן השבאים, \u0003מפני תיקון העולם. רבן שמעון בן גמליאל אומר: מפני תקנת השבויין.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"מפני תיקון העולם\",\u0004 האם כוונתו \u0003משום דוחקא דצבורא\u0004 \u0005[דוחק הציבור]\u0006 \u0003הוא,\u0004 שאם עולים המחירים ביותר הרי זה גורם דוחק לציבור שצריכים לפדות אותם, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003משום\u0004 ש\u0003לא לגרבו ולייתו טפי\u0004 \u0005[יחטפו ויביאו\u0006 שבויים \u0005יותר],\u0006 כדי שלא יהיה כדאי לשובים לשבות דווקא שבויים יהודים?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לשאלה זו ממה ש\u0003לוי בר דרגא פרקא לברתיה\u0004 \u0005[פדה את בתו]\u0006 שנשבתה \u0003בתליסר\u0004 \u0005[בשלושה עשר]\u0006 \u0003אלפי דינרי זהב,\u0004 משמע שפודים את השבויים יותר מדמיהם אם אדם פרטי רוצה בכך. ומכאן עולה שסיבת התקנה היא דוחק הציבור ואינה ענין לאדם פרטי. שאם מן הסיבה השניה — גם לאדם פרטי יהיה אסור לפדות ביותר מדמי השבוי.","\u0003אמר אביי: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 ש\u0003ברצון חכמים עבד\u0004 \u0005[עשה]\u0006 דבר זה? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003שלא ברצון חכמים עבד\u0004 \u0005[עשה],\u0006 ואם כן, אין מכאן הוכחה.","שנינו במשנה: \u0003ואין מבריחין את השבויין מפני תיקון העולם. רבן שמעון בן גמליאל אומר: מפני תקנת שבויין.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003אלא חד\u0004 \u0005[\u0006שבוי \u0005אחד],\u0006 שאם הטעם מפני תקנת שבויים אין אנו חוששים שהרי אין שבוי אחר שינקמו בו, אבל מפני תיקון העולם שלא יתאכזרו להבא לשבויים אין מבריחים אותו.","מסופר: \u0003בנתיה\u0004 \u0005[בנותיו]\u0006 של \u0003רב נחמן בחשן קדרא בידייהו\u0004 \u0005[היו בוחשות קדירה\u0006 רותחת \u0005בידיהן]\u0006 ואנשים חשבו שהן צדקניות כל כך שאין האש שולטת בהן. \u0003קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 \u0003לרב עיליש, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אדם אחד מאלף מצאתי ואשה בכל אלה לא מצאתי\"\u0004 (קהלת ז, כח), \u0003הא איכא בנתיה\u0004 \u0005[הרי ישנן בנותיו]\u0006 של \u0003רב נחמן\u0004 שהן צדקניות מופלאות כאלה! \u0003גרמא להו מילתא ואשתביין\u0004 \u0005[גרם להן הדבר ונישבו],\u0006 \u0003ואישתבאי איהו נמי בהדייהו\u0004 \u0005[ונישבה גם הוא,\u0006 רב עיליש, \u0005יחד איתן].\u0006","\u0003יומא חד הוה יתיב גביה ההוא גברא דהוה ידע בלישנא דציפורי\u0004 \u0005[יום אחד ישב איתו\u0006 בשבי \u0005אדם אחד שהיה יודע בלשון הציפורים].\u0006 \u0003אתא עורבא וקא קרי ליה\u0004 \u0005[בא עורב וקרא,\u0006 השמיע קול, \u0005לו],\u0006 לרב עיליש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב עיליש לאותו אדם: \u0003מאי קאמר\u0004 \u0005[מה אומר\u0006 העורב\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 אומר הוא: \u0003\"עיליש ברח, עיליש ברח\", אמר\u0004 רב עיליש: \u0003עורבא שיקרא\u0004 \u0005[העורב שקרן]\u0006 \u0003הוא ולא סמיכנא עליה\u0004 \u0005[ואין אני סומך עליו].\u0006","\u0003אדהכי אתא\u0004 \u0005[בינתיים באה]\u0006 \u0003יונה וקא קריא\u0004 \u0005[וקראה,\u0006 השמיעה קול\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב עיליש לאותו אדם: \u0003מאי קאמרה\u0004 \u0005[מה אומרת\u0006 היא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אומרת היא: \u0003\"עיליש ברח, עיליש ברח\". אמר: כנסת ישראל כיונה מתילא\u0004 \u0005[משולה],\u0006 \u0003שמע מינה מתרחיש\u0004 \u0005[למד מכאן\u0006 ש\u0005מתרחש]\u0006 \u0003לי ניסא\u0004 \u0005[נס]\u0006 ואני יכול לסמוך על כך ולברוח. \u0003אמר:\u0004 לפני שאני הולך \u0003איזיל אחזי בנתיה\u0004 \u0005[אלך\u0006 ו\u0005אראה\u0006 את \u0005בנותיו]\u0006 של \u0003רב נחמן, אי קיימן בהימנותייהו\u0004 — \u0003אהדרינהו\u0004 \u0005[אם עומדות\u0006 הן \u0005בנאמנותן\u0006 ונוהגות כהוגן — \u0005אחזירן],\u0006 אבריחן יחד איתי.","\u0003אמר: נשי, כל מילי דאית להו\u0004 \u0005[נשים, כל דברים\u0006 של סוד \u0005שיש להן]\u0006 \u0003סדרן להדדי\u0004 \u0005[מספרות הן זו לזו]\u0006 \u0003בבית הכסא,\u0004 והלך והקשיב. \u0003שמעינהו דקאמרן\u0004 \u0005[שמע אותן ש\u0006הן \u0005אומרות]:\u0006 \u0003עדי גוברין ונהרדעי גוברין\u0004 \u0005[אלה,\u0006 השובים, הם \u0005גברים שלנו, ואנשי נהרדעא\u0006 שהתחתנו איתם הם \u0005גברים שלנו],\u0006 \u0003לימא להו לשבוייהו דלירחקינהו מהכא\u0004 \u0005[נאמר להם לשובים שלנו שירחיקו אותנו מכאן],\u0006 ש\u0003לא ליתו אינשין ולישמעי וליפרקינן\u0004 \u0005[יבואו הבעלים שלנו וישמעו ויפדו אותנו]\u0006 ויחזירו אותנו הביתה.","שמע זאת רב עיליש, \u0003קם, ערק\u0004 \u0005[ברח],\u0006 \u0003אתא איהו וההוא גברא\u0004 \u0005[הלך הוא ואותו אדם]\u0006 שידע בלשון הציפורים. \u0003לדידיה איתרחיש ליה ניסא\u0004 \u0005[לו עצמו התרחש לו נס]\u0006 \u0003עבר במברא\u0004 \u0005[במעבורת]\u0006 וברח, \u0003וההוא גברא אשכחוה וקטלוה\u0004 \u0005[ואותו אדם מצאו אותו והרגו אותו].\u0006 \u0003כי הדרן ואתן\u0004 \u0005[כאשר חזרו\u0006 בנות רב נחמן \u0005ובאו]\u0006 בסוף מבית השבי. \u0003אמר\u0004 רב עיליש: \u0003הוו קא בחשן קידרא\u0004 \u0005[היו בוחשות\u0006 את \u0005הקדירה]\u0006 \u0003בכשפים\u0004 ולא מחמת צידקות עשו כן.","\u0003ואין לוקחין\u0004 (קונים) \u0003ספרים\u0004 (ספרי תורה), \u0003תפילין ומזוזות מן הגוים\u0004 שאיכשהו הגיעו הדברים לידם, באופן שנדרשים לשלם עבורם \u0003יותר על כדי דמיהן,\u0004"],["\u0003מפני תיקון העולם,\u0004 שלא לגרום לכך שירבו לבזוז חפצי קודש מישראל על מנת לקבל סכומים גדולים עבורם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב בודיא לרב אשי:\u0004 מלשון המשנה נדייק: \u0003יתר על כדי דמיהן הוא\u0004 ש\u0003אין לוקחין, הא\u0004 \u0005[הרי]\u0006 משמע כי \u0003בכדי דמיהן לוקחין\u0004 אותם? \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 ש\u0003ספר תורה שנמצא ביד גוי\u0004 — \u0003קורין בו,\u0004 ואין חוששים שמא כתב אותו גוי והוא פסול? אמר לו: \u0003דילמא\u0004 \u0005[שמא]\u0006 לא נאמר הדבר שלוקחים כדי שיוכלו לקרוא בו, אלא כדי \u0003לגנוז\u0004 אותו, שלא יהיה מצוי בביזיון בידי גויים.","\u0003אמר רב נחמן, נקטינן\u0004 \u0005[מוחזק לנו]:\u0006 \u0003ספר תורה שכתבו מין\u0004 שהוא כופר בכל — \u0003ישרף, כתבו גוי\u0004 — \u0003יגנז.\u0004 ספר תורה ש\u0003נמצא ביד מין\u0004 ולא ברור מי כתבו — \u0003יגנז. נמצא ביד גוי, אמרי לה\u0004 \u0005[יש אומרים]\u0006 ש\u0003יגנז, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003קורין בו.\u0004","ומתקשים: \u0003ספר תורה שכתבו גוי, תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003ישרף, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003יגנז, ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]:\u0006 \u0003קורין בו,\u0004 ונמצאת סתירה בין שלוש הברייתות!","ומסבירים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003\"ישרף\"\u0004 — שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: סתם מחשבת גוי לעבודה זרה,\u0004 ולכן חוששים שכל מה שכתב — לשם עבודה זרה כתב.","\u0003והא דתניא\u0004 \u0005[וזו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003\"יגנז\"\u0004 — כשיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא, דתני\u0004 \u0005[ששנה]\u0006 \u0003רב המנונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מפשרוניא\u0004 ברייתא זו: \u0003ספר תורה, תפלין ומזוזות שכתבן מין\u0004 או \u0003מסור\u0004 (מלשין), או \u0003גוי\u0004 או \u0003עבד,\u0004 או \u0003אשה\u0004 או \u0003קטן,\u0004 או \u0003כותי,\u0004 או \u0003ישראל מומר\u0004 — \u0003פסולין, שנאמר: \"וקשרתם\u0004 לאות על ידך... \u0003וכתבתם\u0004 על מזוזות ביתך \u0005\"\u0006(דברים ו, ח-ט), ומן ההיקש אנו למדים: \u0003כל שישנו ב\u0004מצות \u0003קשירה\u0004 של תפילין, שחייב בה ומקיים אותה — \u0003ישנו\u0004 גם \u0003בכתיבה\u0004 של מזוזות ותפילין וספרי תורה, \u0003וכל שאינו ב\u0004מצות \u0003קשירה\u0004 — \u0003אינו בכתיבה.\u0004 ומתוך שכולל את אלו שנכתבו בידי גויים עם השאר שהם פסולים משום שכתיבתם לא נעשתה בכשרות, ואינו מציין שדינם בשריפה — משמע שדינם שווה, להיגנז ככל ספר פסול.","\u0003והא דתניא\u0004 \u0005[ו\u0006ברייתא \u0005זו ששנויה]\u0006 \u0003\"קורין בו\"\u0004 — שיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לוקחין\u0004 (קונים) \u0003ספרים\u0004 (ספרי תורה) \u0003מן הגוים בכל מקום ובלבד שיהיו\u0004 הספרים \u0003כתובין כהלכתן. ומעשה בגוי אחד בצידן שהיה כותב ספרים, והתיר רבן שמעון בן גמליאל ליקח ממנו.\u0004","ותוהים: \u0003ורבן שמעון בן גמליאל, עיבוד,\u0004 עורות הספרים \u0003לשמן בעי\u0004 \u0005[צריך],\u0006 ואילו \u0003כתיבה לשמה לא בעי\u0004 \u0005[אינו צריך]?\u0006","והיכן למדנו שרבן שמעון בן גמליאל מצריך עיבוד לשמה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 תפילין ש\u0003ציפן זהב או שטלה עליהן\u0004 (הניח עליהן טלאי) של \u0003עור בהמה טמאה\u0004 — \u0003פסולות,\u0004 אבל אם הניח עליהם \u0003עור בהמה טהורה\u0004 — \u0003כשרות, ואף על פי שלא עיבדן לשמן.\u0004 \u0003רבן שמעון בן גמליאל אומר: אפילו עור בהמה טהורה\u0004 — \u0003פסולות, עד שיעבדן לשמן.\u0004 משמע שהוא מחייב עיבוד לשמה, וכל שכן שצריך לדעה זו כתיבה לשמה, ואיך סמך על כתיבתו של הגוי!","\u0003אמר רבה בר שמואל:\u0004 אותו מעשה היה \u0003בגר שחזר לסורו\u0004 (לקילקולו) שנהג שוב כמנהג גויים, ומצד הדין כיון שנתגייר הריהו כישראל לעולם, אף על פי שחוזר ונוהג כגוי. ותוהים: אם חזר \u0003לסורו, כל שכן\u0004 שהוא פסול, \u0003דהוי ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003מין!\u0004 שכיון שידע מאמונת ישראל וחזר בו — הריהו כופר, ולא כגוי סתם! \u0003אמר רב אשי:\u0004 הכוונה היא \u0003שחוזר לסורו משום יראה,\u0004 לא מפני שחזר בו מדת ישראל, אלא מפני יראה חזר בו מלנהוג כיהודי, וכיון שבעיקרו מצד הדין יהודי הוא, אפשר להשתמש בספרים שכתב.","על מה ששנינו במשנה שאין קונים ספרים תפילין ומזוזות מן הגויים אלא בדמיהם, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעלין בדמיהן,\u0004 כלומר, מוסיפים מעט על דמיהם \u0003עד כדי טרפעיק.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003טרפעיק\u0004 זה? \u0003אמר רב ששת: איסתירא\u0004 (חצי דינר).","מסופר: \u0003ההיא טייעתא דאייתי חייתא דתפילי לקמיה דאביי\u0004 \u0005[ערביה אחת שהביאה שק מלא תפילין לפני אביי].\u0006 \u0003אמר לה: \"יהבת\u0004 \u0005[\u0006האם \u0005תתני]\u0006 \u0003לי ריש ריש\u0004 \u0005[ראש ראש],\u0006 זוג זוג של תפילין, \u0003בתמרי\u0004 \u0005[בתמר]\u0006 עבור כל אחד? \u0003אימליא זיהרא, שקלא שדתינהו בנהרא\u0004 \u0005[התמלאה חימה,\u0006 לקחה ו\u0005זרקה אותם בנהר],\u0006 משום שהציע לה סכום פעוט כל כך, \u0003אמר\u0004 אביי בחרטה: \u0003לא אבעי לי לזלזולינהו באפה כולי האי\u0004 \u0005[הייתי צריך לזלזל אותם בפניה כל כך]\u0006 אלא להציע לה סכום לפי השווי.","\u0003המוציא\u0004 (המגרש) \u0003את אשתו משום שם רע,\u0004 שיצא עליה קול שזנתה — \u0003לא יחזיר\u0004 לישא אותה אחר כך, אפילו אם התברר שהשם הרע היה שקר. וכן המוציא את אשתו \u0003משום נדר\u0004 שנדרה ואינו יכול לעמוד בו — \u0003לא יחזיר. ר' יהודה אומר: כל נדר שידעו בו רבים\u0004 — \u0003לא יחזיר, ו\u0004נדר \u0003שלא ידעו בו רבים\u0004 — \u0003יחזיר.\u0004","\u0003ר' מאיר\u0004 מחלק באופן אחר ו\u0003אומר: כל נדר שצריך חקירת\u0004 והתרת \u0003חכם\u0004 — \u0003לא יחזיר, ושאינו צריך חקירת חכם\u0004 ואפשר להתיר אותו גם בלי התרת החכם — \u0003יחזיר. אמר ר' אלעזר: לא אסרו\u0004 נדר \u0003זה\u0004 שצריך חקירת חכם \u0003אלא מפני זה\u0004 שאינו צריך, ולא מן הדין אלא כדי שלא לחלק בדברים.","\u0003אמר ר' יוסי בר' יהודה: מעשה בצידן, ב\u0004אדם \u0003אחד שאמר לאשתו: \"קונם\u0004 אסורה את עלי בנדר \u0003אם איני מגרשיך\", וגרשה, והתירו לו חכמים שיחזירנה מפני תיקון העולם.\u0004","\u0003אמר רב יוסף בר מניומי אמר רב נחמן:\u0004 מה שאמרנו במשנה שהמוציא את אשתו משום שם רע לא יחזיר — \u0003והוא\u0004 דווקא באופן \u0003שאמר לה\u0004 במפורש: \u0003\"משום שם רע אני מוציאך\",\u0004"],["\u0003\"משום נדר אני מוציאך\",\u0004 ומסבירים, \u0003קסבר\u0004 \u0005[סבור\u0006 \u0005הוא]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאסור להחזירה \u0003מאי\u0004 \u0005[מהו]\u0006 — \u0003משום קלקולא\u0004 \u0005[קלקול],\u0006 שחוששים שמא לאחר שגירשה יאמר שנתברר לו שהיתה זו טעות, ולא נתכוון לגרשה בידיעה זו שהוא יודע עתה ונמצא הגט בטל, ואם נישאה לאחר — נמצאת שנישאה באיסור ובניה ממזרים, לכן \u0003אי אמר לה\u0004 \u0005[אם אומר]\u0006 \u0003הכי\u0004 \u0005[כך],\u0006 שמטעם זה הוא מוציאה — \u0003מצי מקלקל לה\u0004 \u0005[יכול לקלקל אותה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 אמר כן בזמן שגירשה — \u0003לא מצי מקלקל לה\u0004 \u0005[אינו יכול לקלקל אותה],\u0006 שלא יקבלו את טענתו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת; \u0003אמר רב יוסף בר מניומי אמר רב נחמן: צריך שיאמר לה \"הוי יודעת שמשום שם רע אני מוציאך ומשום נדר אני מוציאך\",\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 שאמרו במשנה שלא יחזירה — \u0003כדי שלא יהו בנות ישראל פרוצות בעריות ובנדרים,\u0004 שקנסו חכמים נשים אלה שנהגו שלא כהוגן, שאם נתגרשו משום כך — לא יוכלו לחזור עוד לבעליהן, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003צריך למימר\u0004 \u0005[לומר]\u0006 \u0003לה הכי\u0004 \u0005[כך]\u0006 כדי שישמש הדבר כאזהרה לנשים אחרות.","ומעירים: \u0003תניא כלישנא קמא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה]\u0006 של רב יוסף בר מניומי בשם רב נחמן, \u0003ותניא כלישנא בתרא\u0004 \u0005[ושנויה\u0006 ברייתא אחרת \u0005כלשון אחרונה].\u0006","\u0003תניא כלישנא קמא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון ראשונה],\u0006 \u0003אמר ר' מאיר: מפני מה אמרו המוציא את אשתו משום שם רע לא יחזיר ומשום נדר לא יחזיר\u0004 — \u0003שמא תלך ותנשא לאחר ונמצאו\u0004 לבסוף \u0003דברים בדאין,\u0004 לא היו נכונים, שהשם הרע לא היה נכון, או שניתן היה להפר את הנדר, \u0003ויאמר\u0004 האיש שגירשה: \u0003\"אילו הייתי יודע שכן הוא,\u0004 שהשמועה היתה שקר, או שהנדר הוא בר הפרה \u0003אפילו אם היו נותנים לי מאה מנה\u0004 כדי לגרשה — \u0003לא הייתי מגרשה\", ונמצא\u0004 ה\u0003גט בטל ובניה\u0004 שנולדו לה מבעלה השני — \u0003ממזרין, לפיכך אומרים לו\u0004 מראש: \u0003הוי יודע, שהמוציא את אשתו משום שם רע\u0004 — \u0003לא יחזיר,\u0004 גם אם יוודע לו שהשם הרע שיצא עליה היה שקר, \u0003ומשום נדר\u0004 — \u0003לא יחזיר.\u0004","וכן \u0003תניא כלישנא בתרא\u0004 \u0005[שנויה\u0006 ברייתא \u0005כלשון אחרונה],\u0006 \u0003אמר ר' אלעזר בר' יוסי: מפני מה אמרו המוציא את אשתו משום שם רע לא יחזיר ומשום נדר לא יחזיר?\u0004 — כדי \u0003שלא יהו בנות ישראל פרוצות בעריות ובנדרים, לפיכך,\u0004 על מנת לפרסם את הדבר, \u0003אומרים לו\u0004 כשמגרשה: \u0003אמור לה \"הוי יודעת שמשום שם רע אני מוציאך ומשום נדר אני מוציאך\".\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: כל נדר שידעו בו רבים\u0004 — \u0003לא יחזיר, ושלא ידעו בו רבים\u0004 — \u0003יחזיר. אמר ר' יהושע בן לוי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 מניין לו שיש לחלק בין נדר שידעו בו רבים לבין כזה שלא ידעו בו? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת הגבעונים: \u0003\"ולא הכום בני ישראל כי נשבעו להם\u0004 \u0003נשיאי העדה\"\u0004 (יהושע ט, יח), משמע ששבועה שנעשתה בפני רבים אי אפשר לבטל אותה, וכן אם נדר נדר שיודעים בו רבים — שוב אי אפשר לבטלו.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שאף לנדר כזה יש הפרה, משיבים הם על כך: \u0003התם\u0004 \u0005[שם],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003חלה שבועה עילוייהו\u0004 \u0005[עליהם]\u0006 \u0003כלל? כיון\u0004 ש\u0003אמרו להו\u0004 \u0005[להם]\u0006 הגבעונים: \u0003\"מארץ רחוקה באנו\"\u0004 (יהושע ט, ו) \u0003ולא באו\u0004 מארץ רחוקה, \u0003לא חיילה\u0004 \u0005[חלה]\u0006 \u0003שבועה עילוייהו\u0004 \u0005[עליהם]\u0006 \u0003כלל,\u0004 שהיתה זו שבועה בטעות, \u0003והאי דלא קטלינהו\u0004 \u0005[וזה שלא הרגו אותם]\u0006 כשאר עמי ארץ כנען הרי זה \u0003משום קדושת השם,\u0004 שאם היו הורגים אותם היה בזה חילול שם שמים, במה שלא קיימו את שבועתם, למרות שבעצם לא היתה זו שבועה של ממש.","ושואלים: \u0003וכמה\u0004 הם \u0003רבים\u0004 לענין זה? \u0003רב נחמן אמר: שלשה\u0004 אנשים, \u0003ר' יצחק אמר: עשרה.\u0004","ומבארים את דבריהם, \u0003רב נחמן אמר: שלשה,\u0004 והוא לומד זאת ממה שאנו לומדים בענין נידה ועוד ש\u0003\"ימים\"\u0004 (ויקרא טו, כה) — הם \u0003שנים, \"רבים\"\u0004 (ויקרא טו,כה) — \u0003שלשה. ר' יצחק אמר: עשרה, דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת הגבעונים, שהוא המקור לענין זה של שבועה בפני רבים: \u0003\"\u0004כי נשבעו להם נשיאי \u0003העדה\",\u0004 ועדה היא לפחות עשרה אנשים.","שנינו במשנה ש\u0003ר' מאיר אומר: כל נדר שצריך\u0004 חקירת חכם — לא יחזיר, ושאינו צריך חקירת חכם יחזיר. ואילו ר' אלעזר אומר: לא אסרו זה אלא מפני זה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: לא אסרו צריך אלא מפני שאינו צריך.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים],\u0006 מה יסוד מחלוקתם? ומסבירים, \u0003ר' מאיר סבר: אדם רוצה,\u0004 כלומר, לא איכפת לו \u0003שתתבזה אשתו בבית דין,\u0004 ולכן אם הנדר צריך חקירת חכם ויכול החכם להתירה, יש לחשוש שמא יקלקל לה ויטען שלא ידע שיש לנדר זה התרה. אבל בנדר שאינו צריך חקירת בית דין — אינו יכול לטעון כך, ולא יקבלו את טענתו.","\u0003ור' אלעזר סבר: אין אדם רוצה שתתבזה אשתו בבית דין\u0004 ואינו רוצה שאשתו תלך לבית דין על מנת להתיר את נדרה, ואין לחשוש לקלקול שיבוא אם יותר הנדר. אלא שאסרו בנדר שיכול לבטלו בלא ללכת לבית הדין — מפני שבו יכול הבעל לטעון שלא ידע שיכול להפירו. ומפני הגזירה אסרו אף בזה שצריך חקירת בית דין.","\u0003אמר ר' יוסי בר' יהודה: מעשה בצידן וכו'. מאי תנא דקתני\u0004 \u0005[מה שנה\u0006 קודם \u0005ששנה]\u0006 \u0003מעשה\u0004 זה? הרי לכאורה למעשה זה אין שייכות עם דברי המשנה הקודמים!","ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך שנויה\u0006 היא בשלימות\u0005]:\u0006 \u0003במה דברים אמורים?\u0004 — \u0003כשנדרה היא\u0004 — אז אינו יכול להחזירה, \u0003אבל\u0004 אם \u0003נדר איהו\u0004 \u0005[הוא]\u0006 — \u0003יחזיר, ואמר ר' יוסי בר' יהודה: מעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בצידן, באחד שאמר לאשתו: \"קונם אם איני מגרשיך\" וגירשה, והתירו לו חכמים שיחזירנה מפני תיקון העולם.\u0004"],["ומעתה מבארים את המשנה: \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"קונם\"\u0004 שאמר, הרי \"קונם\" היא לשון נדר כעין הקדש, ומה אוסר זה עליו בקונם? \u0003אמר רב הונא, באומר: \"יאסרו כל פירות שבעולם עלי אם איני מגרשך\".\u0004","שנינו במשנה: \u0003והתירו לו שיחזירנה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]:\u0006 שכן הוא, ומדוע לא יחזירנה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליגזור\u0004 \u0005[נגזור]\u0006 \u0003משום\u0004 מה שאמר \u0003ר' נתן, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: הנודר\u0004 — \u0003כאילו בנה במה, והמקיימו,\u0004 את הנדר הזה — \u0003כאילו הקריב עליה קרבן,\u0004 והיה מקום לומר שמפני שחטא ונדר וקיים נדרו — יקנסוהו ולא יחזיר את אשתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי שנדר וקיים — אין קונסים אותו.","שנינו בסוף דבריו של ר' יוסי בר' יהודה: \u0003\"מפני תיקון העולם\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003תיקון העולם איכא\u0004 \u0005[יש]\u0006 במה שמחזירה? \u0003אמר רב ששת: ארישא\u0004 \u0005[על ראש\u0006 המשנה\u0005]\u0006 מוסבים הדברים. שמה שנאמר \"מפני תיקון העולם\" אינו הסבר לדברי ר' יוסי בר' יהודה שבסוף המשנה, אלא הסבר לתחילת המשנה — מדוע אסור להחזיר אשה שגירשה משום נדר או משום שיצא עליה שם רע.","\u0003רבינא אמר: לעולם\u0004 תאמר שהקטע הזה מתייחס \u0003אסיפא\u0004 \u0005[על סוף\u0006 המשנה\u0005],\u0006 \u0003והכי קתני\u0004 \u0005[וכך שנה]:\u0006 \u0003אין בזו מפני תיקון העולם,\u0004 כלומר, שמה שאמרו שלא יחזירנה מפני תיקון העולם הוא רק במקרה שהאשה נודרת, אבל כשהבעל נודר — אין בזה משום תיקון העולם, ומשום כך יכול להחזירה.","\u0003המוציא\u0004 (המגרש) \u0003את אשתו משום אילונית,\u0004 שגילה לאחר שנשאה שהיא איילונית, ואינה ראויה ללדת, \u0003ר' יהודה אומר: לא יחזיר\u0004 וישא אותה לעולם. \u0003וחכמים אומרים:\u0004 אם רוצה \u0003יחזיר.\u0004","אם \u0003נישאת\u0004 אותה אשה \u0003ל\u0004איש \u0003אחר והיו לה בנים הימנו\u0004 (ממנו) ומתברר איפוא שאינה איילונית, \u0003והיא תובעת כתובתה\u0004 מבעלה הראשון, שאומרת שלא כדין הוציאה כאיילונית בלא כתובה, ומגיעה לה כתובה שלא נתן לה — \u0003אמר ר' יהודה, אומר לה: שתיקותיך\u0004 (שתיקתך) \u0003יפה מדיבוריך,\u0004 שמוטב לה לשתוק ולא להעלות טענה זו. שיכול הבעל לטעון שאילו ידע שיהיה צריך לתת לה כתובה לא היה מגרשה כלל, ולפי טענתה היו הגירושין בטעות והרי נישואיה לשני בטלים ובניה ממזרים.","לענין המחלוקת במגרש את אשתו משום איילונית, שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שטעמו של \u0003ר' יהודה\u0004 הוא משום ש\u0003חייש לקלקולא\u0004 \u0005[חושש\u0006 הוא \u0005לקלקול],\u0006 שמא יתברר לבסוף שלא היתה איילונית, והבעל יטען שבטעות גירש אותה, ונמצא הגט בטל. ומשום כך, אם יודע שאינו יכול להחזירה, גומר בליבו לגרשה בכל אופן, \u0003ורבנן לא חיישי לקלקולא\u0004 \u0005[וחכמים אינם חוששים לקלקול]?\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שומעים אנו אותם\u0006 שאמרו\u0005]!\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא את אשתו משום שם רע\u0004 — \u0003לא יחזיר, ומשום נדר\u0004 — \u0003לא יחזיר. ר' יהודה אומר: כל נדר שידעו בו רבים\u0004 — \u0003לא יחזיר, ושלא ידעו בו רבים\u0004 — \u0003יחזיר. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003רבנן חיישי לקלקולא\u0004 \u0005[חכמים חוששים לקלקול]\u0006 ולכן אינם מחלקים בין נדר לנדר, \u0003ור' יהודה לא חייש לקלקולא\u0004 \u0005[אינו חושש לקלקול]\u0006 ואינו מחלק אלא בין נדר שיש בו פריצות לבין כזה שאין בו!","\u0003אמר שמואל: איפוך\u0004 \u0005[הפוך]\u0006 את השיטות במשנתנו, ואמור שר' יהודה הוא האומר שיחזירנה ואינו חושש לקלקול, וחכמים הם החוששים לקלקול.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה בסוף\u0006 המשנה\u0005]:\u0006 \u0003נישאת לאחר והיו לה בנים הימנו, והיא תובעת כתובתה, אמר ר' יהודה, אומר לה: \"שתיקותיך\u0004 (שתיקתך) \u0003יפה מדיבוריך\", מכלל\u0004 הדברים אתה למד ש\u0003ר' יהודה חייש לקלקולא\u0004 \u0005[חושש לקלקול]!\u0006 ומשיבים: \u0003הא נמי איפוך\u0004 \u0005[זו גם כן הפוך].\u0006","\u0003אביי אמר: לעולם לא תיפוך\u0004 \u0005[אין אתה\u0006 צריך \u0005להפוך],\u0006 \u0003ור' יהודה\u0004 חושש לקלקול, אלא \u0003בההיא\u0004 \u0005[באותה\u0006 משנה קודמת\u0005],\u0006 לענין אשה שנדרה, \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר, וסבר לה\u0004 \u0005[וסבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר. ב\u0004נדר ש\u0003צריך\u0004 חקירת חכם \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' אלעזר\u0004 שבמקרה זה אין חשש לקלקול ומותר להחזירה, \u0003בשאינו צריך סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' מאיר\u0004 שמתיר להחזירה במקרה זה.","\u0003אמר רבא:\u0004 וכי \u0003דר'\u0004 \u0005[מ\u0006דבריו \u0005של ר']\u0006 \u0003יהודה אדר'\u0004 \u0005[על\u0006 דבריו \u0005של ר']\u0006 \u0003יהודה קשיא\u0004 \u0005[קשה],\u0006 \u0003דרבנן אדרבנן\u0004 \u0005[משל חכמים על של חכמים]\u0006 \u0003לא קשיא\u0004 \u0005[קשה]?\u0006 הרי גם כאן קיימת סתירה!","\u0003אלא אמר רבא: דר'\u0004 \u0005[מ\u0006דבריו \u0005של ר']\u0006 \u0003יהודה אדר'\u0004 \u0005[על\u0006 דבריו \u0005של ר']\u0006 \u0003יהודה לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כדשנינן\u0004 \u0005[כפי שתירצנו].\u0006 \u0003דרבנן אדרבנן\u0004 \u0005[משל חכמים על של חכמים]\u0006 \u0003לא קשיא\u0004 \u0005[קשה],\u0006 כי \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 הנזכרים כאן? — \u0003ר' מאיר\u0004 הוא, ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003תנאי כפול,\u0004 ותנאי שאינו כופל ומפרש בו מה יהיה במקרה שיתקיים התנאי, וגם מה יהיה כשהתנאי יתבטל — אינו תנאי. \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 — \u0003ב\u0004ש\u0003לא כפליה לתנאיה\u0004 \u0005[כפל את תנאו],\u0006 ולשיטתו אין זה נחשב כתנאי, ולכן יכול להחזירה.","\u0003המוכר את עצמו ואת בניו לגוים\u0004 — \u0003אין פודין אותו, אבל פודין את הבנים לאחר מיתת אביהן,\u0004 שהרי הם אינם אשמים בכך.","\u0003אמר רב אסי:\u0004 מה שאמרנו שאין פודים אותו, \u0003והוא\u0004 דווקא באופן \u0003שמכר\u0004 עצמו \u0003ושנה ושילש.\u0004 שכיון שהוא רגיל בכך, קנסו אותו שלא יפדוהו עוד.","מסופר: \u0003הנהו\u0004 \u0005[אותם\u0006 אנשים\u0005]\u0006 \u0003בני\u0004 המקום \u0003בי מיכסי דיזפי זוזי\u0004 \u0005[שלוו כסף]\u0006 \u0003מגוים ולא הוה להו למפרעינהו\u0004 \u0005[היה להם לפרוע להם].\u0006 \u0003אתו וקא גרבי להו\u0004 \u0005[באו\u0006 הגויים \u0005ולקחו אותם כעבדים],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב הונא\u0004 שיורה שיפדו אותם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי איעביד לכו\u0004 \u0005[מה אעשה לכם],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוכר את עצמו ואת בניו לגוים\u0004 — \u0003אין פודין אותו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא: לימדתני רבינו, והוא שמכר ושנה ושלש\u0004 והם לא עשו כן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מרגל רגילי דעבדי הכי\u0004 \u0005[אלה רגילים לעשות כך]\u0006 והרי זה כמי ששנה ושילש.","מסופר: \u0003ההוא גברא דזבין נפשיה ללודאי\u0004 \u0005[אדם אחד שמכר\u0006 את \u0005עצמו ללודרים],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי, אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003פירקן\u0004 \u0005[פדה אותי],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003המוכר עצמו ואת בניו לגוים\u0004 — \u0003אין פודין אותו, אבל פודין את הבנים.\u0004 ומה טעם פודים אותם? — \u0003משום קלקולא\u0004 \u0005[קלקול],\u0006 כדי שלא יתקלקלו וייטמעו בין הגויים, \u0003וכל שכן הכא\u0004 \u0005[כאן]\u0006 \u0003דאיכא קטלא\u0004 \u0005[שיש\u0006 פה חשש \u0005מיתה].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לר' אמי: האי\u0004 \u0005[\u0006איש \u0005זה]\u0006 \u0003ישראל מומר הוא, דקא חזו ליה דקאכיל\u0004 \u0005[שראו אותו שאוכל]\u0006 \u0003נבילות וטריפות! אמר להו\u0004 \u0005[להם]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003לתיאבון\u0004 (לתאווה) \u0003הוא דקאכיל\u0004 \u0005[שאוכל],\u0006 ואין זו הוכחה שהוא משומד ויוצא מן היהדות, אלא מפני תאוותו, שרצה לאכול.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא זמנין דאיכא היתירא ואיסורא קמיה ושביק היתירא ואכיל איסורא\u0004 \u0005[והרי פעמים שיש\u0006 מאכלי \u0005היתר ואיסור לפניו ו\u0006הוא \u0005מניח\u0006 את \u0005ההיתר ואוכל\u0006 את \u0005האיסור]!\u0006 כיון ששמע כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי לאותו אדם: \u0003זיל, לא קא שבקי לי דאפרקינך\u0004 \u0005[לך, אין מניחים לי שאפדה אותך].\u0006","אגב כך מסופר: \u0003ריש לקיש זבין נפשיה ללודאי\u0004 \u0005[מכר\u0006 את \u0005עצמו ללודרים],\u0006 \u0003שקל בהדיה חייתא וגלגלתא\u0004 \u0005[לקח איתו שק ועיגול אבן\u0006 בתוכו\u0005],\u0006 \u0003אמר: גמירי דיומא בתרא כל דבעי מינייהו עבדי ליה, כי היכי דליחול אדמיה\u0004 \u0005[למודים אנו שביום האחרון של המומת על ידם, כל שמבקש מהם עושים לו, כדי שימחל על דמו]\u0006 ודבר זה ודאי יהיה לי לתועלת.","\u0003יומא בתרא\u0004 \u0005[ביום האחרון]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי ניחא\u0004 \u0005[מה נוח]\u0006 \u0003לך,\u0004 מה רצונך שנעשה עבורך? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בעינא אקמטינכו\u0004 \u0005[רוצה אני שאקשור אתכם]\u0006 \u0003ואותבינכו\u0004 \u0005[ואושיב אתכם],\u0006 \u0003וכל חד מינייכו אמחיה חייתא ופלגא\u0004 \u0005[וכל אחד מכם אכה אותו מכה וחצי].\u0006 \u0003קמטינהו ואותבינהו\u0004 \u0005[קשר אותם והושיב אותם],\u0006 \u0003כל חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003כד מחייה חד חייתא נפק נשמתיה\u0004 \u0005[כאשר היכה אותו מכה אחת יצאה נשמתו]\u0006 לפי שהיה ריש לקיש גיבור בכוחו. \u0003חרקיניה לשיניה\u0004 \u0005[חרק בשיניו]\u0006 ככועס, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אחוכי קא מחייכת בי\u0004 \u0005[אתה צוחק ממני]?\u0006 \u0003אכתי פש לך גבי פלגא דחייתא\u0004 \u0005[עדיין נותרה לך אצלי חצי מכה].\u0006 \u0003קטלינהו כולהו\u0004 \u0005[הרג אותם כולם].\u0006","\u0003נפק ואתא\u0004 \u0005[יצא ובא],\u0006 ולאחר אותם זמנים \u0003יתיב קאכיל ושתי\u0004 \u0005[היה יושב אוכל ושותה]\u0006 בלא דאגה לפרנסתו. \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003ברתיה\u0004 \u0005[בתו]:\u0006 \u0003לא בעית מידי למזגא עליה\u0004 \u0005[אין אתה רוצה דבר לישון עליו]?\u0006 \u0003אמר לה: בתי, כריסי כרי,\u0004 ודי לי בכך. \u0003כי נח נפשיה שבק קבא דמוריקא\u0004 \u0005[כאשר נפטר השאיר\u0006 בירושתו \u0005קב של כרכום],\u0006 ואף על פי כן \u0003קרא אנפשיה\u0004 \u0005[על עצמו]:\u0006 \u0003\"ועזבו לאחרים חילם\"\u0004 (תהלים מט, יא), שהצטער שלא השתמש בעצמו בכל רכושו.","\u0003המוכר את שדהו לגוי\u0004 — \u0003לוקח\u0004 (קונה) מן הגוי \u0003ומביא ממנו,\u0004 מהשדה שמכר, \u0003בכורים, מפני תיקון העולם.\u0004","\u0003אמר רבה: אף על פי שאין קנין\u0004 קרקע \u0003לגוי בארץ ישראל להפקיע\u0004 את פירותיה \u0003מידי מעשר,\u0004 ועדיין קדושת הארץ עליה, ויש עליה חובת תרומות ומעשרות ושאר חובות התלויות בארץ, \u0003שנאמר: \"כי לי הארץ\"\u0004 (ויקרא כה, כג) והכוונה היא: \u0003לי קדושת הארץ\u0004 ואינה בטלה במכירתה מישראל לגוי. \u0003אבל יש קנין לגוי בארץ ישראל לחפור בה,\u0004 באדמה שקנה, \u0003בורות שיחין ומערות, שנאמר: \"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (תהלים קטו, טז).","\u0003ור' אלעזר אומר: אף על פי שיש קנין לגוי בארץ ישראל להפקיע מידי מעשר, שנאמר\u0004 במעשר: \u0003\"דגנך\"\u0004 (דברים יב, יז), ויש בכך הדגשה: דגנך שלך חייב במעשרות \u0003ולא דגן\u0004 של \u0003גוי, אבל אין קנין לגוי בארץ ישראל לחפור בה בורות שיחין ומערות, שנאמר: \"לה' הארץ\u0004 ומלואה","\u0003\"\u0004(תהלים כד, א). ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה מקור, \u0005הם חלוקים]?\u0006 ומשיבים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר, \u0005סבור]:\u0006 \u0003\"דגנך\"\u0004 — הוא הדגשה להשמיענו: \u0003ולא דגן גוי. ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבה, \u0005סבור]:\u0006 \"דגנך\" אין משמעו התבואה עצמה, אלא \u0003\"דיגונך\"\u0004 — צבירת התבואה הקצורה לעשותה כרי, שאז התבואה נקראת דגן — היא המחייבת במעשר, \u0003ולא דיגון\u0004 של \u0003גוי,\u0004 שאף הוא מודה שאם הגוי קצר ואסף את הדגן אינו חייב במעשר.","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה],\u0006 את שיטתי זו שאין קנין לגוי בארץ ישראל להפקיע מתרומות ומעשרות? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלקט והשכחה והפאה של גוי\u0004 — \u0003חייבין במעשר אלא אם כן הפקיר.\u0004","ומעתה נדון: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיו אלה לקט שכחה ופאה של \u0003ישראל וליקטינהו\u0004 \u0005[וליקט אותם]\u0006 \u0003גוי,\u0004 ואחר כך מכר אותם לישראל. אם כן, הלשון \u0003\"אלא אם כן הפקיר\"\u0004 תמוהה, \u0003הא מפקרי וקיימי\u0004 \u0005[הרי\u0006 הם \u0005מופקרים ועומדים],\u0006 שכן לקט שכחה ופאה הריהם הפקר לכל הבא לקחתם! \u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה במשנה שהתבואה שייכת מתחילה ל\u0003גוי\u0004 והגוי מדעת עצמו הפריש והפקיר לקט שכחה ופאה \u0003וליקטינהו\u0004 \u0005[וליקט אותם]\u0006 \u0003ישראל.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כש\u0003הפקיר\u0004 הגוי את התבואה — הרי היא פטורה מן המעשר, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא הפקיר\u0004 — \u0003חייב\u0004 במעשר. ומכאן שאין קניינו של הגוי מפקיע את השדה מחיוב תרומות ומעשרות!","ודוחים: \u0003לא, לעולם\u0004 תפרש שהיו אלה לקט ושכחה של \u0003ישראל וליקטינהו\u0004 \u0005[וליקט אותם]\u0006 \u0003גוי, ודקא אמרת\u0004 \u0005[ומה שאתה אומר]:\u0006 \u0003הא מפקרי וקיימי\u0004 \u0005[הרי\u0006 הם \u0005מופקרים ועומדים]\u0006 כדין כל פאה — אין זה נכון, \u0003נהי דמפקרי אדעתא דישראל\u0004 \u0005[אם אמנם מופקרים הם על דעת ש\u0006יקח אותם \u0005ישראל],\u0006 \u0003אדעתא דגוי מי מפקרי\u0004 \u0005[על דעת ש\u0006יקח אותם \u0005גוי האם\u0006 הם \u0005מופקרים]?\u0006 ואם כן, צריך להפקיר אותם במפורש לכל, ואם לא הריהם חייבים במעשר כתבואה רגילה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003ישראל שלקח\u0004 (קנה) \u0003שדה מגוי עד שלא הביאה שליש,\u0004 כלומר, עדיין לא הגיעה התבואה לשליש בישולה שהוא זמן חיובה במעשר, \u0003וחזר ומכרה לו\u0004 לגוי \u0003משהביאה שליש\u0004 — \u0003חייבת במעשר.\u0004 ומדוע — \u0003שכבר נתחייבה\u0004 במעשר משעה שהביאה שליש ברשות ישראל. ונדייק מכאן: דווקא \u0003נתחייבה\u0004 ברשות ישראל — \u0003אין\u0004 \u0005[כן],\u0006 ואם \u0003לא נתחייבה\u0004 עדיין ברשותו — \u0003לא!\u0004 משמע שמה שגדל כולו ברשות גוי פטור ממעשר ויש איפוא קנין לגוי בארץ ישראל להפקיע מתרומות ומעשרות!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 לא בארץ ישראל אלא \u0003בסוריא, וקסבר\u0004 \u0005[וסבור\u0006 הוא\u0005]\u0006 ש\u0003כיבוש יחיד לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003כיבוש,\u0004 וכיון שרק יחיד = דוד המלך, כבש את סוריה — אין דינה כארץ ישראל לכל דבר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003ישראל וגוי שלקחו\u0004 (קנו) \u0003שדה בשותפות\u0004 —"],["\u0003טבל וחולין מעורבין זה בזה,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: של גוי,\u0004 כלומר, החלק שמגיע לידו — \u0003פטור\u0004 מתרומות ומעשרות, \u0003ושל ישראל\u0004 — \u0003חייב.\u0004","ולענייננו נדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 ש\u0003יש ברירה,\u0004 ואנו אומרים שכל מה שקיבל כל אחד בחלקו מתברר כאילו היה שלו משעה ראשונה, ולכן של הגוי הוא כולו חולין. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]\u0006 ש\u0003אין ברירה,\u0004 ולכן הטבל והחולין מעורבים בכל התבואה גם לאחר שחילקו אותה ביניהם, \u0003אבל דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יש קנין לגוי בארץ ישראל להפקיע מיד מעשר,\u0004 שהרי חלקו של הגוי הוא חולין!","ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בסוריא, וקסבר\u0004 \u0005[וסבור\u0006 הוא\u0005]\u0006 ש\u0003כיבוש יחיד לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003כיבוש\u0004 להחשיב אותו שטח כארץ ישראל לכל דבר, ולכן יש קנין לגוי בסוריא להפקיע מידי תרומות ומעשרות.","\u0003אמר רב חייא בר אבין, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003המוכר שדהו לגוי\u0004 — \u0003לוקח\u0004 (קונה) \u0003ומביא ביכורים מפני תיקון העולם.\u0004 ונדייק מכאן: \u0003מפני תיקון העולם\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הוא כן צריך להביא ביכורים, אבל \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 — הוא \u0003לא\u0004 צריך משמע שקנין הגוי מפקיע את הקדושה!","\u0003אמר רב אשי: שתי תקנות הוו\u0004 \u0005[היו]\u0006 בענין זה, \u0003מעיקרא הוו מייתי\u0004 \u0005[מתחילה היו\u0006 מוכרי שדותיהם לגויים \u0005מביאים]\u0006 ביכורים \u0003מדאורייתא\u0004 \u0005[מ\u0006דין \u0005תורה],\u0006 \u0003כיון דחזו דקא מקרי ומזבני\u0004 \u0005[שראו\u0006 חכמים \u0005שמזדמנים ומוכרים]\u0006 אנשים קרקעותיהם לגויים, \u0003דסברי בקדושתייהו קיימן\u0004 \u0005[ש\u0006הם, המוכרים, \u0005סבורים\u0006 שבקדושתם הם \u0005עומדים]\u0006 כמו בתחילה, שהרי מביאים משם ביכורים, ואם כן אין רע בכך — \u0003תקינו להו\u0004 \u0005[תיקנו להם]\u0006 ש\u0003לא ליתו\u0004 \u0005[יביאו]\u0006 ביכורים, כדי שיחשבו שבמכירה זו הפקיעו את הקרקע מקדושתה.","\u0003כיון דחזו דמאן דלא סגי ליה מזבן\u0004 \u0005[שראו שמי שאינו יכול מוכר]\u0006 בכל זאת, \u0003וקא משתקען\u0004 \u0005[ו\u0006השדות \u0005משתקעים]\u0006 \u0003ביד גוים\u0004 ואין פודים אותם, \u0003הדר תקינו להו דליתו\u0004 \u0005[חזרו\u0006 ו\u0005תיקנו להם שיביאו ביכורים]\u0006 כדי לקנוס את המוכר, ולגרום לו שיחזור ויקנה את השדה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003המוכר שדהו לפירות\u0004 בלבד, שמשאיר בידו את הבעלות על גוף השדה ומוכר לאחר רק את כל פירותיו, \u0003ר' יוחנן אמר:\u0004 הקונה \u0003מביא\u0004 ביכורים מן השדה הזה \u0003וקורא\u0004 מקרא ביכורים האמור בתורה (דברים כו, ה—י), שכן יכול הוא לומר \"האדמה אשר נתתה לי ה'\" (דברים כו, י). \u0003ריש לקיש אמר:\u0004 הקונה אמנם \u0003מביא ו\u0004אולם \u0003אינו קורא.\u0004","ומסבירים את הבדלי השיטות: \u0003ר' יוחנן אמר מביא וקורא,\u0004 סבור הוא ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שאף על פי שאין גוף השדה שלו, כיון שבפועל שייכים לו כל פירות השדה — הרי זה כקנין הגוף. \u0003ריש לקיש אמר מביא ואינו קורא,\u0004 שהוא סבור ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 מן הברייתא, נאמר בענין ביכורים: \u0003\"\u0004ושמחת בכל הטוב אשר נתן לך ה' אלקיך \u0003ולביתך\"\u0004 (דברים כו, יא), וביתו של אדם — אשתו. ומכאן אמרו חכמים: \u0003מלמד, שאדם מביא ביכורי אשתו וקורא.\u0004 והרי בנכסי אשתו אין לו קנין הגוף אלא רק קנין פירות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש \u0003\"ולביתך\",\u0004 ללמד שלענין זה גזירת הכתוב שגם מה ששייך לביתו = אשתו נכלל בגדר המצוה, אבל אין זה מוכיח שכך הוא הדין בכל מי שזכותו בשדה היא רק בפירות.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת: \u0003איתיביה\u0004 \u0005[הקשה לו],\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן\u0004 מאותה ברייתא: נאמר \u0003\"ולביתך\"\u0004 — \u0003מלמד, שאדם מביא ביכורי אשתו וקורא.\u0004 ונדייק: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שמביא וקורא \u0003דכתיב\u0004 \u0005[שנאמר\u0006 במפורש\u0005]\u0006 \u0003\"ולביתך\", אבל בעלמא\u0004 \u0005[בכלל]\u0006 — \u0003לא,\u0004 הרי שאין הקונה שדה לפירות מביא ביכורים וקורא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003טעמא דידי נמי מהכא קאמינא\u0004 \u0005[טעמי שלי גם כן מכאן אמרתי],\u0006 שאני רואה זאת לא כיוצא מן הכלל, אלא כדוגמא המלמדת על הכלל כולו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ריש לקיש לר' יוחנן ממה ששנינו: \u0003היה בא בדרך\u0004 לירושלים \u0003וביכורי אשתו בידו, ושמע שמתה אשתו\u0004 — \u0003מביא וקורא.\u0004 ונדייק מכאן: \u0003מתה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שכיון שמתה — הריהו יורשה, ונמצא שהנכסים שלו הם, אבל \u0003לא מתה\u0004 — \u0003לא,\u0004 אינו קורא. משמע שבדבר שיש לו בו רק קנין פירות אינו קורא!","ומשיבים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא מתה\u0004 גם כן מביא וקורא, ובמקרה ש\u0003מתה אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003ליגזור\u0004 \u0005[שנגזור]\u0006 פה \u0003משום\u0004 מה שאמר \u0003ר' יוסי בר חנינא\u0004 בענין דומה, ש","\u0003אמר ר' יוסי בר חנינא: בצרן,\u0004 את ביכוריו \u0003ושגרן\u0004 (שלחם) \u0003ביד שליח, ומת שליח בדרך\u0004 — \u0003מביא\u0004 הבעלים או אחר, אבל \u0003אינו קורא, שנאמר: \"ולקחת... והבאת\"\u0004 (ראה דברים כו, פסוקים ב—ג), ללמד מהיקש זה: \u0003עד שתהא לקיחה והבאה באחד,\u0004 ואף במביא ביכורי אשתו ומתה היה מקום לגזור כן, כיון שלא היו הלקיחה וההבאה כאחד, שהרי בלקיחה היו אלה ביכורי אשתו, ובהבאה — ביכוריו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אומרים שנתחדשו פה בעלים, אלא שהוא נחשב כאילו היה בעליה של הנחלה הזו גם קודם לכן.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[ו\u0006הם, ר' יוחנן וריש לקיש, \u0005הולכים לטעמם,\u0006 לשיטתם\u0005]\u0006 במחלוקת עקרונית זו, \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בשאלה הבאה: \u0003המוכר שדהו\u0004"],["\u0003בזמן שהיובל נוהג,\u0004 וכל מכירת קרקע אז היא רק לפירות, שהרי גוף הקרקע חוזר בשנת היובל לבעלים, \u0003ר' יוחנן אמר:\u0004 הקונה \u0003מביא\u0004 ביכורים \u0003וקורא. ריש לקיש אמר:\u0004 הקונה \u0003מביא ו\u0004אולם \u0003אינו קורא.\u0004","ומבארים את השיטות: \u0003ר' יוחנן אמר מביא וקורא,\u0004 שסבור הוא ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 והוא יכול לומר \"האדמה אשר נתת לי ה'\" (דברים כו, י). \u0003ריש לקיש אמר מביא ואינו קורא,\u0004 שסבור ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני המקרים השנויים במחלוקת ר' יוחנן וריש לקיש. \u0003דאי איתמר בההיא\u0004 \u0005[שאם היה נאמר\u0006 רק \u0005באותה\u0006 הלכה\u0005]\u0006 ביחס לקונה קרקע לפירות, הייתי אומר כי דווקא \u0003בההיא קאמר\u0004 \u0005[בה אמר]\u0006 \u0003ריש לקיש\u0004 שהקונה אינו קורא, \u0003דכי קא נחית\u0004 — \u0003אדעתא דפירא קא נחית\u0004 \u0005[ש\u0006כן כבר \u0005כאשר\u0006 הוא \u0005יורד\u0006 לקרקע — \u0005על דעת הפירות\u0006 הוא \u0005יורד],\u0006 שהרי פירש לו המוכר שאינו מוכר לו את גוף השדה, \u0003אבל בהך\u0004 \u0005[בזו],\u0006 בקונה שדה בזמן היובל, \u0003דאדעתא דגופיה קא נחית\u0004 \u0005[שעל דעת\u0006 לקנות את הקרקע \u0005גופה\u0006 הקונה \u0005יורד\u0006 לשדה\u0005],\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יוחנן\u0004 שמביא וקורא. ולכן היה צריך לפרש שגם בזה ריש לקיש חולק.","ומצד שני: \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר בזו],\u0006 בקונה שדה ביובל בלבד, הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' יוחנן\u0004 שהוא כקנין הגוף ולכן מביא וקורא, \u0003אבל בהך\u0004 \u0005[באחרת]\u0006 שבמפורש קנה רק לפירות \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לריש לקיש\u0004 שמביא ואינו קורא, על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 שתיאמר המחלוקת בשני המקרים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדעת ר' יוחנן ממה ששנינו: \u0003הקונה אילן וקרקעו\u0004 — \u0003מביא וקורא\u0004 אף על פי שצריך להחזיר את הקרקע ביובל, והרי זו כדעת ר' יוחנן! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בזמן שאין היובל נוהג,\u0004 שאז הקנין הוא לצמיתות.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003הקונה שני אילנות בתוך שדהו של חבירו\u0004 — \u0003מביא ואינו קורא.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם קנה \u0003שלשה\u0004 — \u0003מביא וקורא,\u0004 משום שהוא זוכה גם בקרקע שביניהם, ואף על פי שהקרקע חוזרת ביובל! ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בזמן שאין היובל נוהג.\u0004","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר רב חסדא: מחלוקת\u0004 ר' יוחנן וריש לקיש — \u0003ביובל שני,\u0004 לאחר שכבר נהגה פעם אחת שנת היובל, והיו אנשים בטוחים שאכן הקרקעות חוזרות ביובל, \u0003אבל ביובל ראשון\u0004 שהיה לישראל מייד אחרי כיבוש הארץ — \u0003דברי הכל מביא וקורא, דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא סמך דעתייהו\u0004 \u0005[סמכה דעתם]\u0006 על כך שבאמת יחזרו השדות, וחשבו אנשים שהם מוכרים לצמיתות. אם כן, לדרך זו אין צורך לתרץ לשיטת ר' יוחנן כפי שאמרנו, שמשניות אלו אמורות בזמן שאין היובל נוהג, אלא אפשר לתרץ כך: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו ושלמדנו שמביא וקורא — הרי זה \u0003ביובל ראשון, הא\u0004 \u0005[זו]\u0006 שמביא ואינו קורא — הרי זה \u0003ביובל שני.\u0004","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שהיא כמחלוקת \u0005תנאים]\u0006 בענין קנין פירות. ששנינו: \u0003מנין ללוקח\u0004 (קונה) \u0003שדה מאביו\u0004 בזמן שהיובל נוהג, \u0003והקדישה, ואחר כך מת אביו, מניין שתהא לפניו\u0004 שדה זו \u0003כשדה אחוזה,\u0004 שאם לא פדאה מן ההקדש עד היובל — שוב אינה חוזרת אליו, ואינה כשדה שקנה מחבירו (\"שדה מקנה\") והקדישה שחוזרת לבעלים ביובל?","— \u0003תלמוד לומר: \"\u0004ו\u0003אם את שדה מקנתו אשר לא משדה אחזתו\"\u0004 (ויקרא כז, כב), ומן הכפילות נלמד שדין זה הוא דווקא ב\u0003שדה שאינה ראויה להיות שדה אחוזה,\u0004 שאין הוא עתיד ליורשה, \u0003יצתה\u0004 (יצאה) \u0003זו שראויה להיות שדה אחוזה,\u0004 אף בשעה שהגיעה אליו דרך קניה, אלו \u0003דברי ר' יהודה ור' שמעון.\u0004","ואילו \u0003ר' מאיר אומר: מניין ללוקח שדה מאביו ומת אביו ואחר כך הקדישה, מניין שתהא לפניו כשדה אחוזה?\u0004 \u0003תלמוד לומר: \"\u0004ו\u0003אם את שדה מקנתו אשר לא משדה אחזתו\"\u0004 — \u0003שדה שאינה שדה אחוזה, יצתה\u0004 (יצאה) \u0003זו שהיא שדה אחוזה. ואילו לר' יהודה ור' שמעון,\u0004 המקרה של \u0003מת אביו ואחר כך הקדישה לא צריכא קרא\u0004 \u0005[צריך פסוק]\u0006 ללמדנו שדינה כשדה אחוזה, שכן פשוט שהיא לו שדה אחוזה.","ומעתה נאמר: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה\u0006 הם \u0005חלוקים],\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003ובהא\u0004 \u0005[ובזו],\u0006 בשדה שקנה מאביו, \u0003במיתת אביו הוא דלא ירית ולא מידי\u0004 \u0005[שאינו יורש דבר],\u0006 שהרי כבר כשקנה את השדה מאביו — נעשה השדה לגמרי כקניינו, ולא נשתנה דבר במות אביו, \u0003והלכך\u0004 \u0005[ועל כן]\u0006 אם \u0003מת אביו ואחר כך הקדישה\u0004 — \u0003צריך קרא\u0004 \u0005[פסוק]\u0006 ללמדנו שבכל זאת נחשבת לו מעתה כשדה אחוזה.","ואילו \u0003ר' יהודה ור' שמעון סברי\u0004 \u0005[סבורים]\u0006 ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003ובהא\u0004 \u0005[ובזו],\u0006 בשדה שקנה מאביו, \u0003במיתת אביו השתא הוא דקא ירית\u0004 \u0005[עכשיו הוא שיורש]\u0006 את גוף השדה, שהרי הואיל וקנה שדה זו בזמן שהיובל נוהג לא היה לו בה בקנייתו אלא קנין פירות, \u0003והלכך\u0004 \u0005[ומשום כך]\u0006 \u0003מת אביו ואחר כך הקדישה\u0004 — \u0003לא צריכא קרא\u0004 \u0005[צריך פסוק]\u0006 ללמדנו שדינה כדין שדה אחוזה, שהרי במות אביו נוסף לו קנין הגוף בקרקע זו. \u0003וכי איצטריך קרא\u0004 \u0005[ו\u0006משום כך \u0005כאשר הוצרך הפסוק],\u0006 \u0003ל\u0004מקרה ש\u0003הקדישה ואחר כך מת אביו הוא דאיצטריך\u0004 \u0005[שהוצרך]?\u0006","ודוחים, \u0003אמר רב נחמן בר יצחק: לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך, בעלמא קסבר\u0004 \u0005[בכלל סבורים]\u0006 \u0003ר' יהודה ור' שמעון\u0004 ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ואף לדבריהם יש צורך לדרוש את הפסוק כפי שדורש אותו ר' מאיר, למקרה שמת אביו ואחר כך הקדישה. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ר' יהודה ור' שמעון קרא אשכחו ודרוש\u0004 \u0005[מקרא\u0006 נוסף \u0005מצאו ודרשו]\u0006 ובגלל המקרא דרשו כך. כי לדעתם, אם זהו החידוש היחיד, אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"אם את שדה מקנתו אשר לא אחזתו\", מאי\u0004 \u0005[מה]\u0006 משמעות הביטוי \u0003\"\u0004אשר לא \u0003משדה אחזתו\"?\u0004 להדגיש: \u0003שדה שאינה ראויה להיות שדה אחוזה, יצתה\u0004 (יצאה) \u0003זו שראויה להיות שדה אחוזה.\u0004","\u0003אמר רב יוסף: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר' יוחנן קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003לא מצא ידיו ורגליו בבית המדרש,\u0004 כלומר, היו דבריו מביאים לסתירה חמורה בדבריו. ש\u0003אמר רב אסי אמר ר' יוחנן: האחין שחלקו\u0004 בנחלת אביהם — \u0003לקוחות הן,\u0004 שדינם כאילו קנו זה מזה, \u0003ומחזירין זה לזה ביובל.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שקנין פירות \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 אם כן \u0003לא משכחת\u0004 \u0005[תמצא]\u0006 לשיטת ר' יוחנן אדם \u0003דמייתי\u0004 \u0005[שמביא]\u0006 \u0003ביכורים\u0004 מן התורה, \u0003אלא\u0004 רק במקרה של \u0003חד בר חד\u0004 \u0005[אחד בן אחד],\u0006 כלומר, בן יחיד שהוא בנו של בן יחיד וכך הלאה \u0003עד\u0004 זמנו של \u0003יהושע בן נון,\u0004 שכל אחד מהם ירש את אביו לחלוטין, שהרי כל השאר הם לקוחות והם מחזירים זה לזה. אבל כיון שהוא סבור שקנין פירות הוא כקנין הגוף, אם כן, אף על פי שמחזירים ביובל, ואין קניינם אלא קנין פירות, לפי שעה השדה הוא שלו, ומביא וקורא.","\u0003אמר רבא: קרא ומתניתא מסייעי ליה\u0004 \u0005[הכתוב והברייתא מסייעים לו]\u0006 \u0003לריש לקיש. קרא\u0004 \u0005[הכתוב]\u0006 שנאמר:"],["\u0003\"במספר שני תבואת ימכר לך\"\u0004 (ויקרא כה, טו), משמע שלא גוף השדה נמכר אלא רק הזכות לאכילת התבואה משך מספר שנים (\"שני תבואות\").","\u0003מתניתא\u0004 \u0005[ברייתא]\u0006 מסייעת לו לריש לקיש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בכור נוטל פי שנים בשדה החוזרת לאביו ביובל,\u0004 כלומר, בשדה שמכר אותה האב וחוזרת לידי הבנים ביובל אם מת אביהם. משמע שאף על פי שמכר האב את השדה והפירות שייכים לאחר, אין אנו רואים שדה זו כדבר שהוא \"ראוי\" (שאינו של האב אלא רק ראוי להיות שלו, ובמקרה זה אין הבכור נוטל בו פי שנים), אלא כ\"מוחזק\" בידי האב גם עתה, ולכן נוטל הבכור פי שנים. והטעם הוא מפני שאנו סבורים שבעצם גוף השדה לא נמכר.","\u0003אמר אביי, נקטינן\u0004 \u0005[מוחזקים אנו]:\u0006 \u0003בעל בנכסי אשתו צריך הרשאה,\u0004 שאם הוא רוצה לדון עם אדם אחר לגבי הקרקע של נכסי מלוג שלה, שהוא אוכל פירותיהם, צריך הוא לקבל הרשאה מיוחדת מאשתו. שכיון שזכותו בשדה היא רק לאכול מן הפירות, הרי אנו פוסקים שקנין פירות אינו כקנין הגוף, ומשום כך יכול הצד שכנגד לטעון שאין הבעל צד בדין זה כיון שאינו בעל הקרקע.","ומסבירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 ש\u0003לא נחית אפירי\u0004 \u0005[ירד\u0006 לדין \u0005לגבי הפירות]\u0006 אלא רק על גוף הקרקע, \u0003אבל\u0004 אם \u0003נחית אפירי\u0004 \u0005[ירד\u0006 לדין \u0005על הפירות]\u0006 שעליהם יש לו זכות ממונית ברורה, \u0003מיגו דמשתעי דינא אפירי\u0004 \u0005[מתוך שמדבר בדין על הפירות]\u0006 — \u0003משתעי דינא אגופא\u0004 \u0005[מדבר\u0006 גם \u0005בדין על גופה]\u0006 של הקרקע ואינו צריך להרשאה מיוחדת.","","\u0003הניזקין שמין להן\u0004 הדיינים, לצורך גביית דמי ניזקם מן המזיק, בעידית (במובחר) שבנכסי המזיק, \u0003ובעל חוב\u0004 גובה את חובו \u0003בבינונית\u0004 של נכסי החייב לו, \u0003וכתובת אשה\u0004 נגבית \u0003בזיבורית\u0004 של נכסי הבעל. \u0003ר' מאיר אומר: אף כתובת אשה\u0004 נגבית \u0003בבינונית.\u0004","ועוד אמרו בענין זה של דרכי פרעון: \u0003אין נפרעין\u0004 לתשלום חוב ולשאר התחייבויות \u0003מנכסים משועבדים\u0004 (שכבר מכרם החייב לאדם אחר) \u0003במקום שיש\u0004 לחייב \u0003נכסים בני חורין\u0004 שאין עליהם שום שיעבוד אחר, \u0003ואפילו הן,\u0004 אותם נכסים בני חורין \u0003זיבורית.\u0004 שגם כאשר מן הדין היה צריך אותו חייב לפרוע מן העידית, והעידית משועבדת לו — מכל מקום נפרעים ממנו מנכסים בני חורין אפילו הם זיבורית. וכן \u0003אין נפרעין\u0004 חוב של האבות שמתו \u0003מנכסי יתומין אלא מן הזיבורית.\u0004","","ועוד אמרו: \u0003אין מוציאין\u0004 מן הגזלן \u0003לאכילת פירות ולשבח קרקעות,\u0004 שאם גזל שדה ומכרה לאחר, והקונה עבד בשדה והשביחה, וגדלו פירות בשדה, ולאחר זמן בא הנגזל ולקח את הקרקע והפירות שבה מן הקונה, הרי אותו קונה חוזר לגזלן לגבות ממנו את מה שהפסיד. ואינו גובה את הכל מנכסים משועבדים או מבני חורין דווקא, אלא שאת מה ששילם לגזלן עבור השדה מוציאים גם מנכסים משועבדים של הגזלן, אבל אין מוציאים מנכסי הגזלן לצורך פרעון דמי הפירות שנלקחו מן הקונה, וההשבחה שהשביח את השדה. \u0003ו\u0004כן אין מוציאים \u0003למזון האשה והבנות\u0004 שהוא מתנאי הכתובה שאדם מחייב עצמו לשלם מנכסיו לאשה ולבנות לאחר מותו לצורך מחייתן, \u0003מנכסים משועבדים\u0004, וכל התקנות הללו נעשו \u0003מפני תיקון העולם.\u0004 \u0003ו\u0004עוד אמרו: \u0003המוצא מציאה\u0004 — \u0003לא ישבע\u0004 שלא נטל ממנה כלום, \u0003מפני תיקון העולם.\u0004","הטעם במשנה \"מפני תיקון העולם\" מובן כמתייחס לכל הדברים במשנה זו. ושואלים: וכי מה שאמרו בראשית המשנה שהניזקים שמים להם בעידית \u0003מפני תיקון העולם\u0004 הוא? הלא \u0003דאורייתא היא\u0004 \u0005[מן התורה הוא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במזיק ממון חבירו: \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 (שמות כב, ד)!","","","\u0003אמר אביי: לא צריכא\u0004 \u0005[נצרכה]\u0006 אמירה זו שבמשנה \u0003אלא ל\u0004שיטת \u0003ר' ישמעאל,\u0004 ש\u0003אמר:\u0004 \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003ב\u0004נכסי ה\u0003ניזק\u0004 \u0003שיימינן\u0004 \u0005[אנו מעריכים]\u0006 ולפי ערך העידית שבנכסי הניזק משלם המזיק, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא במשנתנו ש\u0003מפני תיקון העולם שיימינן\u0004 \u0005[מעריכים אנו]\u0006 \u0003ב\u0004עידית שבנכסי ה\u0003מזיק\u0004 ולא לפי הניזק.","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 דבריו אלה של \u0003ר' ישמעאל\u0004 שרמז להם אביי? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 הכתוב \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 מובנו: \u0003מיטב שדהו\u0004 — \u0003של ניזק, ומיטב כרמו\u0004 — \u0003של ניזק,\u0004 שמשלם כפי העידית שבנכסי הניזק, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: לא בא הכתוב אלא לגבות לניזקין מן העידית\u0004 שבנכסי המזיק, אם אין לו מעות, \u0003וקל וחומר להקדש\u0004 שגובה מן העידית. ושואלים: \u0003ול\u0004דעת \u0003ר' ישמעאל,\u0004 אם \u0003אכל\u0004 (הזיק) המזיק מן הקרקע ה\u0003שמנה\u0004 (המשובחת) שבנכסי הניזק — \u0003משלם שמנה,\u0004 וגם אם \u0003אכל\u0004 מן הקרקע ה\u0003כחושה\u0004 — \u0003משלם שמנה?! אמר רב אידי בר אבין: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שאכלה\u0004 הבהמה המזיקה \u0003ערוגה בין הערוגות, ולא ידעינן\u0004 \u0005[ואין אנו יודעים]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כחושה אכל, אי\u0004 \u0005[אם]\u0006 \u0003שמנה אכל,\u0004 שבמקרה זה \u0003משלם ליה\u0004 \u0005[לו]\u0006 המזיק \u0003ממיטב\u0004 נכסיו.","","על כך מקשים: \u0003אמר רבא: אילו ידעינן\u0004 \u0005[אם היינו יודעים]\u0006 ש\u0003כחושה אכל\u0004 — היה \u0003משלם כחושה, השתא דלא ידעינן\u0004 \u0005[עכשיו שאין אנו יודעים]\u0006 \u0003משלם\u0004 דווקא \u0003שמנה?\u0004 הלא כלל הוא: \u0003המוציא מחברו עליו הראיה,\u0004 וכל עוד לא הביא הניזק ראיה שערוגה שמנה נאכלה לא יקבל מעידית! \u0003אלא אמר רב אחא בר יעקב:\u0004"],["\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 באופן שלאחר ששמו בית דין ויודעים בדיוק את ערך הנזק ובאים להיפרע מנכסי המזיק, וזה אין לו כסף מזומן לפרוע את מה שהזיק. ונחלקו במקרה \u0003כגון שהיתה עידית\u0004 של ה\u0003ניזק\u0004 שווה רק \u0003כזיבורית\u0004 של ה\u0003מזיק\u0004 ולמזיק יש גם עידית, ובמקרה זה \u0003ר' ישמעאל סבר: ב\u0004עידית של ה\u0003ניזק שיימינן\u0004 \u0005[אנו מעריכים]\u0006 ויכול המזיק לשלם לו מן הזיבורית שלו, \u0003ור' עקיבא סבר: ב\u0004עידית של ה\u0003מזיק שיימינן\u0004 \u0005[מעריכים אנו].\u0006","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל?\u0004 — \u0003נאמרה \"שדה\" למטה\u0004 (בסוף הפסוק) \"מיטב שדה ומיטב כרמו ישלם\" (שמות כב, ד) \u0003ונאמרה \"שדה\" למעלה\u0004 (בתחילת הפסוק) \"וביער בשדה אחר\", \u0003מה שדה האמורה למעלה\u0004 — היא שדהו של ה\u0003ניזק, אף שדה האמורה למטה\u0004 — של ה\u0003ניזק.\u0004","\u0003ור' עקיבא סבר:\u0004 מה שנאמר \u0003\"מיטב שדהו ישלם\"\u0004 כוונתו \u0003דהאיך דקא\u0004 \u0005[של זה שהוא]\u0006 \u0003משלם,\u0004 של המזיק.","\u0003ו\u0004מה משיב על כך \u0003ר' ישמעאל?\u0004 — \u0003אהני\u0004 \u0005[הועילה]\u0006 \u0003גזרה שוה\u0004 של \"שדה\" \"שדה\", \u0003ואהני קרא\u0004 \u0005[והועיל הכתוב]\u0006 עצמו; \u0003אהני\u0004 \u0005[הועילה]\u0006 \u0003גזרה שוה לכדאמרן\u0004 \u0005[לכפי שאמרנו],\u0006 ללמד שעידית הנכסים שמשלמים (\"מיטב שדהו\") כוונתה לשדה של ניזק. \u0003אהני קרא\u0004 \u0005[הועיל הכתוב]\u0006 שממנו משמע שמדובר בשדה המזיק, לדבר אחר; \u0003דאי אית ליה\u0004 \u0005[שאם יש לו]\u0006 \u0003למזיק עידית וזיבורית, וזיבורית דידיה\u0004 \u0005[שלו]\u0006 \u0003לא שויא\u0004 \u0005[אינה שווה,\u0006 טובה\u0005]\u0006 \u0003כעידית\u0004 של ה\u0003ניזק\u0004 — במקרה כזה \u0003משלם ליה\u0004 \u0005[לו]\u0006 \u0003ממיטב,\u0004 מעידית של המזיק.","שנינו בברייתא ש\u0003ר' עקיבא אומר: לא בא הכתוב\u0004 \"מיטב שדהו\" \u0003אלא לגבות לניזקין מן העידית\u0004 שבנכסי המזיק, אם אין לו מעות, \u0003וקל וחומר להקדש\u0004 שגובה מן העידית.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003קל וחומר\u0004 זה מנזיקין \u0003להקדש\u0004 ובאיזה מקרה מדובר כאן? \u0003אילימא דנגחיה תורא דידן לתורא\u0004 \u0005[אם תאמר שנגח שור שלנו,\u0006 של ישראל, \u0005לשור]\u0006 של \u0003הקדש\u0004 הרי \u0003\"\u0004וכי יגוף שור איש את \u0003שור רעהו\"\u0004 (שמות כא, לה) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 והדגש במילים \"שור רעהו\" הוא: \u0003ולא שור של הקדש,\u0004 ולפיכך אינו גובה כלום!","\u0003אלא\u0004 תאמר שאין מדובר לענין ניזקין, אלא \u0003לאומר \"הרי עלי מנה לבדק הבית\",\u0004 שאם אינו משלם בכסף, \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003גזבר\u0004 \u0003ושקיל\u0004 \u0005[ולוקח]\u0006 את תשלום המנה הזה \u0003מעידית\u0004 של קרקעו —","על כך יש להקשות: \u0003לא יהא\u0004 דינו של הגזבר \u0003אלא\u0004 כדין \u0003בעל חוב\u0004 הדיוט, \u0003ובעל חוב דינו\u0004 רק \u0003בבינונית!\u0004 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' עקיבא\u0004 שאף \u0003בעל חוב שקיל\u0004 \u0005[לוקח]\u0006 \u0003בעידית כניזקין\u0004 — גם אז \u0003איכא למיפרך\u0004 \u0005[יש לפרוך,\u0006 להקשות ולשבור\u0005]\u0006 את הקל וחומר הזה כך: \u0003מה לבעל חוב\u0004 הדיוט \u0003— שכן יפה\u0004 הכתוב \u0003כחו בניזקין,\u0004 שכיון שהדיוט הוא מקבל תשלום עבור נזק שהזיקו שורו של אחר, \u0003תאמר בהקדש שכן הורע כחו בניזקין\u0004 שאינו גובה כלל!","ודוחים: \u0003לעולם\u0004 תפרש שמדובר כאן \u0003דנגחיה תורא דידן לתורא\u0004 \u0005[שנגח שור שלנו את השור],\u0006 של \u0003הקדש\u0004 \u0003ור' עקיבא סבר לה\u0004 \u0005[סבור]\u0006 בענין זה \u0003כ\u0004שיטת \u0003ר' שמעון בן מנסיא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן מנסיא אומר: שור של הקדש שנגח לשור של הדיוט\u0004 — \u0003פטור, ו\u0004אולם שור \u0003של הדיוט שנגח לשור של הקדש, בין\u0004 שהיה השור הנוגח \u0003תם ובין\u0004 אם היה \u0003מועד\u0004 — בעל השור \u0003משלם נזק שלם.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 מדוע יש צורך להסיק ש\u0003ב\u0004מקרה שהיתה \u0003עידית\u0004 של ה\u0003ניזק כזיבורית\u0004 של ה\u0003מזיק פליגי\u0004 \u0005[חלוקים]\u0006 ר' עקיבא ור' ישמעאל, וכפי שהעמיד לעיל רב אחא בר יעקב? \u0003דלמא דכולי עלמא\u0004 \u0005[שמא ל\u0006דעת \u0005הכל],\u0006 ואף לדעת ר' עקיבא, \u0003ב\u0004עידית של ה\u0003ניזק שיימינן\u0004 \u0005[מעריכים אנו],\u0006 \u0003והכא בפלוגתא\u0004 \u0005[וכאן במחלוקת]\u0006 של \u0003ר' שמעון בן מנסיא ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006","ש\u0003ר' עקיבא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון בן מנסיא,\u0004 ולענין הקדש שניזוק על ידי הדיוט גובים מעידית של המזיק, \u0003ור' ישמעאל סבר לה כרבנן\u0004 \u0005[סבור כ\u0006דעת \u0005חכמים]\u0006 שאין בעל השור חייב להקדש כלום!","ודוחים: \u0003אם כן\u0004 אתה מפרש, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש דבריו של ר' עקיבא \u0003\"לא בא הכתוב\u0004 אלא לגבות לניזקין מן העידית \u0003\"?\u0004 שמשמע מן הדברים שעל פירוש הכתוב בא ר' עקיבא לחלוק. \u0003ועוד,\u0004 אם בהקדש מדברים, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"קל וחומר להקדש\"? ועוד, הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב אשי,\u0004"],["\u0003תניא בהדיא\u0004 \u0005[שנויה\u0006 ברייתא \u0005במפורש]:\u0006 כוונת הכתוב \u0003\"מיטב שדהו ומיטב כרמו ישלם\"\u0004 (שמות כב, ד) היא, \u0003\"מיטב שדהו\"\u0004 — \u0003של ניזק, \"ומיטב כרמו\"\u0004 — \u0003של ניזק,\u0004 אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: \"מיטב שדהו\"\u0004 — \u0003של מזיק \"ומיטב כרמו\"\u0004 — \u0003של מזיק.\u0004 משמע שדעת ר' עקיבא שגובים מעידית של המזיק!","\u0003רבינא אמר: לעולם מתניתין\u0004 \u0005[משנתנו]\u0006 כדעת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003ב\u0004של ה\u0003מזיק שיימינן\u0004 \u0005[אנו מעריכים],\u0006 \u0003ו\u0004שיטת \u0003ר' שמעון היא, דדריש טעמא דקרא\u0004 \u0005[שדורש\u0006 את \u0005טעם הכתוב],\u0006 \u0003ו\u0004בלשון \u0003\"מה טעם\"\u0004 קאמר \u0005[אמר].\u0006 וכך יש להבין: \u0003מה טעם הניזקין שמין להן בעידית?\u0004 — \u0003מפני תיקון העולם,\u0004 ש\"תיקון עולם\" זה אינו תקנת חכמים אלא הטעם לדין התורה בענין זה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' שמעון: מפני מה אמרו הניזקין שמין להן בעידית?\u0004 — \u0003מפני הגזלנים ומפני החמסנין,\u0004 ומדוע? — \u0003כדי שיאמר אדם: למה אני גוזל ולמה אני חומס? למחר בית דין יורדין לנכסי ונוטלין\u0004 דווקא \u0003שדה נאה\u0004 ביותר \u0003שלי\u0004 כתשלום על מה שגזלתי וחמסתי, \u0003וסומכים על מה שכתוב בתורה: \"מיטב שדהו ומיטב כרמו ישלם\", לפיכך אמרו: הניזקין\u0004 — \u0003שמין להן בעידית.\u0004","ועוד הוא מסביר: \u0003מפני מה אמרו בעל חוב\u0004 גובה \u0003בבינונית? כדי שלא יראה אדם לחבירו שדה נאה ודירה נאה, ויאמר: אקפוץ ואלונו כדי ש\u0004אחר כך, אם לא יהיה ביד הלווה כסף להחזיר ההלוואה \u0003אגבנו בחובי, לפיכך אמרו בעל חוב\u0004 גובה רק \u0003בבינונית,\u0004 ואותה שדה יפה שבגללה הילווה לו — לא יקבל.","ושואלים: \u0003אלא מעתה,\u0004 אם המטרה היא שלא יבואו אנשים להלוות כדי לגבות על ידי כך את נחלתם של אחרים, \u0003יהא\u0004 דינו של בעל חוב אם כן \u0003בזיבורית!\u0004 ומשיבים: \u0003אם כן\u0004 אתה עושה — \u0003אתה נועל דלת בפני לווין,\u0004 שלא ירצו המלווים להלוות להם.","\u0003כתובת אשה\u0004 — \u0003בזיבורית,\u0004 אלו \u0003דברי ר' יהודה, ר' מאיר אומר: בבינונית. אמר ר' שמעון: מפני מה אמרו כתובת אשה בזיבורית? שיותר ממה שהאיש רוצה לישא\u0004 אשה, \u0003האשה רוצה לינשא,\u0004 ומשום כך אין צריכים להקפיד שיהיה מה שמשלמים לה בכתובתה מן המין המשובח דווקא.","\u0003דבר אחר: אשה יוצאה\u0004 (מתגרשת) מבעלה \u0003לרצונה ושלא לרצונה, והאיש אינו מוציאה\u0004 (מגרשה) מביתו \u0003אלא לרצונו.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003דבר אחר?\u0004 מדוע היה צריך להוסיף עוד טעם אחר? ומשיבים: הדבר האחר בא להסביר בעיה שונה, שכיון שתיקנו חכמים כתובה כדי לשמור על שלימות הנישואין יש מקום לשאול: \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003כי היכי דכי מפיק לה איהו\u0004 \u0005[כמו שכאשר הוא מוציא אותה]\u0006 \u0003תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 \u0003כתובה\u0004 \u0003מיניה\u0004 \u0005[ממנו],\u0006 \u0003כי נפקא איהי נמי ליתקני ליה רבנן כתובה מינה\u0004 \u0005[כאשר יוצאת היא\u0006 מרצונה ש\u0005גם כן יתקנו לו חכמים כתובה ממנה]?\u0006 על כן, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003אשה יוצאה לרצונה ושלא לרצונה, והאיש אינו מוציא אלא לרצונו,\u0004 שגם אם תנסה לריב עימו כדי שיגרשנה, מכל מקום \u0003אפשר\u0004 לו לבעל \u0003דמשהי לה בגיטא\u0004 \u0005[שישהה אותה ב\u0006מתן \u0005הגט]\u0006 ונמצא שהוא נותן לה את הגט רק לכשירצה, והגירושין תלויים בעצם רק בו.","שנינו ש\u0003כתובת אשה בזיבורית. אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: לא אמרן\u0004 \u0005[אמרנו]\u0006 שגובה בזיבורית \u0003אלא\u0004 כאשר מת הבעל והיא באה לגבות כתובתה \u0003מיתמי\u0004 \u0005[מן היתומים]\u0006 היורשים, \u0003אבל\u0004 אם נתגרשה ובאה לגבות כתובתה \u0003מיניה דידיה\u0004 \u0005[ממנו עצמו]\u0006 — גובה \u0003בבינונית.\u0004","ושואלים: אם מדובר בגבייה \u0003מיתמי\u0004 \u0005[מיתומים],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003כתובת אשה? אפילו כל מילי נמי\u0004 \u0005[הדברים\u0006 כגון ניזקין, \u0005גם כן]\u0006 כגון ניזקין, גובים מיתומים מן הזיבורית, \u0003דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין נפרעים מנכסי יתומים אלא מן הזיבורית! אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן כשהיא גובה \u0003מיניה\u0004 \u0005[ממנו]\u0006 מן הבעל עצמו!","ודוחים: \u0003לעולם\u0004 תפרש שמדובר כאן שהיא גובה \u0003מיתמי\u0004 \u0005[מן היתומים],\u0006 \u0003ו\u0004בכל זאת \u0003כתובת אשה איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 להשמיענו במיוחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003משום חינא\u0004 \u0005[חן]\u0006 שרצו חכמים לעשות חן והקלה לנשים, \u0003אקילו רבנן גבה\u0004 \u0005[הקילו חכמים אצלה]\u0006 ונתנו לה זכות לגבות את כתובתה אפילו מן היתומים בבינונית, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו בכתובת אשה לא תיקנו כך.","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא, \u0003ר' מאיר אומר: כתובת אשה\u0004 — \u0003בבינונית.\u0004 ונברר: \u0003ממאן\u0004 \u0005[ממי]\u0006 מדובר כאן שגובים את הכתובה? \u0003אילימא מיתמי\u0004 \u0005[אם תאמר מן היתומים]\u0006 על כך יש להקשות: וכי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 \u0003לר' מאיר הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין נפרעים מנכסי יתומים אלא מן הזיבורית? אלא לאו מיניה\u0004 \u0005[האם לא\u0006 הכוונה כאשר האשה גובה \u0005ממנו,\u0006 מבעלה\u0005],\u0006 וכיון שר' מאיר אומר שגובה בבינונית — \u0003מכלל\u0004 הדבר אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 שגובה \u0003בזיבורית,\u0004 ושלא כדברי מר זוטרא!","ושוב דוחים: \u0003לא, לעולם\u0004 יכול אתה לפרש שמדובר שגובה \u0003מיתמי\u0004 \u0005[מיתומים],\u0006 \u0003ושאני\u0004 \u0005[ושונה]\u0006 \u0003כתובת אשה\u0004 משאר גובים מן היתומים שדינם בזיבורית, \u0003משום חינא\u0004 \u0005[חן],\u0006 שעל כן אמר ר' מאיר שגובה בינונית אפילו מן היתומים.","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003הניזקין שמין להן בעידית, ובעל חוב\u0004 — \u0003בבינונית, וכתובת אשה\u0004 — \u0003בזיבורית.\u0004 ומעתה נברר: \u0003ממאן\u0004 \u0005[ממי]\u0006 מדובר כאן שגובים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכל זה מדובר בגבייה \u0003מיתמי\u0004 \u0005[מיתומים],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 צויינה \u0003כתובת אשה? אפילו כל הני נמי\u0004 \u0005[כל אלה גם כן]\u0006 שאף ניזקים ובעלי חוב גובים מיתומים רק זיבורית! \u0003אלא לאו מיניה\u0004 \u0005[האם לא\u0006 מדובר שגובים \u0005ממנו]\u0006 זיבורית, ושלא כדברי מר זוטרא!","\u0003אמר רב אחא בר יעקב:\u0004 אין ממשנתנו ראיה כנגד מר זוטרא, שכן אפשר לדחות: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים]?\u0006 \u0003כגון שנעשה\u0004 האדם \u0003ערב לנזקי בנו,\u0004 וכן ערב \u0003לבעל חוב בנו, ו\u0004כן ערב \u0003לכתובת כלתו\u0004 אשת בנו, ומת בנו.","ומתוך שהערב עומד במקום בנו, יש לגבות ממנו כאילו היינו נפרעים מנכסי בנו, \u0003והאי כי דיניה והאי כי דיניה\u0004 \u0005[וזה כדינו וזה כדינו].\u0006 \u0003ניזקין ובעל חוב\u0004 ש\u0003מחיים גבו\u0004 \u0005[\u0006הם \u0005גובים]\u0006 כלומר, בחייו של הנתבע: המזיק או הלווה, \u0003איהו נמי כי מגבי\u0004 \u0005[הוא,\u0006 הערב, \u0005גם כן כאשר\u0006 הוא \u0005מגבה]\u0006 ומשלם להם \u0003כ\u0004אילו שהיה המזיק או הלווה \u0003מחיים\u0004 הוא \u0003מגבי\u0004 \u0005[מגבה],\u0006 בעידית או בבינונית. ואולם \u0003כתובת אשה\u0004 ש\u0003לאחר מיתה גביא\u0004 \u0005[\u0006היא \u0005גובה],\u0006 שהרי לא ניתן לגבות כתובה בחיי הבעל, \u0003ולאחר מיתה ממאן גביא\u0004 \u0005[ממי גובה]\u0006 — \u0003מיתמי\u0004 \u0005[מן היתומים],\u0006 \u0003איהו נמי\u0004 \u0005[הוא,\u0006 הערב, \u0005גם כן]\u0006 \u0003כי מגבי\u0004 \u0005[כאשר מגבה]\u0006 לה — \u0003כלאחר מיתה מגבי\u0004 \u0005[מגבה]\u0006 לה, מזיבורית.","ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא,\u0006 תילמד, \u0005לו]\u0006 אותה הלכה מהלכה אחרת הנקוטה בידינו, ש\u0003ערב\u0004 של כתובה \u0003לא משתעבד,\u0004 אין נכסיו משועבדים באמת לפרעון הכתובה, שאין חתימתו משמשת אלא כתוספת חיזוק, אבל לא כערבות ממש, ואם כן, אף אם גובים, לא יגבו אלא מן הפחות שבנכסים! ומשיבים: מדובר פה \u0003ב\u0004ערב שהיה \u0003קבלן,\u0004 שקיבל על עצמו לשלם את הכתובה על מנת שיינשא בנו.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קבלן אף על גב דלית ליה נכסי\u0004 \u0005[אף על פי שאין לו נכסים]\u0006 \u0003ללוה\u0004 הוא עצמו \u0003משתעבד\u0004 לתשלום ההלוואה, אם כן, \u0003שפיר\u0004 \u0005[יפה],\u0006 ניתן להעמיד כך את הדברים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 ללווה נכסים — \u0003משתעבד\u0004 הערב הקבלן, \u0003אי לית ליה\u0004 \u0005[אם אין לו]\u0006 — \u0003לא משתעבד,\u0004 אם כן, לשיטה זו, במקרה שאין לבנו רכוש, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והרי לא נשתעבד האב מעולם!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 מדובר \u0003בדהוו ליה ואישתדוף\u0004 \u0005[בשהיו לו\u0006 לבנו נכסים קודם \u0005ו\u0006אחר כך \u0005השתדפו,\u0006 התקלקלו\u0005]\u0006 שמתחילה שיעבד אביו עצמו כראוי כערב, אבל עכשיו אין לנכסים ערך, ומשום כך ניתן לגבות מן האב.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כל\u0004 דבר שהוא \u0003לגבי בריה\u0004 \u0005[בשביל בנו]\u0006 \u0003שעבודי משעבד נפשיה\u0004 \u0005[משעבד האב\u0006 את \u0005עצמו]\u0006 בשלימות, ואפילו כשאין לבן כל רכוש משלו.","מתוך שהזכרנו ענין ערבות בכתובה, מביאים: \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003ערב\u0004 החותם על ה\u0003כתובה\u0004 — \u0003דברי הכל לא משתעבד\u0004 בכך לגבות ממנו את הכתובה,"]]};
